"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[880],{5880:function(a,e,i){i.d(e,{C0:function(){return n},wN:function(){return h},az:function(){return t},e7:function(){return r},I9:function(){return s}});let r=[{id:"CANON-NIS-01",titleUrdu:"جنتی زیور",titleArabic:"الزيور الجناتي في فقه المرأة المسلمة",titleEnglish:"Jannati Zewar (The Heavenly Adornment)",authorUrdu:"شیخ الحدیث علامہ عبد المصطفیٰ اعظمی (رحمة الله عليه)",authorEnglish:"Shaykh al-Hadith Allama Abdul Mustafa Azmi (d. 1406 AH)",authorEra:"1406ھ / معاصر اکابرینِ اہل سنت",category:"fiqh_taharah",categoryLabelUrdu:"احکام و فقہِ نسواں",categoryLabelEnglish:"Fiqh & Purity for Women",descriptionUrdu:"اہل سنت و جماعت میں خواتین کے لیے سب سے جامع، مستند اور مقبول ترین انسائیکلوپیڈیا۔ اس میں صحیح اسلامی عقائد، نماز، طہارت، حیض و نفاس کے مسائل اور مثالی اسلامی گھریلو زندگی کو آسان اور دلنشین زبان میں بیان کیا گیا ہے۔",descriptionEnglish:"The premier comprehensive encyclopedia for Muslim women in Ahl al-Sunnah. Covers sound Sunni creed, modesty, prayer, comprehensive rulings on Haidh, Nifas, and moral character for the home.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-JANNATI-ZEWAR-AZMI-8819A",scholarlyConsensusUrdu:"جمہور علمائے اہل سنت کے نزدیک خواتین کے مسائل کے لیے نہایت قابلِ اعتماد اور مستند کتاب ہے۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://www.dawateislami.net/bookslibrary/ur/jannati-zewar",onlineArchiveName:"Maktaba-tul-Madina Official Research Desk (Jannati Zewar Complete)",coreChapters:[{chapterId:"jz-01",chapterNumber:1,titleUrdu:"حیض و نفاس کے بنیادی فقہی احکام",titleEnglish:"Fundamental Rulings of Haidh & Nifas",summaryUrdu:"حیض کی کم از کم مدت تین دن اور تین راتیں اور زیادہ سے زیادہ دس دن اور دس راتیں ہیں۔ اس دوران نماز معاف ہے اور روزہ بعد میں قضا رکھا جائے گا۔",summaryEnglish:"The minimum duration of Haidh in Hanafi fiqh is 3 days/nights and maximum 10 days/nights. Prayers are completely exempt and fasts are deferred.",hadithOrFiqhReference:"بہارِ شریعت، حصہ ۲ / درِ مختار و رد المحتار",keyTakeaways:["حیض کے دنوں میں نماز بالکل معاف ہے، اس کی قضا بھی لازم نہیں۔","روزوں کی قضا بعد میں رکھنا فرض ہے۔","قرآن مجید کی تلاوت اور چھونا منع ہے، البتہ ذکر و درود پڑھنا مستحب ہے۔"],fullTextUrdu:"حیض وہ خون ہے جو بالغہ عورت کے رحم سے بغیر کسی بیماری یا ولادت کے عادت کے مطابق نکلے۔ فقہ حنفی میں اس کی کم سے کم مدت پورے تین دن اور تین راتیں (یعنی ۷۲ گھنٹے) ہیں اور زیادہ سے زیادہ دس دن اور دس راتیں۔ حیض کی حالت میں نماز بالکل معاف ہے اور پاک ہونے کے بعد ان کی قضا بھی نہیں کرنی۔ البتہ رمضان کے روزوں کی قضا بعد میں رکھنا فرض ہے۔"},{chapterId:"jz-02",chapterNumber:2,titleUrdu:"خواتین کی نماز کی ہیئت اور سجدہ کی حیا",titleEnglish:"Modesty and Compact Posture in Women's Prayer",summaryUrdu:"خواتین کے لیے شریعت نے نماز میں مکمل پردہ اور سمٹ کر رہنے کا حکم دیا ہے، سجدے میں پیٹ رانوں سے اور بازو پہلو سے ملے رہیں۔",summaryEnglish:"In Hanafi jurisprudence, women adopt a compact, modest posture in prayer: keeping elbows to sides and body closely gathered.",hadithOrFiqhReference:"مراسیل ابی داؤد، حدیث رقم ۸۷ / الہدایہ",keyTakeaways:["تکبیر تحریمہ میں ہاتھ صرف کندھوں تک اٹھائے جائیں۔","سجدے میں بازو زمین سے ملائے جائیں اور پیٹ رانوں سے ملا رہے تاکہ مکمل ستر حاصل ہو۔","تشہد میں دونوں پاؤں دائیں جانب نکال کر بیٹھا جائے (تورک)۔"],fullTextUrdu:"شریعتِ مطہرہ نے عورت کے لیے نماز میں حیا اور ستر کو بنیاد بنایا ہے۔ تکبیر تحریمہ میں ہاتھ صرف سینے یا کندھوں تک چادر کے اندر سے اٹھائے جائیں۔ سجدے میں سمٹ کر سجدہ کرے، یعنی بازو زمین پر بچھا دے اور پیٹ کو رانوں سے چپکا لے۔ قعدہ میں تورک کرے یعنی دونوں پاؤں داہنی طرف نکال کر بائیں چوتڑ پر بیٹھے۔"},{chapterId:"jz-03",chapterNumber:3,titleUrdu:"عورتوں کے زیورات اور زکوٰۃ کے شرعی احکام",titleEnglish:"Zakat on Gold, Silver & Women's Jewelry",summaryUrdu:"فقہ حنفی میں عورت کے ملکیتی سونے اور چاندی کے زیورات پر زکوٰۃ فرض ہے اگر وہ نصاب (ساڑھے سات تولہ سونا یا ساڑھے باون تولہ چاندی) کو پہنچ جائیں اور سال گزر جائے۔",summaryEnglish:"In Hanafi fiqh, personal gold and silver jewelry owned by women is subject to 2.5% Zakat once reaching the Nisab threshold and completing one lunar year.",hadithOrFiqhReference:"سنن ابی داؤد، حدیث رقم ۱۵۶۳ / الہدایہ کتاب الزکاۃ",keyTakeaways:["استعمال کے زیورات ہوں یا رکھے ہوئے، حنفی مذہب میں دونوں پر زکوٰۃ واجب ہے۔","صرف سونا ہو تو ساڑھے سات تولہ (۸۷.۴۸ گرام) نصاب ہے۔","اگر سونا اور چاندی دونوں ملے جلے ہوں تو چاندی کے نصاب (۵۲.۵ تولہ = ۶۱۲.۳۶ گرام) کی قیمت کے اعتبار سے حساب کیا جائے گا۔","زکوٰۃ ادا کرنے کی شرعی ذمہ داری زیور کی مالکہ (عورت) پر ہے، شوہر اپنی خوشی سے ادا کرے تو جائز ہے۔"],fullTextUrdu:'حضرت عمرو بن شعیب اپنے والد سے اور وہ اپنے دادا سے روایت کرتے ہیں کہ ایک خاتون رسول اللہ ﷺ کی خدمت میں حاضر ہوئیں اور ان کی بیٹی کے ہاتھ میں سونے کے دو موٹے کنگن تھے۔ آپ ﷺ نے فرمایا: "کیا تم اس کی زکوٰۃ دیتی ہو؟" انہوں نے عرض کیا: نہیں! آپ ﷺ نے فرمایا: "کیا تمہیں یہ پسند ہے کہ قیامت کے دن اللہ تعالیٰ تمہیں ان کے بدلے آگ کے کنگن پہنائے؟" پس انہوں نے وہ فوراً اتار کر پیش کر دیے۔ فقہ حنفی کی تمام معتمد کتب (ہدایہ، رد المحتار، بہارِ شریعت) میں یہی راجح ہے کہ زیورات خواہ روزمرہ پہنے جاتے ہوں، سال مکمل ہونے پر ڈھائی فیصد زکوٰۃ نکالنا فرض ہے۔'},{chapterId:"jz-04",chapterNumber:4,titleUrdu:"خواتین کے روزے: حمل، رضاعت اور قضا کا طریقہ",titleEnglish:"Fasting Rulings for Women: Pregnancy, Nursing & Makeup Fasts",summaryUrdu:"حاملہ یا دودھ پلانے والی عورت کو اگر اپنی یا بچے کی جان یا صحت کے شدید نقصان کا اندیشہ ہو تو روزہ مؤخر کرنے کی اجازت ہے، بعد میں صرف قضا لازم ہوگی، کفارہ نہیں۔",summaryEnglish:"Pregnant and nursing mothers may defer fasting if there is genuine medical risk to mother or infant; only single-day makeup (Qadha) is owed later without expiation (Kaffarah).",hadithOrFiqhReference:"سنن الترمذی، حدیث رقم ৭১৫ / رد المحتار باب ما یفسد الصوم",keyTakeaways:["ماہر مسلمان طبیب یا ذاتی تجربے کی بنیاد پر اگر صحت کو خطرہ ہو تو روزہ نہ رکھنے کی رخصت ہے۔","ان دنوں کی بعد میں صحت یابی اور فراغت کے بعد ایک ایک روزہ قضا رکھنا لازم ہوگا۔","حیض کے چھوٹنے والے روزے بھی زندگی میں کسی بھی وقت قضا کیے جا سکتے ہیں، البتہ جلد ادا کرنا مستحب ہے۔","اگر کوئی عورت بڑھاپے یا دائمی مرض کے سبب زندگی بھر قضا رکھنے پر قادر نہ رہے تو وہ ہر روزے کا فدیہ (ایک صدقہ فطر کی مقدار) ادا کرے۔"],fullTextUrdu:'رسول اللہ ﷺ نے فرمایا: "بے شک اللہ تعالیٰ نے مسافر پر سے آدھی نماز معاف فرما دی، اور مسافر، حاملہ اور دودھ پلانے والی عورت پر سے روزے کی پابندی (اس وقت کے لیے) اٹھا لی ہے"۔ پس جو بہن حمل یا بچے کو دودھ پلانے کے زمانے میں کمزوری کی وجہ سے روزہ نہ رکھ سکے وہ گناہ گار نہیں ہوگی، بلکہ بعد کے مہینوں میں جب آسانی ہو قضا رکھ لے۔ اگر شوہر یا گھر والے بلاوجہ اصرار کریں جبکہ ڈاکٹر نے منع کیا ہو، تو شریعت کی رخصت پر عمل کرنا افضل ہے۔'},{chapterId:"jz-05",chapterNumber:5,titleUrdu:"نکاح، مہر کی شرعی ملکیت اور گھریلو حقوقِ زوجین",titleEnglish:"Nikah, Sanctity of Mahr & Mutual Domestic Rights",summaryUrdu:"مہر عورت کا خالص ذاتی حق اور شرعی ملکیت ہے جس میں شوہر یا سسرال والوں کا کوئی دخل نہیں، اور حسنِ معاشرت دونوں جانب سے واجب ہے۔",summaryEnglish:"Mahr is the exclusive divinely mandated financial right of the bride; neither husband nor in-laws may usurp it, and harmonious companionship is mutually binding.",hadithOrFiqhReference:"سورۃ النساء آیت ۴ / درِ مختار کتاب النکاح",keyTakeaways:['قرآن کریم کا صریح حکم ہے: "اور عورتوں کو ان کے مہر خوش دلی سے ادا کرو"۔',"مہر معاف کروانے کے لیے عورت پر کسی بھی قسم کا گھریلو دباؤ ڈالنا شرعاً باطل اور حرام ہے۔","نان و نفقہ، رہائش اور علاج معالجہ کا مکمل خرچہ شوہر کے ذمے ہے خواہ بیوی خود صاحبِ ثروت ہو۔","گھر کے اندر باہمی مشاورت، محبت اور درگزر سے زندگی گزارنا سنتِ نبوی ہے۔"],fullTextUrdu:'اسلام نے عورت کو وہ مالی خود مختاری اور عزت عطا فرمائی ہے جو دنیا کے کسی قانون نے نہیں دی۔ نکاح کے وقت مقرر کردہ مہر عورت کی ذاتی ملکیت ہے، وہ جس طرح چاہے اسے خرچ کرے یا محفوظ رکھے۔ شوہر کے ذمے نان و نفقہ، مناسب رہائش اور عزت دار سلوک واجب ہے۔ رسول اللہ ﷺ نے حجۃ الوداع کے موقع پر خطبہ دیتے ہوئے ارشاد فرمایا: "لوگو! عورتوں کے معاملے میں اللہ سے ڈرو، تم نے انہیں اللہ کی امان سے اپنی رفاقت میں لیا ہے، پس ان کے ساتھ بھلائی اور نرمی کا برتاؤ کرو"۔'},{chapterId:"jz-06",chapterNumber:6,titleUrdu:"خواتین کے اخلاق: غیبت، چغلی سے اجتناب اور زبان کی حفاظت",titleEnglish:"Moral Conduct for Women: Safeguarding the Tongue from Gheebah & Slander",summaryUrdu:"گھریلو فتنوں اور معاشرتی بگاڑ کی سب سے بڑی جڑ زبان کی بے احتیاطی ہے؛ غیبت، چغلی اور طعنہ زنی سے بچنا اور گھر میں درود و استغفار کی فضا بنانا باعثِ برکت ہے۔",summaryEnglish:"The primary cause of domestic discord is negligence of the tongue. Preserving one's speech from backbiting, gossiping, and harsh mockery creates angels of peace in the home.",hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۶۴۷۴ / ریاض الصالحین",keyTakeaways:['رسول اللہ ﷺ نے فرمایا: "مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں"۔',"سسرال، ہمسایوں یا رشتہ داروں کی چھوٹی موٹی باتوں کو دوسروں کے سامنے اچھالنا (چغلی) سخت گناہِ کبیرہ ہے۔","گھر کے کام کاج کرتے وقت زبان پر استغفار، درود شریف اور سبحان اللہ کا ورد رکھنا گھر میں سکینہ لاتا ہے۔","غصے کے وقت خاموشی اختیار کرنا اور معاف کر دینا اللہ کی بارگاہ میں اعلیٰ مقام دلاتا ہے۔"],fullTextUrdu:'سیدہ عائشہ صدیقہ رضی اللہ عنہا بیان فرماتی ہیں کہ میں نے ایک بار رسول اللہ ﷺ کے سامنے کسی کے چھوٹے قد کی طرف اشارہ کیا تو آپ ﷺ نے سخت ناراضگی کا اظہار کرتے ہوئے فرمایا: "عائشہ! تم نے ایسا کلمہ بولا ہے کہ اگر سمندر کے پانی میں ملا دیا جائے تو اس کا سارا پانی کڑوا ہو جائے!" پس ایک مسلمان بہن کا زیور صرف سونا چاندی نہیں بلکہ اس کی میٹھی، پاکیزہ زبان اور پاک دامن اخلاق ہے جو اس کے گھر کو جنت کا نمونہ بنا دیتا ہے۔'}]},{id:"CANON-NIS-02",titleUrdu:"بہارِ شریعت (حصہ احکامِ نسواں و طہارت)",titleArabic:"بهار شريعت - قسم أحكام النساء والطهور",titleEnglish:"Bahar-e-Shari'at (Volume on Women & Purity)",authorUrdu:"صدر الشریعہ مفتی محمد امجد علی اعظمی (رحمة الله عليه)",authorEnglish:"Sadr al-Shari'ah Mufti Amjad Ali Azmi (d. 1367 AH)",authorEra:"1367ھ / خلیفہ اعلیٰ حضرت امام احمد رضا خان",category:"fiqh_taharah",categoryLabelUrdu:"احکام و فقہِ نسواں",categoryLabelEnglish:"Fiqh & Purity for Women",descriptionUrdu:"برصغیر میں فقہ حنفی کا سب سے معتبر اور جامع ترین شاہکار۔ اس کا ہر فتویٰ فتاویٰ ہندیہ، درِ مختار اور فتاویٰ رضویہ سے مدلل ہے۔ خواتین کی طہارت کے انتہائی باریک مسائل اس میں نہایت دیانت سے درج ہیں۔",descriptionEnglish:"The supreme Hanafi legal compendium of the subcontinent, thoroughly verified from Fatawa Razawiyyah and al-Durr al-Mukhtar. The definitive reference for women's legal jurisprudence.",classicalSourceTier:"TIER_B_CLASSICAL_AUTHORITATIVE",sanadGrade:"SAHIH",verificationHash:"SHA256-BAHAR-E-SHARIAT-AMJADI-9921B",scholarlyConsensusUrdu:"فقہ حنفی میں برصغیر کا مستند ترین حوالہ، جس کے فتاویٰ پر تمام دار الافتاء اعتماد کرتے ہیں۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://www.dawateislami.net/bookslibrary/ur/bahar-e-shariat",onlineArchiveName:"Maktaba-tul-Madina (Bahar-e-Shari'at Complete 3 Volumes)",coreChapters:[{chapterId:"bs-01",chapterNumber:1,titleUrdu:"استحاضہ (بیماری کا خون) اور معذور کے احکام",titleEnglish:"Rulings on Istihadha and the Excused Person (Ma'dhur)",summaryUrdu:"تین دن سے کم یا دس دن سے زیادہ آنے والا خون استحاضہ ہے، اس میں نماز معاف نہیں بلکہ ہر نماز کے وقت کے لیے نیا وضو کر کے نماز پڑھنا لازم ہے۔",summaryEnglish:"Bleeding less than 3 days or more than 10 days is Istihadha. Prayer is NOT exempt; the sister makes Wudu for each prayer time and prays.",hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۳۲۴ (حدیث فاطمہ بنت ابی حبیش)",keyTakeaways:["استحاضہ بیماری ہے، اس میں نماز اور روزہ چھوڑنا جائز نہیں۔","ہر فرض نماز کے وقت کے داخل ہونے پر نیا وضو کیا جائے۔","اس حالت میں تلاوتِ قرآن اور کعبہ کا طواف باوضو جائز ہے۔"],fullTextUrdu:'رسول اللہ ﷺ نے حضرت فاطمہ بنت ابی حبیش رضی اللہ عنہا سے فرمایا: "یہ حیض نہیں بلکہ رگ کا خون (استحاضہ) ہے۔ جب حیض کے دن آئیں تو نماز چھوڑ دو اور جب وہ مدت گزر جائے تو غسل کر کے نماز پڑھو اور ہر نماز کے لیے وضو کرو۔" (صحیح بخاری)'},{chapterId:"bs-02",chapterNumber:2,titleUrdu:"غسل کے فرائض اور مینڈھیوں (چوٹیوں) کے احکام",titleEnglish:"Obligations of Ghusl & Rulings on Braided Hair",summaryUrdu:"غسل میں تین فرائض ہیں: کلی کرنا، ناک کی نرم ہڈی تک پانی پہنچانا اور پورے بدن پر پانی بہانا؛ گندھے بالوں والی عورت کے لیے چوٹیاں کھولنا واجب نہیں بشرطیکہ جڑوں تک پانی پہنچ جائے۔",summaryEnglish:"Ghusl has 3 obligatory acts: gargling mouth, rinsing nose to bone, and washing entirety of body. Braided hair does not need unbraiding if roots receive water.",hadithOrFiqhReference:"صحیح مسلم، حدیث رقم ۳۳۰ (حدیث ام سلمہ) / بہارِ شریعت حصہ ۲",keyTakeaways:["اگر بالوں کی جڑوں تک پانی پہنچ جائے تو چوٹیاں کھولنا فرض نہیں ہے۔","اگر بال کھلے ہوں تو ایک ایک بال کا دھونا فرض ہے۔","انگوٹھی، نتھ، بالیوں اور چوڑیوں کو ہلا کر نیچے پانی پہنچانا لازم ہے۔"],fullTextUrdu:'ام المؤمنین حضرت ام سلمہ رضی اللہ عنہا نے بارگاہِ رسالت ﷺ میں عرض کیا: "یا رسول اللہ! میں اپنے سر کے بال گوندھ کر رکھتی ہوں، کیا حیض اور جنابت کے غسل کے لیے انہیں کھولوں؟" آپ ﷺ نے فرمایا: "نہیں! تمہارے لیے صرف یہ کافی ہے کہ تم اپنے سر پر تین چلو پانی ڈال لو، پھر تمام بدن پر پانی بہا لو، تم پاک ہو جاؤ گی۔" صدر الشریعہ فرماتے ہیں: یہ رخصت صرف عورتوں کے لیے ہے اور اس شرط کے ساتھ ہے کہ بالوں کی جڑوں میں پانی پہنچ جائے۔'},{chapterId:"bs-03",chapterNumber:3,titleUrdu:"نفاس (ولادت کے بعد کا خون) اور چالیس دن کی شرعی حدود",titleEnglish:"Postnatal Bleeding (Nifas) & The 40-Day Maximum Ceiling",summaryUrdu:"نفاس کی زیادہ سے زیادہ مدت ۴۰ دن اور ۴۰ راتیں ہیں، کم کی کوئی حد نہیں۔ اگر خون ۴۰ دن سے پہلے رک جائے تو فوراً غسل کر کے نمازیں پڑھنا فرض ہے۔",summaryEnglish:"The absolute maximum limit for Nifas is 40 days; there is no minimum. If bleeding stops before 40 days, the mother must immediately perform Ghusl and resume Salah.",hadithOrFiqhReference:"جامع الترمذی، حدیث رقم ۱۳۹ / بہارِ شریعت حصہ ۲",keyTakeaways:["یہ عوامی وہم باطل ہے کہ ہر عورت پر ۴۰ دن پورے کرنا لازم ہے۔","خون ۱۰ یا ۲۰ دن میں رک جائے تو اسی وقت پاک شمار ہوگی اور غسل کر کے نماز شروع کرے۔","۴۰ دن سے زیادہ آنے والا خون استحاضہ ہے، اس میں غسل کر کے ہر نماز کے لیے وضو کرے گی۔"],fullTextUrdu:'سیدہ ام سلمہ رضی اللہ عنہا فرماتی ہیں: "رسول اللہ ﷺ کے مبارک زمانے میں نفاس والی خواتین چالیس دن تک انتظار کیا کرتی تھیں"۔ فقہ حنفی میں اس کی کم سے کم کوئی مدت نہیں، اگر ولادت کے بعد ایک گھنٹے میں بھی خون بند ہو جائے تو فوراً غسل کر کے نماز اور روزے شروع کرنا فرض ہے۔ چالیس دن کے بعد آنے والا خون استحاضہ (بیماری) ہے جس میں نماز نہیں چھوڑی جائے گی۔'},{chapterId:"bs-04",chapterNumber:4,titleUrdu:"طہارت کی حتمی علامات: قصۂ بیضاء اور سفیدی کا ظہور",titleEnglish:"Final Markers of Purity: White Discharge (Qassah Bayda) & Dryness",summaryUrdu:"عورت اس وقت پاک شمار ہوتی ہے جب پیڈ یا روئی پر خالص سفید رطوبت (قصۂ بیضاء) نظر آئے یا کپڑا بالکل سوکھا نکلے۔",summaryEnglish:"A woman is officially pure when white discharge (Qassah Bayda) appears or the cotton pad emerges completely clean and dry.",hadithOrFiqhReference:"صحیح البخاری، کتاب الحیض، تعلیقاً / بہارِ شریعت حصہ ۲",keyTakeaways:["جب تک زردی یا خاکی رنگت باقی ہے حیض ختم نہیں مانا جائے گا۔","سیدہ عائشہ نے فرمایا: جلدی نہ کرو جب تک سفید دھاگے کی طرح سفیدی نہ دیکھ لو۔","عادت کے دن پورے ہونے پر سفید رطوبت آتے ہی غسل کر لیا جائے۔"],fullTextUrdu:'حضرت عائشہ صدیقہ رضی اللہ عنہا کی خدمت میں خواتین روئی کے ٹکڑے بھیجتی تھیں جن پر پیلاہٹ ہوتی تھی، تو آپ فرماتی تھیں: "جلدی نہ کرو، یہاں تک کہ تم خالص سفید رطوبت (قصۂ بیضاء) نہ دیکھ لو"۔ پس جب تک سفید رطوبت ظاہر نہ ہو یا روئی بالکل خشک نہ نکلے، طہارت مکمل نہیں ہوتی۔'}]},{id:"CANON-NIS-03",titleUrdu:"فتاویٰ رضویہ (رسائلِ احکامِ نسواں و پردہ)",titleArabic:"فتاوى الرضوية - رسائل أحكام النساء والحجاب",titleEnglish:"Fatawa Razawiyyah (Treatises on Women's Rights & Hijab)",authorUrdu:"اعلیٰ حضرت امام احمد رضا خان بریلوی (رحمة الله عليه)",authorEnglish:"Imam Ahmad Raza Khan Barelvi (d. 1340 AH)",authorEra:"1340ھ / مجددِ دین و ملت",category:"fiqh_taharah",categoryLabelUrdu:"احکام و فقہِ نسواں",categoryLabelEnglish:"Fiqh & Purity for Women",descriptionUrdu:"اعلیٰ حضرت کے وہ نادر فقہی رسائل جن میں خواتین کے حقوقِ مہر، نان و نفقہ، عفت و حجاب کی شرعی حدود اور وراثت میں خواتین کا تحفظ قرآن و حدیث کے قوی دلائل سے ثابت کیا گیا ہے۔",descriptionEnglish:"Authoritative jurisprudential treatises demonstrating women's rights to mahr, inheritance, financial support, and the sacred boundaries of modesty from Quran and Sunnah.",classicalSourceTier:"TIER_B_CLASSICAL_AUTHORITATIVE",sanadGrade:"SAHIH",verificationHash:"SHA256-FATAWA-RAZAWIYYAH-NISWAN-7712C",scholarlyConsensusUrdu:"تحقیقی اور استدلالی لحاظ سے بے مثال فتاویٰ کا مجموعہ۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://www.dawateislami.net/bookslibrary/ur/fatawa-razawiyya",onlineArchiveName:"Maktaba-tul-Madina (Fatawa Razawiyyah Complete 30 Volumes)",coreChapters:[{chapterId:"fr-01",chapterNumber:1,titleUrdu:"عورت کا مالی خود مختاری اور مہر کا تحفظ",titleEnglish:"Financial Autonomy of Women & Sanctity of Mahr",summaryUrdu:"اسلام نے عورت کو اپنی ذاتی ملکیت، مہر اور وراثت میں مکمل مالی تصرف کا حق دیا ہے، شوہر یا باپ کے لیے اس کی مرضی کے بغیر لینا حرام ہے۔",summaryEnglish:"Islam guarantees full financial ownership for women over their wealth, Mahr, and inheritance; taking it without consent is strictly prohibited.",hadithOrFiqhReference:"فتاویٰ رضویہ، جلد ۱۲ / سورۃ النساء، آیت ۴",keyTakeaways:["مہر عورت کا خالص ذاتی حق ہے، اس پر کسی دوسرے کا حق نہیں۔","شریعت میں عورت کو اپنی حلال جائداد کی خود مختار مالکہ تسلیم کیا گیا ہے۔","عورت کی وراثت کو دبا لینا گناہِ کبیرہ اور جہنم کی وعید کا سبب ہے۔"],fullTextUrdu:'قرآن کریم نے واضح ارشاد فرمایا: "اور عورتوں کو ان کے مہر خوشی سے دو" (النساء: ۴)۔ امام احمد رضا خان فرماتے ہیں کہ عورت اپنے مہر اور ذاتی مال کی آزاد مالکہ ہے، شوہر اس کا محتاج نہیں ہو سکتا اور نہ ہی زبردستی معاف کروا سکتا ہے۔'},{chapterId:"fr-02",chapterNumber:2,titleUrdu:"خواتین کے حجاب اور ستر کی شرعی حدود",titleEnglish:"Canonical Boundaries of Modesty & Hijab for Muslim Women",summaryUrdu:"نامحرم مردوں کے سامنے چہرے اور پورے بدن کا پردہ لازم ہے؛ شریعت نے حیا کو عورت کا فطری اور دینی زیور قرار دیا ہے۔",summaryEnglish:"Full modesty before non-Mahram men is mandatory; classical jurisprudence establishes modesty as the inherent spiritual ornament of the believer.",hadithOrFiqhReference:'فتاویٰ رضویہ، جلد ۲۲، رسالہ "مسئلہ حجاب"',keyTakeaways:["فتنے کے دور میں نامحرم کے سامنے چہرہ چھپانا واجب ہے۔","باریک اور چست لباس پہننا جس سے جسم کے خدوخال ظاہر ہوں حرام ہے۔","خوشبو لگا کر غیر محرموں کے مجمع میں جانا سخت گناہ ہے۔"],fullTextUrdu:'اعلیٰ حضرت امام احمد رضا خان فرماتے ہیں: قرآن مجید میں ارشاد ہے: "اے نبی! اپنی بیویوں اور بیٹیوں اور مسلمانوں کی عورتوں سے فرما دیجیے کہ اپنے اوپر اپنی چادروں کا گھونگھٹ ڈال لیا کریں" (الاحزاب: ۵۹)۔ عورت کا وقار اور تقدس اس کے پردے میں مضمر ہے، اور سچے دل سے حجاب کی پابندی درحقیقت سیدہ فاطمۃ الزہراء رضی اللہ عنہا کی سنت کی پیروی ہے۔'},{chapterId:"fr-03",chapterNumber:3,titleUrdu:"وراثت میں بہنوں اور بیٹیوں کے حقوق کی سختی سے حفاظت",titleEnglish:"Protecting Daughters and Sisters Inheritance Rights from Coercion",summaryUrdu:'بہنوں یا بیٹیوں کو جائداد کے حصے سے محروم کرنا یا رسمی طور پر "معاف" کروانا شرعاً باطل اور حرامِ قطعی ہے۔',summaryEnglish:'Depriving daughters or sisters of their estate shares or coercing formal "forgiveness" is completely void and strictly prohibited.',hadithOrFiqhReference:"فتاویٰ رضویہ، جلد ۲۶، کتاب الفرائض",keyTakeaways:["وراثت اللہ تعالیٰ کا قطعی طے کردہ فریضہ ہے جس میں کوئی رشتہ دار کمی بیشی نہیں کر سکتا۔","بھائیوں کا بہنوں کا حصہ دبا لینا دوزخ کی آگ کھانا ہے۔","دباؤ کے تحت کروایا گیا معاف نامہ شریعت میں باطل ہے۔"],fullTextUrdu:'اعلیٰ حضرت لکھتے ہیں: روئے زمین پر سب سے بڑا ظلم یہ ہے کہ لوگ بیٹیوں اور بہنوں کا وراثت کا حصہ غصب کر لیتے ہیں اور حیلے بہانوں سے کہتے ہیں کہ "ہماری بہن نے معاف کر دیا"۔ یاد رکھو! جو معافی خاندانی دباؤ یا شرمندگی میں لی جائے وہ عند اللہ کالعدم ہے، اور ایسا کرنے والے قیامت کے دن سخت عذاب میں مبتلا ہوں گے۔'}]},{id:"CANON-NIS-04",titleUrdu:"اسلامی بہنوں کی نماز و طہارت",titleArabic:"صلاة وطهارة المرأة المسلمة وفق الفقه الحنفي",titleEnglish:"Salah and Taharah Guide for Muslim Sisters",authorUrdu:"تحقیقِ فقہائے اہل سنت و جماعت",authorEnglish:"Compiled by Jurists of Ahl al-Sunnah wal-Jama'ah",authorEra:"معاصر مستند تدوین",category:"fiqh_taharah",categoryLabelUrdu:"احکام و فقہِ نسواں",categoryLabelEnglish:"Fiqh & Purity for Women",descriptionUrdu:"آسان اور مرحلہ وار گائیڈ جس میں وضو، غسل، مخصوص ایام کی طہارت اور پانچوں نمازوں کا طریقہ باقاعدہ فقہی احکام کے ساتھ بیان کیا گیا ہے۔",descriptionEnglish:"A step-by-step practical manual for Wudu, Ghusl, menstrual purification, and the precise prayer method for women.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-SISTERS-SALAH-GUIDE-3312D",scholarlyConsensusUrdu:"مبتدی اور متوسط بہنوں کے لیے روزمرہ مسائل کا آسان و صحیح حل۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://www.dawateislami.net/bookslibrary/ur/islami-behno-ki-namaz",onlineArchiveName:"Maktaba-tul-Madina (Islami Behnon Ki Namaz Complete Edition)",coreChapters:[{chapterId:"ssg-01",chapterNumber:1,titleUrdu:"غسلِ حیض و طہارت کا مکمل مسنون طریقہ",titleEnglish:"Sunnah Method of Post-Menstrual Ghusl (Purification)",summaryUrdu:"طہارت کے غسل میں کلی کرنا، ناک میں نرم ہڈی تک پانی ڈالنا اور پورے بدن پر بال برابر بھی سوکھا نہ چھوڑنا فرض ہے۔",summaryEnglish:"The three obligatory acts (Fara'idh) of Ghusl: rinsing the mouth, cleansing the nose up to soft bone, and washing the entire body thoroughly.",hadithOrFiqhReference:"رد المحتار علی الدر المختار، باب الغسل",keyTakeaways:["غسل کے تین فرائض ہیں: کلی کرنا، ناک میں پانی چڑھانا، اور سارے بدن پر پانی بہانا۔","اگر بالوں کی مینڈھیاں (چوٹیاں) کھلی نہ ہوں تو جڑوں تک پانی پہنچانا ضروری ہے۔","ناخن پالش اگر جمی ہو تو اسے ہٹائے بغیر وضو اور غسل نہیں ہوگا۔"],fullTextUrdu:"جب حیض کا خون بند ہو جائے تو غسل فرض ہے۔ غسل میں پہلے استنجا کرے اور نجاست دھوئے، پھر نماز کا وضو کرے۔ اس کے بعد تین بار سر پر، تین بار دائیں اور تین بار بائیں کاندھے پر پانی بہائے۔ کلی کرنا اور ناک کی نرم ہڈی تک پانی پہنچانا فرض ہے۔"},{chapterId:"ssg-02",chapterNumber:2,titleUrdu:"وضو کے چار فرائض اور خواتین کی عام غلطیاں",titleEnglish:"Four Pillars of Wudu & Rectifying Common Female Errors",summaryUrdu:"پیشانی کے بالوں سے ٹھوڑی تک اور ایک کان کی لو سے دوسرے کان کی لو تک چہرہ دھونا، کہنیوں سمیت ہاتھ دھونا، چوتھائی سر کا مسح اور ٹخنوں سمیت پاؤں دھونا فرض ہے۔",summaryEnglish:"The four non-negotiable obligations of Wudu: washing entire face ear to ear, washing hands past elbows, wiping quarter head, washing feet with ankles.",hadithOrFiqhReference:"بہارِ شریعت، حصہ اول و دوم / قانونِ شریعت",keyTakeaways:["کان کی لو اور گلے کے قریب خشکی رہ جانے سے وضو نہیں ہوتا۔","آنکھوں کے کونوں میں کیچڑ یا کاجل کی پپڑی کو صاف کرنا ضروری ہے۔","ایڑیوں اور انگلیوں کے درمیانی خلا کو اچھی طرح تر کیا جائے۔"],fullTextUrdu:"فقہ حنفی میں وضو کے چار فرائض ہیں: (۱) چہرہ دھونا (پیشانی سے ٹھوڑی اور ایک کان سے دوسرے کان تک)، (۲) کہنیوں سمیت دونوں ہاتھ دھونا، (۳) چوتھائی سر کا مسح کرنا، (۴) ٹخنوں سمیت دونوں پاؤں دھونا۔ خواتین کو چاہیے کہ وضو کرتے وقت چوڑیوں اور انگوٹھیوں کو حرکت دیں تاکہ نیچے پانی پہنچ جائے، اور کاجل یا واٹر پروف میک اپ کی تہہ کو پہلے مکمل صاف کر لیں۔"},{chapterId:"ssg-03",chapterNumber:3,titleUrdu:"نماز میں ستر کے احکام اور دوپٹہ اوڑھنے کا طریقہ",titleEnglish:"Rules of Aurah in Prayer & Correct Dupatta/Scarf Coverage",summaryUrdu:"عورت کی نماز میں چہرہ، دونوں ہتھیلیاں اور پاؤں کے علاوہ پورا بدن چھپانا فرض ہے؛ بالوں کی ایک لٹ یا گردن کا چوتھائی حصہ بھی ایک رکن کی مقدار کھلا رہا تو نماز فاسد ہو جائے گی۔",summaryEnglish:"In prayer, the woman's entire body is Aurah except face, palms, and feet; if a quarter of the neck, ear, or hair remains exposed for one pillar duration, Salah is invalidated.",hadithOrFiqhReference:"سنن ابی داؤد، حدیث رقم ۶۴۱ / درِ مختار",keyTakeaways:["باریک دوپٹہ جس سے بالوں کی سیاہی چمکے نماز کے لیے ناکافی ہے۔","ٹھوڑی کے نیچے کا حصہ اور کلائیاں مکمل طور پر ڈھانپی ہونی چاہئیں۔","سجدے میں جاتے وقت اگر پچھلی طرف سے بال یا پیٹھ ننگی ہو گئی تو نماز ٹوٹ جائے گی۔"],fullTextUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "اللہ تعالیٰ کسی بالغہ عورت کی نماز بغیر اوڑھنی (خمار) کے قبول نہیں فرماتا" (سنن ابی داؤد)۔ پس بہنوں پر لازم ہے کہ نماز کے وقت موٹی چادر یا ایسا اسکارف استعمال کریں جس سے بال اور گردن بالکل نہ جھلکیں۔ اگر غفلت کی وجہ سے بال یا گلا کھل جائے اور فوراً نہ ڈھانپا جائے تو نماز کا لوٹانا فرض ہے۔'}]},{id:"CANON-NIS-05",titleUrdu:"حقوقِ زوجین و تحفۃ الزوجین",titleArabic:"حقوق الزوجين والتآلف الأسري",titleEnglish:"Marital Harmony and Mutual Rights in Islam",authorUrdu:"فقیہ ملت مفتی جلال الدین امجدی (رحمة الله عليه)",authorEnglish:"Mufti Jalaluddin Amjadi (d. 1422 AH)",authorEra:"1422ھ / مصنف انوار الحدیث و فتاویٰ فیض الرسول",category:"fiqh_taharah",categoryLabelUrdu:"احکام و فقہِ نسواں",categoryLabelEnglish:"Fiqh & Purity for Women",descriptionUrdu:"ازدواجی زندگی میں باہمی محبت، شوہر اور بیوی کے شرعی حقوق، ساس سسر کے احترام اور گھر کو جنت نظیر بنانے کا مستند اسلامی دستور۔",descriptionEnglish:"A classic guide to mutual respect, rights between spouses, and establishing spiritual tranquility in the home based on Quran and Hadith.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-HUQUQ-ZAWJAYN-AMJADI-4411E",scholarlyConsensusUrdu:"خاندانی استحکام اور گھریلو امن کے لیے اہل سنت کی انتہائی مفید کتاب۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Huquq+uz+Zawjain+Amjadi",onlineArchiveName:"Classical Sunnah Heritage Archive (Huquq-e-Zawjayn - Mufti Jalaluddin Amjadi)",coreChapters:[{chapterId:"hz-01",chapterNumber:1,titleUrdu:"گھر میں سکون اور باہمی حسنِ سلوک کے نبوی اصول",titleEnglish:"Prophetic Principles for Peace and Mutual Mercy at Home",summaryUrdu:"رسول اللہ ﷺ نے فرمایا: تم میں سب سے بہتر وہ ہے جو اپنے اہل و عیال کے لیے سب سے بہتر ہو، اور میں اپنے گھر والوں کے لیے تم سب سے بہتر ہوں۔",summaryEnglish:'The Prophet ﷺ stated: "The best of you are those who are best to their families, and I am the best among you to my family." (Tirmidhi)',hadithOrFiqhReference:"جامع الترمذی، حدیث رقم ۳۸۹۵ (حسن صحیح)",keyTakeaways:["گھر میں غصہ اور تلخی کے بجائے معافی اور درگزر کا مزاج اپنایا جائے۔","چھوٹی چھوٹی باتوں پر طعنے دینا گھر کی برکت کو ختم کر دیتا ہے۔","باہمی گفتگو میں نرمی اور پیار سنتِ نبوی ﷺ ہے۔"],fullTextUrdu:'رسولِ اکرم ﷺ نے اپنے مبارک گھرانے میں کبھی کسی پر ہاتھ نہیں اٹھایا اور نہ ہی کبھی بدکلامی فرمائی۔ آپ ﷺ نے فرمایا: "تم میں سب سے بہتر وہ ہے جو اپنے گھر والوں کے ساتھ سب سے اچھا سلوک کرے"۔ مفتی جلال الدین امجدی فرماتے ہیں کہ میاں بیوی کے درمیان جھگڑوں کا خاتمہ اس وقت ممکن ہے جب دونوں اپنے فرائض پر نظر رکھیں اور ایک دوسرے کی خطاؤں کو معاف کرنے کا حوصلہ پیدا کریں۔'},{chapterId:"hz-02",chapterNumber:2,titleUrdu:"بیوی کے واجب حقوق: نان و نفقہ، علاج اور عزت دار رہائش",titleEnglish:"The Inviolable Rights of the Wife: Maintenance, Healthcare & Dignity",summaryUrdu:"بیوی کا کھانا پینا، لباس، رہائش اور علاج کا مکمل خرچ شوہر کے ذمے شرعاً واجب ہے؛ اس میں کوتاہی کرنا سخت گناہ ہے۔",summaryEnglish:"A wife's sustenance, seasonal clothing, private accommodation, and medical expenses are strictly binding on the husband according to Islamic law.",hadithOrFiqhReference:"سنن ابی داؤد، حدیث رقم ۲۱۴۲ / درِ مختار کتاب النفقات",keyTakeaways:["شوہر پر فرض ہے کہ وہ اپنی استطاعت کے مطابق بیوی کو باعزت نفقہ دے۔","بیوی کو ایسا کمرہ دینا واجب ہے جس میں اس کا پردہ اور ذاتی سکون محفوظ ہو۔","بیوی کی بیماری میں علاج معالجہ کروانا شوہر کی اخلاقی اور شرعی ذمہ داری ہے۔"],fullTextUrdu:'حضرت معاویہ قشیری رضی اللہ عنہ نے رسول اللہ ﷺ سے دریافت کیا: "ہم پر ہماری بیوی کا کیا حق ہے؟" آپ ﷺ نے فرمایا: "جب تم کھاؤ تو اسے بھی کھلاؤ، جب تم پہنو تو اسے بھی پہناؤ، اس کے چہرے پر نہ مارو، اسے برا بھلا نہ کہو، اور گھر کے علاوہ اس سے قطع تعلق نہ کرو" (سنن ابی داؤد)۔ اسلام نے بیوی کو نوکرانی نہیں بلکہ گھر کی ملکہ اور سکون کا ذریعہ بنایا ہے۔'},{chapterId:"hz-03",chapterNumber:3,titleUrdu:"شوہر کے حقوق، خاندانی آداب اور ساس سسر کا احترام",titleEnglish:"Respect, In-Laws & Establishing Domestic Serenity",summaryUrdu:"شوہر کی جائز امور میں اطاعت اور اس کے والدین کا احترام عورت کے لیے باعثِ اجر و ثواب ہے، اور سسرال میں صبر و حکمت گھر کو جنت بناتی ہے۔",summaryEnglish:"Obedience in lawful matters and honoring in-laws with patience and wisdom earns divine reward and establishes lasting generational peace.",hadithOrFiqhReference:"صحیح ابن حبان، حدیث رقم ۴۱۶۳ / فتاویٰ فیض الرسول",keyTakeaways:["رسول اللہ ﷺ نے فرمایا: جس عورت نے ۵ وقت کی نماز پڑھی، رمضان کے روزے رکھے، پاکدامن رہی اور شوہر کی خیرخواہی کی وہ جس دروازے سے چاہے جنت میں داخل ہو جائے۔","ساس سسر کی خدمت اخلاقی اور نیکی کا اعلیٰ درجہ ہے جو نسلوں کو سنوارتا ہے۔","شوہر کے رازوں اور مال کی حفاظت کرنا نیک عورت کی نشانی ہے۔"],fullTextUrdu:'نبی کریم ﷺ نے ارشاد فرمایا: "اگر عورت پانچوں وقت کی نماز پڑھے، اپنے مہینے کے روزے رکھے، اپنی عفت کی حفاظت کرے اور اپنے شوہر کی اطاعت کرے، تو اس سے کہا جائے گا کہ جنت کے جس دروازے سے چاہے داخل ہو جا"۔ فقیہ ملت فرماتے ہیں کہ سسرال والوں کے ساتھ شفقت اور درگزر سے پیش آنا گھر میں محبت کی بنیاد ہے اور یہی وہ صفت ہے جو مومنہ عورت کو دنیا اور آخرت میں معزز بناتی ہے۔'}]},{id:"CANON-NIS-06",titleUrdu:"السيدة خديجة الكبرى أم المؤمنين",titleArabic:"السيدة خديجة الكبرى: أم المؤمنين وسيدة نساء العالمين",titleEnglish:"Sayyidatuna Khadijah al-Kubra: Mother of the Believers",authorUrdu:"محدث الحرمین سید محمد بن علوی المالکی الحسنی (رحمة الله عليه)",authorEnglish:"Sayyid Muhammad ibn Alawi al-Maliki al-Hasani (d. 1425 AH)",authorEra:"1425ھ / شیخ الحدیث مکہ مکرمہ",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"مکہ مکرمہ کے جلیل القدر محدث کا وہ نفیس شاہکار جس میں ام المؤمنین حضرت خدیجہ الکبریٰ رضی اللہ عنہا کی پہلی تصدیق، اسلام کے ابتدائی ایام کی قربانیاں اور اللہ تعالیٰ کی جانب سے سلام کا پیغام لانے کی فضیلتیں قلمبند کی گئی ہیں۔",descriptionEnglish:"The sublime Makkan masterwork chronicling the first believer, her profound business wisdom, unwavering emotional solace to the Prophet ﷺ, and the divine greeting delivered by Jibril (عليه السلام).",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"SAHIH",verificationHash:"SHA256-KHADIJAH-AL-KUBRA-MALIKI-5512F",scholarlyConsensusUrdu:"عالمِ اسلام کے اکابر محدثین کے نزدیک انتہائی پرتاثیر اور ثقہ تصنیف۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Sayyidah+Khadijah+Alawi+Maliki",onlineArchiveName:"Makkan Classical Archives (Al-Sayyidah Khadijah al-Kubra - Sayyid Muhammad Alawi al-Maliki)",coreChapters:[{chapterId:"sk-01",chapterNumber:1,titleUrdu:"نزولِ وحی پر سیدتنا خدیجہ کی تسلی اور الٰہی سلام",titleEnglish:"Solace at the First Revelation and the Divine Salutation",summaryUrdu:"جب غارِ حرا میں پہلی وحی آئی تو سیدتنا خدیجہ نے فرمایا: ہرگز نہیں! اللہ آپ کو کبھی رسوا نہیں کرے گا، آپ تو صلہ رحمی کرتے ہیں اور بے سہاروں کا بوجھ اٹھاتے ہیں۔",summaryEnglish:'When the first revelation came, Sayyidatuna Khadijah comforted the Prophet ﷺ: "Never! By Allah, Allah will never disgrace you. You uphold ties of kinship and carry the burden of the weak." (Bukhari)',hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۳ / صحیح مسلم، حدیث رقم ۱۶۰",keyTakeaways:["سیدتنا خدیجہ نے نبوت کی سب سے پہلے تصدیق کی اور اپنا سارا مال اسلام کے لیے پیش کر دیا۔",'حضرت جبرائیل علیہ السلام نے آ کر فرمایا: "یا رسول اللہ! خدیجہ کو ان کے رب کا اور میرا سلام کہیے۔"',"جنت میں سیدتنا خدیجہ کے لیے موتیوں کا ایک ایسا محل تیار ہے جہاں نہ کوئی شور ہوگا نہ کوئی مشقت۔"],fullTextUrdu:"سیدتنا خدیجہ الکبریٰ رضی اللہ عنہا نہ صرف اسلام کی پہلی مؤمنہ تھیں بلکہ رسول اللہ ﷺ کی وہ رفیقۂ حیات تھیں جنہوں نے ہر کڑے وقت میں ڈھارس بندھائی۔ اللہ تعالیٰ نے خود حضرت جبرائیل علیہ السلام کے ذریعے ان کے لیے سلام کا تحفہ بھیجا، جو تمام کائنات کی خواتین میں منفرد شرف ہے۔"}]},{id:"CANON-NIS-07",titleUrdu:"الإجابة فیما استدركته عائشة على الصحابة",titleArabic:"الإجابة لإيراد ما استدركته عائشة على الصحابة",titleEnglish:"Al-Ijabah: Sayyidatuna Aisha's Juristic Corrections",authorUrdu:"امام بدر الدین زرکشی و امام جلال الدین سیوطی (رحمة الله عليهما)",authorEnglish:"Imam Badr al-Din al-Zarkashi (d. 794 AH) & Imam al-Suyuti",authorEra:"794ھ / 911ھ — کبار ائمۂ حدیث و اصول",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"تاریخِ اسلام کا وہ بے نظیر کلاسیکل شاہکار جس میں ثابت کیا گیا ہے کہ سیدتنا عائشہ صدیقہ رضی اللہ عنہا نے کس طرح کبار صحابہ کرام کے فتاویٰ اور روایات کی فقہی اور علمی تصحیح فرمائی۔ یہ کتاب خواتین کی عظیم فقہی اور اجتہادی صلاحیت کا روشن ثبوت ہے۔",descriptionEnglish:"The historic classical Arabic masterwork demonstrating the peerless juristic intellect, critical Hadith analysis, and corrections that Sayyidatuna Aisha Siddiqah provided to senior companions.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"SAHIH",verificationHash:"SHA256-AL-IJABAH-ZARKASHI-SUYUTI-6612G",scholarlyConsensusUrdu:"تمام محدثین کے نزدیک ام المؤمنین عائشہ کے فقہی مقام کو سمجھنے کے لیے بنیادی کلاسیکی ماخذ ہے۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://shamela.ws/book/8381",onlineArchiveName:"Al-Maktaba al-Shamela (Al-Ijabah - Imam al-Zarkashi & al-Suyuti)",coreChapters:[{chapterId:"ai-01",chapterNumber:1,titleUrdu:"سیدتنا عائشہ کا اجتہاد اور علمی عبقریت",titleEnglish:"The Ijtihad and Juristic Genius of Sayyidatuna Aisha",summaryUrdu:"حضرت ابو موسیٰ اشعری رضی اللہ عنہ فرماتے ہیں: ہم صحابہ پر جب بھی کوئی مشکل حدیث یا مسئلہ پیش آتا، ہم سیدتنا عائشہ سے پوچھتے تو ان کے پاس اس کا علم موجود پاتے۔",summaryEnglish:'Abu Musa al-Ash\'ari reported: "Whenever a matter became difficult for us, the companions of the Prophet ﷺ, we asked Aisha and found knowledge with her." (Tirmidhi)',hadithOrFiqhReference:"جامع الترمذی، حدیث رقم ۳۸۸۳ (حدیث صحیح غریب)",keyTakeaways:["سیدتنا عائشہ نے ۲,۲۱۰ سے زائد احادیثِ مبارکہ روایت فرمائیں۔","وہ علمِ میراث، طب، فقہ اور انساب و اشعار کی سب سے بڑی عالمہ تھیں۔","کبار صحابہ جیسے حضرت عمر اور حضرت عثمان رضی اللہ عنہم ان کے فتاویٰ کی طرف رجوع فرماتے تھے۔"],fullTextUrdu:'امام زہری رحمہ اللہ فرماتے ہیں: "اگر تمام لوگوں کا علم اور تمام ازواجِ مطہرات کا علم جمع کیا جائے تو عائشہ صدیقہ رضی اللہ عنہا کا علم ان سب سے وسیع تر نکلے گا۔" آپ نے دین کی گہری باریکیوں کو احادیث اور عقلِ سلیم کی روشنی میں واضح فرمایا۔'}]},{id:"CANON-NIS-08",titleUrdu:"سیرتِ سیدتنا عائشہ صدیقہ",titleArabic:"سيرة الصديقة الطاهرة عائشة أم المؤمنين",titleEnglish:"Biography of Sayyidatuna Aisha Siddiqah",authorUrdu:"علامہ مفتی فیض احمد اویسی (رحمة الله عليه)",authorEnglish:"Allama Mufti Faiz Ahmad Owaisi (d. 1431 AH)",authorEra:"1431ھ / بہاولپور، محققِ اہل سنت",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"اردو زبان میں سیدتنا عائشہ کی حیاتِ طیبہ کا انتہائی عاشقانہ اور مدلل تذکرہ۔ واقعہ افک میں قرآن پاک کی سترہ آیات کے ذریعے براءت کا نزول، عبادت گزاری اور امت کے لیے علمی فیضان کو جامعیت سے سمیٹا گیا ہے۔",descriptionEnglish:"An exhaustive, devotional Urdu biography of the Mother of the Believers: her Divine exoneration in Surah an-Nur, nocturnal worship, and lifelong pedagogy.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-SEERAT-AISHA-OWAISI-7711H",scholarlyConsensusUrdu:"اہل سنت کے ہاں ازواجِ مطہرات کی پاکیزگی اور عظمت کو اجاگر کرنے کے لیے معتبر تالیف۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Seerat+Hazrat+Aisha+Owaisi",onlineArchiveName:"Sunni Classical Heritage (Seerat Hazrat Aisha Siddiqah - Mufti Faiz Ahmad Owaisi)",coreChapters:[{chapterId:"sa-01",chapterNumber:1,titleUrdu:"براءتِ عائشہ اور سورۃ النور کی آیات کا نزول",titleEnglish:"The Divine Exoneration of Aisha in Surah An-Nur",summaryUrdu:"منافقین کے بہتان کے جواب میں اللہ تعالیٰ نے آسمانوں سے سیدتنا عائشہ کی طہارت و پاکیزگی کی گواہی کے لیے قرآن پاک کی ۱۰ آیات نازل فرمائیں۔",summaryEnglish:"In response to the slanders of the hypocrites, Allah revealed 10 verses of Surah An-Nur directly exonerating Sayyidatuna Aisha for all eternity.",hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۴۷۵۰ / سورۃ النور، آیات ۱۱-۲۱",keyTakeaways:["سیدتنا عائشہ صدیقہ کی براءت قرآن کا حصہ ہے، جس پر ایمان رکھنا لازم ہے۔","رسول اللہ ﷺ کی زوجیتِ مطہرہ دنیا اور آخرت دونوں میں حضرت عائشہ کے لیے ثابت ہے۔","آپ کی سخاوت کا عالم یہ تھا کہ ایک دن میں ایک لاکھ درہم صدقہ کر دئے اور خود روزے سے رہیں۔"],fullTextUrdu:'سیدتنا عائشہ رضی اللہ عنہا نے مصیبت کے وقت فرمایا: "واللہ! میں صرف وہی کہتی ہوں جو حضرت یوسف علیہ السلام کے والد نے فرمایا تھا: فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ۔" پس اللہ تعالیٰ نے عرش سے ان کی پاکیزگی پر کلام نازل فرما دیا۔'}]},{id:"CANON-NIS-09",titleUrdu:"ثغور الباسم في مناقب سيدتنا فاطمة الزهراء",titleArabic:"ثغور الباسم في مناقب سيدتنا فاطمة الزهراء البتول",titleEnglish:"Thughur al-Basim: The Virtues of Sayyidatuna Fatimah az-Zahra",authorUrdu:"امام جلال الدین سیوطی (رحمة الله عليه)",authorEnglish:"Imam Jalal al-Din al-Suyuti (d. 911 AH)",authorEra:"911ھ / قاہرہ، امام الحدیث والتفسیر",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"امام سیوطی کا وہ مستند رسالہ جس میں سیدۃ نساء اہل الجنہ حضرت فاطمۃ الزہراء رضی اللہ عنہا کے مناقب، بضعۃ منی کا شرف اور آپ کے خصائص کو صحیح روایات سے جمع کیا گیا ہے۔",descriptionEnglish:"Imam al-Suyuti's verified treatise collecting the singular spiritual virtues, asceticism, and station of the Leader of the Women of Paradise.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"SAHIH",verificationHash:"SHA256-THUGHUR-AL-BASIM-SUYUTI-8812I",scholarlyConsensusUrdu:"مناقبِ اہل بیت اور سیدہ زہراء کی سیرت کے لیے متفقہ کلاسیکی مرجع۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Thughur+al-Basim+Suyuti",onlineArchiveName:"Al-Maktaba al-Shamela (Thughur al-Basim - Imam Jalal al-Din al-Suyuti)",coreChapters:[{chapterId:"tb-01",chapterNumber:1,titleUrdu:"فاطمہ میرے جگر کا ٹکڑا ہے (فاطمة بضعة مني)",titleEnglish:"Fatimah is a Part of Me: The Highest Prophetic Kinship",summaryUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "فاطمہ میرے جگر کا ٹکڑا ہے، جس نے اسے ناراض کیا اس نے مجھے ناراض کیا اور جس نے اسے خوش کیا اس نے مجھے خوش کیا۔"',summaryEnglish:'The Prophet ﷺ proclaimed: "Fatimah is a part of me; whoever angers her angers me, and whoever pleases her pleases me." (Sahih al-Bukhari)',hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۳۷۱۴ / صحیح مسلم، حدیث رقم ۲۴۴۹",keyTakeaways:["سیدہ فاطمہ جنت کی تمام عورتوں کی سردار ہیں۔","جب بھی رسول اللہ ﷺ کے پاس تشریف لاتیں، حضور ان کے احترام میں کھڑے ہو جاتے اور پیشانی پر بوسہ دیتے۔","آپ کی سیرت زہد، قناعت اور راتوں کی طویل عبادات کا بے مثل نمونہ ہے۔"],fullTextUrdu:"سیدہ بتول فاطمۃ الزہراء رضی اللہ عنہا حسن و اخلاق اور نشست و برخاست میں اپنے بابا حضور رحمتِ عالم ﷺ کے سب سے زیادہ مشابہ تھیں۔ گھر کی چکی خود پیستیں حتیٰ کہ ہاتھوں میں چھالے پڑ جاتے، لیکن زبان پر ہر دم شکرِ الٰہی جاری رہتا۔"}]},{id:"CANON-NIS-10",titleUrdu:"سیرتِ سیدۃ النساء فاطمۃ الزہراء",titleArabic:"سيرة سيدة نساء أهل الجنة فاطمة الزهراء",titleEnglish:"Seerat Sayyidat an-Nisa Fatimah az-Zahra",authorUrdu:"علامہ مفتی فیض احمد اویسی (رحمة الله عليه)",authorEnglish:"Allama Mufti Faiz Ahmad Owaisi (d. 1431 AH)",authorEra:"1431ھ / بہاولپور",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"سیدہ پاک کی ولادت، بچپن، مکہ میں حضور ﷺ کا دفاع، شادی، سادگی، حسنین کریمین کی تربیت اور وصالِ نبوی پر غم کی کیفیات کا جامع احاطہ۔",descriptionEnglish:"Comprehensive biographical survey of Sayyidatuna Fatimah: her childhood defending the Prophet in Makkah, marriage to Ali (رضي الله عنه), and nurturing the Hasani-Husayni lineage.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-SEERAT-FATIMAH-OWAISI-9912J",scholarlyConsensusUrdu:"اہل سنت کے ہاں حسنین کریمین کی والدہ ماجدہ کی سیرت پر مستند تالیف۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Seerat+Sayyidah+Fatimah+Owaisi",onlineArchiveName:"Sunni Classical Heritage (Seerat Sayyidat an-Nisa Fatimah - Mufti Faiz Ahmad Owaisi)",coreChapters:[{chapterId:"sf-01",chapterNumber:1,titleUrdu:"سیدہ فاطمہ کا بچپن اور کعبہ میں حضور ﷺ کی نصرت",titleEnglish:"Childhood Devotion: Defending the Prophet at the Ka'bah",summaryUrdu:"جب قریش کے شریروں نے سجدے کی حالت میں حضور ﷺ پر اوجھڑی ڈالی، تو سیدہ فاطمہ نے کمسنی میں آ کر اسے ہٹایا اور مشرکین کو للکارا۔",summaryEnglish:"When the Quraysh placed filth upon the back of the Prophet ﷺ while in Sujud, the young Fatimah rushed forward, removed it, and rebuked them bravely.",hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۲۴۰ / صحیح مسلم، حدیث رقم ۱۷۹۴",keyTakeaways:["سیدہ فاطمہ کم عمری سے ہی دینِ حق اور اپنے والد گرامی کی محافظہ تھیں۔","رسول اللہ ﷺ کو ان سے اتنی محبت تھی کہ سفر پر جاتے وقت سب سے آخر میں ان سے رخصت ہوتے اور واپسی پر سب سے پہلے ان کے ہاں تشریف لاتے۔"],fullTextUrdu:'سیدہ پاک بچپن سے ہی شجاعت، وفاداری اور محبت کا پیکر تھیں۔ جب کفار مکہ نے ایذا رسانی کی انتہا کر دی، تو اس کمسن شہزادی نے تن تنہا اپنے والدِ ماجد کی دیکھ بھال کی، اسی لیے آپ کو "ام ابیہا" (اپنے باپ کی ماں) کا لقب ملا۔'}]},{id:"CANON-NIS-11",titleUrdu:"بناتِ مصطفیٰ ﷺ",titleArabic:"بنات النبي صلى الله عليه وسلم وسيرتهن العطرة",titleEnglish:"Banat-e-Mustafa: The Four Daughters of the Prophet ﷺ",authorUrdu:"علامہ عبد المصطفیٰ اعظمی (رحمة الله عليه)",authorEnglish:"Allama Abdul Mustafa Azmi (d. 1406 AH)",authorEra:"1406ھ / مصنف سیرتِ مصطفیٰ",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"اہل سنت و جماعت کے عقیدے کے مطابق رسول اللہ ﷺ کی چاروں صاحبزادیوں (سیدتنا زینب، سیدتنا رقیہ، سیدتنا ام کلثوم، اور سیدتنا فاطمۃ الزہراء رضی اللہ عنہن) کے مستند حالات اور خدمات۔",descriptionEnglish:"Biographical masterwork on all four noble daughters of the Prophet ﷺ (Zainab, Ruqayyah, Umm Kulthum, and Fatimah az-Zahra) in authentic Ahl al-Sunnah tradition.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"SAHIH",verificationHash:"SHA256-BANAT-MUSTAFA-AZMI-1101K",scholarlyConsensusUrdu:"اہل سنت کے ہاں چاروں بناتِ رسول کے احوال پر متفقہ اور مستند کتاب۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Banat+e+Mustafa+Azmi",onlineArchiveName:"Ahl al-Sunnah Digital Heritage (Banat-e-Mustafa ﷺ - Allama Abdul Mustafa Azmi)",coreChapters:[{chapterId:"bm-01",chapterNumber:1,titleUrdu:"سیدتنا زینب، رقیہ اور ام کلثوم کے فضائل",titleEnglish:"Virtues and Sacrifices of Zainab, Ruqayyah, and Umm Kulthum",summaryUrdu:'سیدتنا رقیہ اور ام کلثوم یکے بعد دیگرے حضرت عثمان غنی رضی اللہ عنہ کے نکاح میں آئیں، جس کی بنا پر حضرت عثمان کو "ذو النورین" (دو نوروں والا) کہا گیا۔',summaryEnglish:"Sayyidatuna Ruqayyah and Umm Kulthum were wed sequentially to Uthman ibn Affan (رضي الله عنه), granting him the title Dhu an-Nurayn (Possessor of Two Lights).",hadithOrFiqhReference:"صحیح البخاری، کتاب الفضائل / مدارج النبوۃ",keyTakeaways:["رسول اللہ ﷺ کی چار بیٹیاں تھیں اور چاروں سے حضور ﷺ بے پناہ پیار فرماتے تھے۔","سیدتنا رقیہ نے حبشہ اور مدینہ کی دونوں ہجرتوں کا ثواب پایا۔","سیدتنا ام کلثوم کے وصال پر حضور ﷺ نے فرمایا: اگر میری تیسری بیٹی بھی ہوتی تو میں عثمان کے نکاح میں دے دیتا۔"],fullTextUrdu:"اہل سنت کا مسلّم عقیدہ ہے کہ سرکارِ دو عالم ﷺ کی چاروں بیٹیاں نورِ نبوت کی روشن شمعیں ہیں۔ سیدتنا زینب کی قربانیاں ہجرت کے موقع پر تاریخ کا درخشندہ باب ہیں۔"}]},{id:"CANON-NIS-12",titleUrdu:"سیدتنا حلیمہ سعدیہ رضی اللہ عنہا",titleArabic:"السيدة حليمة السعدية مرضعة خير البرية",titleEnglish:"Sayyidatuna Halimah al-Sa'diyyah: The Blessed Foster Mother",authorUrdu:"علامہ مفتی فیض احمد اویسی (رحمة الله عليه)",authorEnglish:"Allama Mufti Faiz Ahmad Owaisi (d. 1431 AH)",authorEra:"1431ھ / بہاولپور",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"حضور اقدس ﷺ کی رضاعی والدہ سیدتنا حلیمہ سعدیہ رضی اللہ عنہا کے قبیلہ بنو سعد میں آمد، اونٹنی اور بکریوں کے دودھ کی برکتیں اور شقِ صدر کے ایمان افروز واقعات۔",descriptionEnglish:"The life of the Prophet's foster mother, the miraculous blessings that filled Banu Sa'd upon his arrival, and her noble status.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"HASAN",verificationHash:"SHA256-HALIMAH-SAADIYYAH-OWAISI-2202L",scholarlyConsensusUrdu:"حضور ﷺ کی رضاعت اور برکاتِ نبوی کے حوالے سے نہایت مقبول کتاب۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Hazrat+Halima+Sadia+Owaisi",onlineArchiveName:"Sunni Classical Heritage (Sayyidatuna Halimah al-Sa'diyyah - Mufti Faiz Ahmad Owaisi)",coreChapters:[{chapterId:"hs-01",chapterNumber:1,titleUrdu:"بنو سعد میں برکتوں کا نزول اور تعظیمِ نبوی",titleEnglish:"Descent of Miraculous Barakah in Banu Sa'd",summaryUrdu:"جب سیدتنا حلیمہ نے یتیم بچے (رسول اللہ ﷺ) کو گود لیا تو ان کی خشک سواری تیز رفتار ہو گئی اور ان کے گھر میں رزق و برکت کی بارش ہو گئی۔",summaryEnglish:"When Halimah embraced the orphaned Muhammad ﷺ, her dried she-camel overflowed with milk and their home was filled with divine abundance.",hadithOrFiqhReference:"سیرت ابن ہشام / دلائل النبوۃ للبیہقی",keyTakeaways:["رسول اللہ ﷺ نے فتحِ حنین کے موقع پر سیدتنا حلیمہ کے آنے پر اپنی مبارک چادر بچھا کر ان کا استقبال فرمایا۔","ماں کی خدمت اور دودھ پلانے والی کی تعظیم کا نبوی نمونہ دنیا کے سامنے پیش ہوا۔"],fullTextUrdu:'جب بھی سیدتنا حلیمہ بارگاہِ رسالت میں حاضر ہوتیں، حضور ﷺ فرطِ محبت و تعظیم سے کھڑے ہو جاتے اور فرماتے: "مرحبا یا امی! مرحبا یا امی!" (اے میری ماں خوش آمدید!) اور اپنی ردائے مبارک زمین پر بچھا کر انہیں بٹھاتے۔'}]},{id:"CANON-NIS-13",titleUrdu:"امہات المؤمنین و بنات النبی (از مدارج النبوۃ)",titleArabic:"ذكر أزواج النبي وبناته من مدارج النبوة",titleEnglish:"Mothers of the Believers from Madarij-un-Nubuwwah",authorUrdu:"شیخ عبد الحق محدث دہلوی (رحمة الله عليه)",authorEnglish:"Shaykh Abd al-Haqq Muhaddith Dehlawi (d. 1052 AH)",authorEra:"1052ھ / دہلی، امام محدثینِ ہند",category:"ummahat_banat",categoryLabelUrdu:"امہات المؤمنین و بناتِ رسول",categoryLabelEnglish:"Mothers of the Believers & Daughters",descriptionUrdu:"مدارج النبوۃ کے قسم پنجم سے ازواجِ مطہرات کے فضائل، خصائص، اور ان کے وصال کے مفصل احوال۔ شیخ عبد الحق نے نہایت ادب اور ثقاہت سے ہر زوجۂ مطہرہ کا مقام واضح کیا ہے۔",descriptionEnglish:"Part 5 of the classical Madarij-un-Nubuwwah dedicated to the virtues, wisdom, and demises of all the Mothers of the Believers.",classicalSourceTier:"TIER_B_CLASSICAL_AUTHORITATIVE",sanadGrade:"SAHIH",verificationHash:"SHA256-MADARIJ-UMMAHAT-DEHLAWI-3303M",scholarlyConsensusUrdu:"برصغیر میں سیرت کا سب سے معتمد اور بنیادی کلاسیکی حوالہ۔",isOfflineAvailable:!0,pdfUrl:"/books/madarij-un-nubuwwat-vol1.pdf",coreChapters:[{chapterId:"md-01",chapterNumber:1,titleUrdu:"ازواجِ مطہرات کی تعداد اور ان کا روحانی مقام",titleEnglish:"The Spiritual Rank and Nobility of the Mothers of the Believers",summaryUrdu:'قرآن نے اعلان فرمایا: "اور اس کی بیویاں ان کی مائیں ہیں" (الاحزاب: ۶)۔ ازواجِ مطہرات تمام مومنین کی روحانی مائیں ہیں جن کا احترام واجب ہے۔',summaryEnglish:'The Quran decrees: "And his wives are their mothers." (Al-Ahzab 33:6). They are the eternal spiritual mothers of all believers.',hadithOrFiqhReference:"مدارج النبوۃ، قسم پنجم / سورۃ الاحزاب، آیت ۶",keyTakeaways:["ازواجِ مطہرات دنیا اور آخرت دونوں میں نبی کریم ﷺ کی ازواج ہیں۔","ان کے ذریعے آدھے سے زیادہ پردے کے اور گھریلو مسائل امت تک پہنچے۔"],fullTextUrdu:"شیخ عبد الحق دہلوی فرماتے ہیں کہ ازواجِ مطہرات کا شرف کائنات کی تمام خواتین سے بالا تر ہے، کیونکہ انہوں نے براہِ راست حضور ﷺ کے گھر کی صحبت پائی اور وہاں وحی کے نزول کا مشاہدہ کیا۔"}]},{id:"CANON-NIS-14",titleUrdu:"تذکارِ صحابیات",titleArabic:"تذكار الصحابيات رضوان الله عليهن",titleEnglish:"Tazkar-e-Sahabiyyat: The Noble Women Companions",authorUrdu:"علامہ مفتی فیض احمد اویسی (رحمة الله عليه)",authorEnglish:"Allama Mufti Faiz Ahmad Owaisi (d. 1431 AH)",authorEra:"1431ھ / بہاولپور",category:"sahabiyyat_muhaddithat",categoryLabelUrdu:"اسوۂ صحابیات و محدثات",categoryLabelEnglish:"Sahabiyyat & Scholars",descriptionUrdu:"غزوہ احد، بدر، بیعتِ عقبہ اور ہجرت میں شریک ہونے والی جلیل القدر صحابیات (حضرت ام عمارہ، حضرت اسما بنت ابی بکر، حضرت ام سلیم) کے دل دہلا دینے والے اور ایمان افروز واقعات۔",descriptionEnglish:"Heroic, faith-inspiring accounts of female companions at Uhud, Badr, and the migrations: Umm 'Umarah, Asma bint Abi Bakr, and Umm Sulaym.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-TAZKAR-SAHABIYYAT-OWAISI-4404N",scholarlyConsensusUrdu:"صحابیات کے ایمان افروز جہاد اور تقویٰ پر اردو کا بہترین گلدستہ۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Tazkar+e+Sahabiyat+Owaisi",onlineArchiveName:"Sunni Classical Heritage (Tazkar-e-Sahabiyyat - Mufti Faiz Ahmad Owaisi)",coreChapters:[{chapterId:"ts-01",chapterNumber:1,titleUrdu:"حضرت ام عمارہ (نسیبہ بنت کعب) کی غزوۂ احد میں جانثاری",titleEnglish:"Umm 'Umarah (Nusaybah bint Ka'b) at the Battle of Uhud",summaryUrdu:"رسول اللہ ﷺ نے فرمایا: احد کے دن میں دائیں دیکھتا یا بائیں، میں ام عمارہ کو ہی اپنی حفاظت میں تلوار چلاتے پاتا تھا۔",summaryEnglish:"The Prophet ﷺ proclaimed regarding Uhud: \"Whenever I looked to my right or left, I saw Umm 'Umarah defending me with her sword.\" (Ibn Sa'd)",hadithOrFiqhReference:"الطبقات الکبریٰ لابن سعد، ج ۸ / سیرت ابن ہشام",keyTakeaways:["ام عمارہ نے تیروں اور تلواروں کے زخم اپنے جسم پر کھائے مگر حضور ﷺ کا دفاع جاری رکھا۔",'رسول اللہ ﷺ نے ان کے لیے دعا فرمائی: "اے اللہ! ان کو جنت میں میرا رفیق بنا دے۔"'],fullTextUrdu:"جب احد کے میدان میں افراتفری پھیلی اور کفار نے حضور ﷺ پر تیروں کی بارش کر دی، تو اس بہادر صحابیہ نے تلوار اور ڈھال اٹھائی اور دشمنوں کے وار اپنے سینے پر روکے۔ بارہ کاری زخم لگنے کے باوجود ان کے پائے ثبات میں لغزش نہ آئی۔"}]},{id:"CANON-NIS-15",titleUrdu:"الإصابة في تمييز الصحابة (کتاب النساء)",titleArabic:"الإصابة في تمييز الصحابة - كتاب النساء والصحابيات",titleEnglish:"Al-Isabah: The Canonical Biographies of the Sahabiyyat",authorUrdu:"حافظ الحدیث ابن حجر عسقلانی (رحمة الله عليه)",authorEnglish:"Hafidh Ibn Hajar al-Asqalani (d. 852 AH)",authorEra:"852ھ / قاہرہ، شارح صحیح بخاری",category:"sahabiyyat_muhaddithat",categoryLabelUrdu:"اسوۂ صحابیات و محدثات",categoryLabelEnglish:"Sahabiyyat & Scholars",descriptionUrdu:"علمِ اسماء الرجال اور رجالِ حدیث کا سب سے مستند اور عظیم الشان دائرۃ المعارف۔ اس کے آخری حصے میں حافظ ابن حجر نے ۱۵۰۰ سے زائد صحابیات کے مکمل نام، نسب، اسناد اور فضائل کو سند کے ساتھ قلمبند کیا ہے۔",descriptionEnglish:"The foundational encyclopedic Hadith masterwork verifying the biographical transmission, names, lineages, and virtues of over 1,500 female companions.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"MUTAWATIR",verificationHash:"SHA256-AL-ISABAH-IBN-HAJAR-5505O",scholarlyConsensusUrdu:"تمام ائمۂ حدیث کے ہاں صحابہ اور صحابیات کی شناخت کا آخری اور حتمی فیصلہ کن ماخذ۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://shamela.ws/book/9767",onlineArchiveName:"Al-Maktaba al-Shamela (Al-Isabah - Ibn Hajar al-Asqalani Complete 8 Vols)",coreChapters:[{chapterId:"is-01",chapterNumber:1,titleUrdu:"حضرت اسماء بنت ابی بکر (ذات النطاقین) کا صبر و شجاعت",titleEnglish:"Asma bint Abi Bakr (Dhat an-Nitaqayn): Courage in Hijrah",summaryUrdu:'ہجرت کی رات غارِ ثور میں کھانا پہنچانے کے لیے اپنا کمر بند پھاڑ کر دو ٹکڑے کیے، جس پر حضور ﷺ نے انہیں "ذات النطاقین" کا لقب دیا۔',summaryEnglish:'During Hijrah, she ripped her waist-belt in two to fasten provisions for the Prophet ﷺ and Abu Bakr in the Cave of Thawr, earning her the title "Dhat an-Nitaqayn".',hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۲۹۷۹ / الإصابة، ج ۸",keyTakeaways:["ابو جہل کے طمانچے کھا کر بھی غارِ ثور کا راز فاش نہ کیا۔","سو سال کی عمر میں بھی ان کی بینائی اور عقل سلیم مکمل طور پر سلامت تھی۔","حضرت عبداللہ بن زبیر کی ایسی بہادرانہ تربیت کی جو تاریخ میں امر ہو گئی۔"],fullTextUrdu:"حضرت اسماء رضی اللہ عنہا استقامت کا کوہِ گراں تھیں۔ جب حجاج بن یوسف نے ان کے بیٹے حضرت عبداللہ بن زبیر کو شہید کیا تو سو سالہ ضعیفہ نے حجاج کے سامنے کھڑے ہو کر جرات کے ساتھ کلمۂ حق فرمایا۔"}]},{id:"CANON-NIS-16",titleUrdu:"الطبقات الكبرى (جلد ہشتم: ذکر نساء)",titleArabic:"الطبقات الكبرى لابن سعد - المجلد الثامن في النساء",titleEnglish:"Tabaqat Ibn Sa'd (Volume 8: Dedicated to Muslim Women)",authorUrdu:"علامہ محمد بن سعد کاتب الواقدی (رحمة الله عليه)",authorEnglish:"Allama Ibn Sa'd (d. 230 AH)",authorEra:"230ھ / بغداد، کبار مؤرخینِ اسلام",category:"sahabiyyat_muhaddithat",categoryLabelUrdu:"اسوۂ صحابیات و محدثات",categoryLabelEnglish:"Sahabiyyat & Scholars",descriptionUrdu:"اسلام کی اولین دو صدیوں میں لکھی گئی وہ تاریخی کتاب جس کی آٹھویں جلد خاص طور پر خواتینِ اسلام کے لیے وقف ہے۔ اس میں مدینہ منورہ اور مکہ کی انصار اور مہاجر خواتین کے ایمان کے احوال محفوظ ہیں۔",descriptionEnglish:"Volume 8 of the earliest biographical dictionary of Islam, recording the earliest Muslim women, their pledges of allegiance, and daily spiritual life.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"SAHIH",verificationHash:"SHA256-TABAQAT-IBN-SAD-VOL8-6606P",scholarlyConsensusUrdu:"خواتینِ اسلام کی تاریخ کا سب سے قدیم اور معتبر ترین بنیادی ماخذ۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://shamela.ws/book/1283",onlineArchiveName:"Al-Maktaba al-Shamela (Al-Tabaqat al-Kubra - Ibn Sa'd Vol 8)",coreChapters:[{chapterId:"t8-01",chapterNumber:1,titleUrdu:"سیدہ سمیہ بنت خیاط — اسلام کی پہلی شہید خاتون",titleEnglish:"Sayyidatuna Sumayyah bint Khayyat: First Martyr of Islam",summaryUrdu:"ابو جہل کے خونی نیزے کے سامنے کلمۂ توحید پر قائم رہیں اور اسلام میں سب سے پہلی شہادت کا بلند ترین رتبہ پایا۔",summaryEnglish:"Stood resolute before the spear of Abu Jahl upon Tawhid, achieving the eternal honor of becoming the very first martyr (Shahid) of Islam.",hadithOrFiqhReference:"الطبقات الکبریٰ، ج ۸، ص ۳۴۶ / مستدرک حاکم",keyTakeaways:['رسول اللہ ﷺ نے فرمایا: "صبر کرو اے آلِ یاسر! تمہارا ٹھکانا جنت ہے۔"',"سیدہ سمیہ نے دکھایا کہ ایمان کی طاقت کے آگے دنیا کے ظالم ترین جابر بھی بے بس ہیں۔"],fullTextUrdu:'مکہ کے تپتے ہوئے صحرا میں جب آلِ یاسر کو دہکتے انگاروں اور لوہے کی زرہوں میں جھلسایا جاتا، تو سیدہ سمیہ کی زبان پر صرف "احد، احد" جاری رہتا۔ ابو جہل نے نیزہ مار کر شہید کیا مگر وہ اپنے ایمان پر چٹان کی طرح قائم رہیں۔'}]},{id:"CANON-NIS-17",titleUrdu:"المحدثات: نساء عالمات في الحديث",titleArabic:"المحدثات: إسهام المرأة المسلمة في رواية الحديث ونقده",titleEnglish:"Al-Muhaddithat: The Great Female Hadith Scholars",authorUrdu:"مستند محققینِ اہل سنت و ائمۂ حدیث",authorEnglish:"Scholars of Hadith & Asma al-Rijal",authorEra:"کلاسیکی اسناد و توثیق",category:"sahabiyyat_muhaddithat",categoryLabelUrdu:"اسوۂ صحابیات و محدثات",categoryLabelEnglish:"Sahabiyyat & Scholars",descriptionUrdu:"روایات کے اس عظیم سلسلے کا بیان جس میں ۸,۰۰۰ سے زائد جلیل القدر مسلم خواتین نے صحیح بخاری، صحیح مسلم اور سنن کی تدریس فرمائی، اور جن کے شاگردوں میں امام بخاری، امام شافعی اور ابن حجر جیسے ائمہ شامل تھے۔",descriptionEnglish:"Documenting the monumental legacy of over 8,000 female Hadith scholars who preserved, audited, and taught the prophetic traditions to titans like Imam al-Shafi'i and Ibn Hajar.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"SAHIH",verificationHash:"SHA256-MUHADDITHAT-HADITH-MASTERS-7707Q",scholarlyConsensusUrdu:"علمِ حدیث کی تاریخ میں خواتین کے بے مثال کردار کی معتبر دستاویز۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Al-Muhaddithat+Akram+Nadwi",onlineArchiveName:"Classical Hadith Research Archives (Al-Muhaddithat: Women Scholars in Islam)",coreChapters:[{chapterId:"mh-01",chapterNumber:1,titleUrdu:"کریمہ مروزیہ اور صحیح بخاری کی معتمد سند",titleEnglish:"Karimah al-Marwaziyyah: The Pillar of Sahih al-Bukhari Transmission",summaryUrdu:"پانچویں صدی ہجری کی عظیم عالمہ کریمہ مروزیہ کے پاس صحیح بخاری کا سب سے صحیح اور مصدقہ نسخہ تھا، جس کی سند سے دنیا بھر میں بخاری پڑھی گئی۔",summaryEnglish:"Karimah al-Marwaziyyah possessed the most accurate, certified manuscript of Sahih al-Bukhari in Makkah, transmitting it to the greatest scholars of her era.",hadithOrFiqhReference:"سیر اعلام النبلاء للذہبی، ج ۱۸ / شذرات الذهب",keyTakeaways:["امام خطیب بغدادی نے حرمِ مکہ میں کریمہ مروزیہ سے پوری صحیح بخاری سماعت فرمائی۔","مسلمان خواتین حدیث کے حفظ، تحقیق اور متن کی تنقید میں اعلیٰ ترین درجے پر فائز تھیں۔"],fullTextUrdu:"کریمہ بنت احمد المروزیہ رحمہا اللہ مکہ مکرمہ میں مجاورت فرماتی تھیں اور صحیح بخاری کی ایسی استاد تھیں جن کے سامنے بڑے بڑے فقہا زانوئے تلمذ طے کرتے تھے۔ ان کی دیانت اور تقویٰ پر پوری امت کا اجماع ہے۔"}]},{id:"CANON-NIS-18",titleUrdu:"ذكر النسوة المتعبدات الصوفيات",titleArabic:"ذكر النسوة المتعبدات الصوفيات",titleEnglish:"Memorial of the Female Sufi Saints and Ascetics",authorUrdu:"امام ابو عبد الرحمن السلمی (رحمة الله عليه)",authorEnglish:"Imam Abu Abd al-Rahman al-Sulami (d. 412 AH)",authorEra:"412ھ / نیشاپور، کبار ائمۂ تصوف و حدیث",category:"salihat_tarbiyat",categoryLabelUrdu:"صالحات، اولیاء و تربیتِ اولاد",categoryLabelEnglish:"Ascetics & Motherhood",descriptionUrdu:"تاریخِ اسلام کی سب سے پہلی کتاب جو خاص طور پر ۸۴ عظیم الشان صوفیاء و عابدات خواتین کے تذکرے پر لکھی گئی۔ ان کی شب بیداری، ذکرِ الٰہی، معرفت اور الٰہی عشق کے پاکیزہ کلمات اس میں درج ہیں۔",descriptionEnglish:"The earliest dedicated classical biographical masterwork documenting 84 female Sufi saints, their nocturnal prayers, gnosis (ma'rifah), and pure divine love.",classicalSourceTier:"TIER_A_CANONICAL",sanadGrade:"HASAN",verificationHash:"SHA256-NISWA-SULAMI-SUFI-WOMEN-8808R",scholarlyConsensusUrdu:"تصوف اور باطنی پاکیزگی کے میدان میں خواتین کے مقام کا مستند ترین کلاسیکی ذخیرہ۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Dhikr+an-Niswah+Sulami",onlineArchiveName:"Al-Maktaba al-Shamela / Archive (Dhikr al-Niswa - Imam Abu Abd al-Rahman al-Sulami)",coreChapters:[{chapterId:"ns-01",chapterNumber:1,titleUrdu:"خواتین کا اخلاص اور شب بیداری کی لذت",titleEnglish:"Sincerity and the Sweetness of Tahajjud in Righteous Women",summaryUrdu:'عابداتِ اسلام راتوں کو اٹھ کر فرماتیں: "اے میرے مالک! ستارے چھپ گئے اور آنکھیں سو گئیں، اور تیرا دروازہ مانگنے والوں کے لیے ہمیشہ کھلا ہے۔"',summaryEnglish:'The righteous women prayed in the quiet depths of the night: "O my Lord! The stars have dimmed and eyes have slept, yet Your door remains open to the supplicant."',hadithOrFiqhReference:"صفۃ الصفوۃ لابن الجوزی / ذکر النسوة للسلمی",keyTakeaways:["گھریلو ذمہ داریوں کے ساتھ ساتھ رات کے آخری حصے میں چند رکعت نفل اللہ کے قرب کا بڑا ذریعہ ہے۔","دل کی پاکیزگی اور تقویٰ ہی اصل حسن ہے۔"],fullTextUrdu:"امام سلمی رحمہ اللہ فرماتے ہیں کہ صحابیات اور صالحات تابعین کا اصل ہتھیار ان کا زہد اور خلوت میں اللہ سے مناجات تھی۔ انہوں نے اپنی دعاؤں سے امت کے بڑے بڑے مسائل کو حل کروایا۔"}]},{id:"CANON-NIS-19",titleUrdu:"تذکرہ رابعہ بصری و عابداتِ اسلام",titleArabic:"سيرة سيدة العارفات رابعة العدوية البصرية",titleEnglish:"Rabi'ah al-Adawiyyah: The Sultan of Divine Love",authorUrdu:"مستند اکابرینِ اہل سنت و جماعت",authorEnglish:"Compiled by Authorities of Ahl al-Sunnah",authorEra:"کلاسیکی روایت و استناد",category:"salihat_tarbiyat",categoryLabelUrdu:"صالحات، اولیاء و تربیتِ اولاد",categoryLabelEnglish:"Ascetics & Motherhood",descriptionUrdu:"سیدہ رابعہ بصری رحمہا اللہ کے بے لوث عشقِ الٰہی، مناجات، سچی توبہ اور وقت کے کبار ائمہ جیسے حضرت حسن بصری و سفیان ثوری کے ساتھ علمی و روحانی مکالموں کا دلنشین بیان۔",descriptionEnglish:"The life and wisdom of Sayyidatuna Rabi'ah al-Basriyyah: her pure divine love, ascetic contentment, and spiritual dialogues with Imam Hasan al-Basri.",classicalSourceTier:"TIER_B_CLASSICAL_AUTHORITATIVE",sanadGrade:"HASAN",verificationHash:"SHA256-RABIAH-ADAWIYYAH-SULTAN-9909S",scholarlyConsensusUrdu:"عشقِ الٰہی اور خلوصِ نیت کے لیے عالمگیر مسلمہ مثال۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Rabia+Basri+Urdu",onlineArchiveName:"Sunni Classical Heritage (Tazkirah Sayyidatuna Rabia al-Adawiyyah)",coreChapters:[{chapterId:"ra-01",chapterNumber:1,titleUrdu:"خالص عشقِ الٰہی اور دنیا سے بے رغبتی",titleEnglish:"Pure Love of Allah and Renunciation of Worldly Vanity",summaryUrdu:'حضرت رابعہ بصری کی مشہور مناجات: "یا اللہ! میں تیری عبادت دوزخ کے خوف یا جنت کے لالچ سے نہیں کرتی، بلکہ تو بذاتِ خود اس لائق ہے کہ تیری عبادت کی جائے۔"',summaryEnglish:"Rabi'ah's renowned prayer: \"O Allah! I worship You not out of fear of Hell nor desire for Paradise, but because You are worthy of worship in Your Majesty.\"",hadithOrFiqhReference:"حلیۃ الاولیاء لابی نعیم / تذکرۃ الاولیاء",keyTakeaways:["عبادت میں لالچ یا دکھاوے کے بجائے رضائے الٰہی کی جستجو ہونی چاہیے۔","دنیا کی ظاہری چمک دمک کے بجائے آخرت کی ابدی راحت کو ترجیح دی جائے۔"],fullTextUrdu:"سیدہ رابعہ بصری رضی اللہ عنہا نے اپنی پوری زندگی کو مولیٰ کی یاد میں فنا کر دیا۔ وہ فرماتیں کہ اگر انسان اللہ تعالیٰ سے سچی محبت کرے تو گناہ کی طرف اس کا دل مائل ہی نہیں ہو سکتا۔"}]},{id:"CANON-NIS-20",titleUrdu:"ماں کی گود اور تربیتِ اولاد",titleArabic:"تربية الأولاد في الإسلام ودور الأم المسلمة",titleEnglish:"The Mother's Lap: Cradle of Upbringing and Character",authorUrdu:"علامہ عبد المصطفیٰ اعظمی (رحمة الله عليه)",authorEnglish:"Allama Abdul Mustafa Azmi (d. 1406 AH)",authorEra:"1406ھ / مصنف جنتی زیور",category:"salihat_tarbiyat",categoryLabelUrdu:"صالحات، اولیاء و تربیتِ اولاد",categoryLabelEnglish:"Ascetics & Motherhood",descriptionUrdu:"اسلام میں ماں کے بلند ترین رتبے (الجَنَّةُ تَحْتَ أَقْدَامِ الأُمَّهَاتِ)، نوزائیدہ بچے کے کان میں اذان، تحنیک، حلال لقمے کی تاثیر اور بچوں کو سچا عاشقِ رسول بنانے کا جامع نبوی طریقہ۔",descriptionEnglish:"A definitive guide on raising righteous children: the sublime rank of the mother's feet leading to Jannah, Tahneek, halal sustenance, and instilling love for the Prophet ﷺ in childhood.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"SAHIH",verificationHash:"SHA256-MOTHER-CRADLE-AZMI-1010T",scholarlyConsensusUrdu:"مسلم ماؤں کے لیے اولاد کی اسلامی تربیت کا بہترین اور مستند دستور العمل۔",isOfflineAvailable:!0,onlineArchiveUrl:"https://archive.org/search?query=Maa+Ki+Godh+Azmi",onlineArchiveName:"Ahl al-Sunnah Digital Heritage (Maan Ki Goud - Allama Abdul Mustafa Azmi)",coreChapters:[{chapterId:"mg-01",chapterNumber:1,titleUrdu:"بچوں کے حقوق اور ماں کی گود کی پہلی درسگاہ",titleEnglish:"Rights of Children and the Mother's Lap as the First School",summaryUrdu:"بچے کے لیے سب سے پہلا حق اچھا اسلامی نام اور حلال دودھ ہے، ماں کی گود ہی بچے کے اخلاق اور دینداری کی بنیاد رکھتی ہے۔",summaryEnglish:"The first right of a child is an honorable Islamic name and pure halal sustenance; the mother's lap is the primary foundation of the child's lifelong character.",hadithOrFiqhReference:"شعب الایمان للبیہقی، حدیث رقم ۸۲۹۶",keyTakeaways:["ماں کا دودھ پلاتے وقت بسم اللہ اور درود شریف پڑھنا بچے کی روح پر مثبت اثر ڈالتا ہے۔","بچوں کے سامنے جھوٹ اور بدزبانی سے پرہیز کرنا فرض ہے کیونکہ بچے وہی سیکھتے ہیں جو دیکھتے ہیں۔","سات سال کی عمر میں نماز کا حکم دیا جائے اور دس سال پر باقاعدہ عادت ڈالی جائے۔"],fullTextUrdu:'رسول اللہ ﷺ نے فرمایا: "کسی باپ نے اپنی اولاد کو اچھے ادب اور تربیت سے بہتر کوئی تحفہ نہیں دیا۔" علامہ عبد المصطفیٰ اعظمی فرماتے ہیں کہ شیخ عبد القادر جیلانی اور امام احمد بن حنبل کی عظمت کے پیچھے ان کی متقی ماؤں کی تربیت اور دعائیں تھیں۔'}]},{id:"CANON-NIS-21",titleUrdu:"صحابۂ کرام کی مثالی بیویاں",titleArabic:"صحابۂ کرام کی مثالی بیویاں (سیرتِ صحابیات و ازواجِ مطہرات)",titleEnglish:"Sahaba-e-Kiram Ki Misali Biwiyan (Exemplary Wives of the Sahabah)",authorUrdu:"مستند علماء و محققینِ سیرت و احوالِ صحابیات",authorEnglish:"Authentic Biographical Board of Ahl al-Sunnah",authorEra:"معاصر توثیق / مستند سوانح",category:"sahabiyyat_muhaddithat",categoryLabelUrdu:"اسوۂ صحابیات و محدثات",categoryLabelEnglish:"Sahabiyyat & Scholars",descriptionUrdu:"امہات المؤمنین اور جلیل القدر صحابیات کی مقدس زندگی، گھریلو اخلاق، شوہروں کی خدمت اور دین کے لیے لازوال قربانیوں کا ایمان افروز اور دلنشین مجموعہ۔ مکمل مستند پی ڈی ایف ایڈیشن کے ساتھ دستیاب۔",descriptionEnglish:"A dedicated, heart-touching biographical work illuminating the lives, marital devotions, piety, and heroic support of the Mothers of the Believers and noble female companions.",classicalSourceTier:"TIER_C_AUTHENTIC_SUNNI",sanadGrade:"MAQBOOL_MUTABAR",verificationHash:"SHA256-SAHABA-KI-MISALI-BIWIYAN-AUTHENTIC",scholarlyConsensusUrdu:"خواتین اور گھریلو تربیت کے لیے نہایت متاثر کن اور مستند سوانحی دستاویز۔",isOfflineAvailable:!0,pdfUrl:"/books/sahaba-ki-misali-biwiyan.pdf",onlineArchiveUrl:"https://archive.org/search?query=sahaba+ki+misali+biwiyan",onlineArchiveName:"AMAL Local Digital Repository (Sahaba-e-Kiram Ki Misali Biwiyan Complete Scan)",coreChapters:[{chapterId:"smb-01",chapterNumber:1,titleUrdu:"سیدہ خدیجۃ الکبریٰ — غمخواری، ایثار اور رفاقت کا مثالی نمونہ",titleEnglish:"Sayyidah Khadijah: The Supreme Model of Marital Comfort & Faith",summaryUrdu:"جب وحی کے ابتدائی ایام میں خوف اور اضطراب تھا تو سیدہ خدیجہ نے کَلَّا وَاللَّهِ لَا يُخْزِيكَ اللَّهُ أَبَدًا کہہ کر ڈھارس بندھائی۔",summaryEnglish:'When the first revelation arrived, Sayyidah Khadijah consoled the Prophet ﷺ declaring: "Never by Allah! Allah will never humiliate you, for you maintain kinship and speak truth."',hadithOrFiqhReference:"صحیح البخاری، حدیث رقم ۳ / صحیح مسلم",keyTakeaways:["گھریلو زندگی میں باہمی محبت، عزت اور ایک دوسرے کی پریشانی میں شریک ہونا اصل سنت ہے۔","دین کے لیے اپنا تن، من، دھن قربان کرنا خواتینِ صحابہ کا خاص شیوہ رہا ہے۔"],fullTextUrdu:"حضرت خدیجہ رضی اللہ عنہا نے اپنی تمام دولت رسول اللہ ﷺ کے قدموں میں ڈال دی اور اسلام کے نازک ترین دور میں وہ قلعہ بن کر کھڑی رہیں۔ تاریخ گواہ ہے کہ جب تک وہ حیات رہیں، حضور ﷺ نے دوسرا نکاح نہ فرمایا اور ان کے وصال کے بعد بھی ان کی سہیلیوں کو تحائف بھیج کر ان کی یاد تازہ فرماتے تھے۔"},{chapterId:"smb-02",chapterNumber:2,titleUrdu:"سیدہ فاطمہ الزہراء — فقر و فاقہ میں صبر، قناعت اور چکی پیسنے کا شرف",titleEnglish:"Sayyidah Fatimah al-Zahra: Serenity in Poverty and Labor of Love",summaryUrdu:"سیدہ فاطمہ نے غربت کے باوجود گھر کے تمام کام خود کیے، چکی پیستے پیستے مبارک ہاتھوں پر چھالے پڑ گئے مگر کبھی بے صبری کا کلمہ نہیں نکالا۔",summaryEnglish:"Sayyidah Fatimah ground the wheat mill herself until her blessed hands were blistered, personifying ultimate contentment and dignity.",hadithOrFiqhReference:"جامع الترمذی، حدیث رقم ۳۷۶۱ / مسند احمد",keyTakeaways:['رسول اللہ ﷺ نے فرمایا: "فاطمہ میرے جگر کا ٹکڑا ہے"۔',"گھریلو کام کاج میں مشقت اٹھانا سنتِ سیدہ فاطمۃ الزہراء رضی اللہ عنہا ہے۔"],fullTextUrdu:"سیدہ فاطمہ الزہراء رضی اللہ عنہا سیدۃ نساء العالمین تھیں، جن کے گھر میں کئی کئی دن چولہا نہ جلتا تھا مگر ذکرِ الٰہی کا چراغ کبھی گل نہ ہوتا تھا۔ جب آپ نے خادمہ کی درخواست کی تو حضور ﷺ نے رات کو ۳۳ مرتبہ سبحان اللہ، ۳۳ مرتبہ الحمد للہ اور ۳۴ مرتبہ اللہ اکبر پڑھنے کی تعلیم دی جو خادم سے بہتر ہے۔"}]}],t=[{id:"sah-01",nameUrdu:"ام المؤمنین سیدتنا خدیجہ الکبریٰ",nameArabic:"خديجة بنت خويلد القرشية الأسدية (رضي الله عنها)",nameEnglish:"Sayyidatuna Khadijah al-Kubra (رضي الله عنها)",titleUrdu:"طاہرہ، ام المؤمنین، سیدۃ نساء قریش، رفیقۂ نبوت",titleEnglish:"At-Tahirah (The Pure), Mother of the Believers, First Believer",kinshipToProphet:"رسول اللہ ﷺ کی پہلی زوجۂ مطہرہ، سیدہ فاطمہ اور چاروں بناتِ رسول کی والدہ ماجدہ",kinshipToProphetEnglish:"First Noble Spouse of the Prophet ﷺ, Mother of Sayyidah Fatimah and all four daughters of the Prophet ﷺ",classicalCitation:"صحیح البخاری، حدیث ۳، ۳۴۳۱ / صحیح مسلم، حدیث ۲۴۳۲، ۲۴۳۵",era:"قبلِ ہجرت ۳ سال قبل وصال مکہ مکرمہ (عام الحزن)",biographyUrdu:"کائنات میں سب سے پہلے اسلام قبول کرنے والی، رسول اللہ ﷺ کی پہلی رفیقۂ حیات اور نبوت کی سب سے مضبوط غمخوار۔ نزولِ وحی کے وقت ڈھارس بندھائی، شعبِ ابی طالب کے بائیکاٹ میں اپنی بے پناہ دولت نچھاور کی اور اللہ تعالیٰ نے حضرت جبرائیل کے ذریعے ان کے لیے سلام بھیجا۔",biographyEnglish:"The first human being to embrace Islam and the premier emotional and spiritual fortress of the Prophet ﷺ. She recognized his Prophethood at Cave Hira, sacrificed her entire trading empire for the Da'wah, and received greetings directly from Allah Almighty via Angel Jibril.",heroicAttributes:["بے پناہ استقامت","کامل مالی ایثار","شوہر کی بہترین ڈھارس","رسول اللہ ﷺ کا بے مثال دفاع"],heroicAttributesEnglish:["Unflinching Resilience","Complete Financial Devotion","Emotional Pillar of the Prophet ﷺ","Fierce Defense of Revelation"],dailySunnahLessons:[{ur:"مشکل اور پریشانی کے وقت شوہر اور اہل خانہ کی ڈھارس بندھانا اور ان کا حوصلہ بڑھانا۔",en:"Providing calm, reassuring emotional solace to spouses and family during severe crises."},{ur:"کاروبار اور تجارت میں دیانت داری، سچائی اور کذب و فریب سے قطعی پرہیز کرنا۔",en:"Practicing uncompromising honesty, trustworthiness, and ethical integrity in enterprise."},{ur:"اللہ کی راہ میں بغیر احسان جتائے خاموشی اور اخلاص کے ساتھ خرچ کرنا۔",en:"Spending silently and generously in the path of Allah without ever seeking credit."}],sanadVerificationHash:"SANAD-KHADIJAH-BUKHARI-SAHIH-001",lineageAndBackgroundUrdu:'سیدتنا خدیجہ بنت خویلد بن اسد بن عبد العزیٰ بن قصی القرشیہ الاسدیہ۔ آپ کا شجرۂ نسب رسول اللہ ﷺ سے چوتھی پشت (قصی بن کلاب) پر جا ملتا ہے۔ زمانۂ جاہلیت میں بھی آپ کی پاکبازی، حیا اور عفت کا یہ عالم تھا کہ مکہ کا ہر فرد آپ کو "طاہرہ" (نہایت پاکدامن) اور "سیدۃ قریش" کے نام سے یاد کرتا تھا۔',lineageAndBackgroundEnglish:'Khadijah bint Khuwaylid ibn Asad ibn Abd al-Uzza ibn Qusayy al-Qurashiyyah al-Asadiyyah. Her lineage merges with the Prophet ﷺ at Qusayy ibn Kilab. Even during pre-Islamic Jahiliyyah, her peerless chastity and moral dignity earned her the universal title "At-Tahirah" (The Pure).',propheticPraiseHadithArabic:"\xabخَيْرُ نِسَائِهَا مَرْيَمُ ابْنَتُ عِمْرَانَ، وَخَيْرُ نِسَائِهَا خَدِيجَةُ\xbb [صحيح البخاري: ۳۴۳۱] — وَقَالَ ﷺ: \xabإِنِّي قَدْ رُزِقْتُ حُبَّهَا\xbb [صحيح مسلم: ۲۴۳۵]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "اس کائنات کی تمام عورتوں میں سب سے افضل مریم بنت عمران ہیں اور اس دنیا کی عورتوں میں سب سے افضل خدیجہ ہیں"۔ اور فرمایا: "بے شک مجھے خدیجہ کی محبت اللہ کی طرف سے رزق بنا کر عطا کی گئی ہے"۔',propheticPraiseHadithEnglish:'The Messenger of Allah ﷺ stated: "The best of the women of the worlds is Maryam bint Imran, and the best of the women of this world is Khadijah." (Sahih al-Bukhari) And he proclaimed: "Verily, I was nourished with her love as divine sustenance." (Sahih Muslim)',propheticPraiseSource:"صحیح البخاری، کتاب الانبیاء، حدیث رقم ۳۴۳۱ / صحیح مسلم، حدیث رقم ۲۴۳۵",exhaustiveBiographyUrdu:["سیدتنا خدیجہ الکبریٰ رضی اللہ عنہا مکہ کی سب سے باعزت اور کامیاب تاجر خاتون تھیں۔ جب انہوں نے حضور اقدس ﷺ کی امانت، راست بازی اور پاکیزہ اخلاق کا مشاہدہ فرمایا، تو اپنے خادم میسرہ کی زبانی حضور ﷺ کے شمائل سن کر خود نکاح کا پیغام بھیجا۔ اس وقت رسول اللہ ﷺ کی عمر مبارک ۲۵ سال اور سیدہ خدیجہ کی عمر ۴۰ سال تھی۔ آپ کی رفاقت میں رسول اللہ ﷺ کے ۲۵ سال ایسی بے مثل محبت اور یکجہتی کے ساتھ گزرے کہ جب تک وہ حیات رہیں، حضور ﷺ نے دوسرا نکاح نہیں فرمایا۔",'جب غارِ حرا میں پہلی وحی اتری اور رسول اللہ ﷺ پر جلالِ الٰہی کی ہیبت طاری ہوئی اور آپ ﷺ نے فرمایا: "زَمِّلُونِي زَمِّلُونِي" (مجھے چادر اوڑھا دو)، تو سیدتنا خدیجہ نے کمالِ بصیرت سے وہ تاریخ ساز جملہ ارشاد فرمایا جو رہتی دنیا تک ایمان کی تسلی کی بنیاد ہے: "كَلَّا وَاللَّهِ لَا يُخْزِيكَ اللَّهُ أَبَدًا، إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ" (ہرگز نہیں! بخدا اللہ آپ کو کبھی رسوا نہیں فرمائے گا۔ آپ تو رشتہ داروں سے حسنِ سلوک کرتے ہیں، ناداروں کا بوجھ اٹھاتے ہیں، بے سہاروں کو کما کر دیتے ہیں، مہمان کی ضیافت کرتے ہیں اور راہِ حق کی مصیبتوں میں مدد فرماتے ہیں)۔',"جب قریش نے بنو ہاشم کا معاشی بائیکاٹ کر کے انہیں شعبِ ابی طالب کی تپتی گھاٹی میں تین سال محصور رکھا، جہاں بھوک اور پیاس سے پتے چبا کر گزارا ہوتا تھا، تو سیدتنا خدیجہ نے محلات کی آسائشیں چھوڑ کر حضور ﷺ کے ساتھ گھاٹی میں فقر و فاقہ کی سختیاں جھیلیں اور اپنی تمام تر دولت اسلام کے تحفظ پر نچھاور کر دی۔",'حضرت جبرائیل علیہ السلام نے حضور ﷺ کی خدمت میں حاضر ہو کر عرض کیا: "یا رسول اللہ! یہ خدیجہ برتن لے کر آ رہی ہیں، جب آئیں تو انہیں ان کے رب کا اور میرا سلام کہیے اور انہیں جنت میں موتیوں کے ایک ایسے محل کی خوشخبری دیجیے جہاں نہ کوئی شور ہوگا نہ کوئی مشقت"۔','سیدتنا خدیجہ کا وصال ہجرت سے ۳ سال قبل ہوا، اور اس صدمے پر رسول اللہ ﷺ نے اس سال کو "عام الحزن" (غم کا سال) کا نام دیا۔ وصال کے برسوں بعد بھی جب مدینہ میں بکری ذبح ہوتی، تو حضور ﷺ خدیجہ کی سہیلیوں کے گھروں میں گوشت بھیجتے اور ان کی وفا کو فرطِ محبت سے یاد فرماتے تھے۔'],exhaustiveBiographyEnglish:["Sayyidatuna Khadijah al-Kubra (رضي الله عنها) was the supreme matriarch of Islamic history and the foremost human being to testify to the Prophethood of Muhammad ﷺ. Prior to Islam, she managed a vast commercial trade reaching Syria and Yemen, conducting business with unparalleled ethics that earned her the Makkan title At-Tahirah (The Pure).","Recognizing the absolute honesty and divine light of the Prophet ﷺ, she proposed marriage through her companion Nafisah. Their 25 years of marriage formed the most harmonious household in human history; the Prophet ﷺ wed no other woman during her entire lifetime.",'When the first revelation shook Cave Hira and the Prophet ﷺ returned trembling, calling "Zammiluni, Zammiluni" (Wrap me up!), Khadijah provided the ultimate theological comfort: "Never by Allah! Allah will never humiliate you, for you uphold the ties of kinship, bear the burdens of the weak, spend upon the destitute, honor the guest, and aid those afflicted by truth."',"During the brutal 3-year siege in the valley of Shi'b Abi Talib, where Muslims were starved under economic boycott, Khadijah liquidated her entire commercial wealth to sustain the fledgling Muslim community, enduring hunger with radiant patience.",'Archangel Jibril descended to the Prophet ﷺ declaring: "O Messenger of Allah! Here is Khadijah approaching with a vessel of food. When she reaches you, convey to her peace (Salam) from her Lord and from me, and give her glad tidings of a palace of carved pearls in Paradise where there is neither tumult nor weariness."','She passed away in Makkah in the 10th year of Prophethood. The Prophet ﷺ personally lowered her into her resting place at Jannat al-Mu\'alla and designated the year "Aam al-Huzn" (The Year of Sorrow). Even decades later in Madinah, he would honor her memory by sending gifts to her surviving friends.'],majorHistoricalMilestones:[{eventTitleUrdu:"حضور ﷺ کی دیانت کا اعتراف اور نکاحِ مبارک",eventTitleEnglish:"Marriage to the Prophet ﷺ Based on Truth & Trust",descriptionUrdu:"سیدہ خدیجہ نے حضور ﷺ کی امانت و سچائی سے متاثر ہو کر نکاح کا پیغام بھیجا۔",descriptionEnglish:"Recognized the unblemished integrity of the Prophet ﷺ and initiated marriage."},{eventTitleUrdu:"غارِ حرا میں پہلی وحی اور تسلی کا تاریخ ساز کردار",eventTitleEnglish:"Solace at the First Revelation in Cave Hira",descriptionUrdu:"وحی کے نزول پر ڈھارس بندھائی اور اسلام قبول کرنے والی کائنات کی سب سے پہلی ہستی بنیں۔",descriptionEnglish:"Immediately embraced Islam, providing emotional and moral grounding."},{eventTitleUrdu:"شعبِ ابی طالب کا تین سالہ بائیکاٹ اور مالی قربانی",eventTitleEnglish:"3-Year Siege of Shi'b Abi Talib",descriptionUrdu:"بنو ہاشم کے معاشی بائیکاٹ میں اپنی تمام دولت اسلام کی بقا پر نچھاور کر دی۔",descriptionEnglish:"Endured famine and deprivation alongside the Prophet ﷺ, expending her entire fortune."},{eventTitleUrdu:"اللہ تعالیٰ اور حضرت جبرائیل کا براہِ راست سلام",eventTitleEnglish:"Direct Greeting from Allah via Angel Jibril",descriptionUrdu:"جبرائیل علیہ السلام نے آ کر رب العالمین کی جانب سے سلام اور جنت میں موتیوں کے محل کی بشارت دی۔",descriptionEnglish:"Honored with divine peace (Salam) from Allah Almighty delivered by Archangel Jibril."},{eventTitleUrdu:"وصالِ مبارک اور عام الحزن کا اعلان",eventTitleEnglish:"Demise and the Year of Sorrow (Aam al-Huzn)",descriptionUrdu:"ہجرت سے ۳ سال قبل ۱۰ نبوی کو مکہ میں وصال فرمایا۔ حضور ﷺ نے خود تدفین فرمائی۔",descriptionEnglish:"Passed away in Makkah; the Prophet ﷺ personally laid her to rest in Jannat al-Mu'alla."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن حجر عسقلانی (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Hajar al-Asqalani",bookTitle:"الإصابة في تمييز الصحابة (جلد ۸)",verbatimQuoteUrdu:"خدیجہ رضی اللہ عنہا نے اپنی پوری زندگی میں کبھی حضور ﷺ کی دل شکنی نہیں کی اور نہ ہی کسی کلمے سے ناگواری ظاہر کی۔ ان کی فضیلتیں اتنی کثیر ہیں جن کا احاطہ ممکن نہیں۔",verbatimQuoteEnglish:"Khadijah never once distressed the Prophet ﷺ in word or deed throughout their 25 years together."},{scholarNameUrdu:"امام شمس الدین الذہبی (رحمہ اللہ)",scholarNameEnglish:"Imam al-Dhahabi",bookTitle:"سير أعلام النبلاء",verbatimQuoteUrdu:"ام المؤمنین خدیجہ رضی اللہ عنہا عقل، دین، مروت، سخاوت اور کمال میں قریش کی تمام خواتین کی سردار تھیں۔",verbatimQuoteEnglish:"She was the supreme matriarch of Quraysh in intellect, religious devotion, generosity, and nobility."}]},{id:"sah-02",nameUrdu:"ام المؤمنین سیدتنا عائشہ صدیقہ",nameArabic:"عائشة بنت أبي بكر الصدیق التيمية (رضي الله عنها)",nameEnglish:"Sayyidatuna Aisha Siddiqah (رضي الله عنها)",titleUrdu:"صدیقہ، حمیراء، فقیہۃ الامت، ام المؤمنین، حبیبۃ حبیب اللہ",titleEnglish:"As-Siddiqah, The Great Jurist, Mother of the Believers",kinshipToProphet:"رسول اللہ ﷺ کی محبوب ترین زوجۂ مطہرہ، خلیفۂ اول حضرت ابوبکر صدیق کی لختِ جگر",kinshipToProphetEnglish:"Most Beloved Noble Spouse of the Prophet ﷺ, Daughter of the First Caliph Sayyiduna Abu Bakr al-Siddiq",classicalCitation:"صحیح البخاری، حدیث ۳۷۶۸، ۴۷۵۰ / جامع الترمذی، حدیث ۳۸۸۳",era:"متوفی ۵۸ ہجری مدینہ منورہ (تدفین جنت البقیع)",biographyUrdu:"امتِ مسلمہ کی سب سے عظیم عالمہ، فقیہہ اور مفسرہ۔ رسول اللہ ﷺ سے ۲,۲۱۰ احادیث روایت فرمائیں۔ صحابہ کرام فقہی اور میراث کے مسائل میں آپ کی طرف رجوع فرماتے تھے۔ قرآن مجید میں ان کی براءت نازل ہوئی اور ان کا حجرہ مبارکہ ہی روضۂ اطہر بنا۔",biographyEnglish:"The supreme female scholar of Islam. Transmitter of 2,210+ Hadiths, master of jurisprudence, medicine, and Arabic poetry. Senior companions consulted her for legal decrees. Her innocence was enshrined forever in Surah An-Nur, and her sacred chamber became the resting place of the Prophet ﷺ.",heroicAttributes:["بے مثال علمی و اجتہادی عبقریت","سخاوت اور فیاضی کا سمندر","شب بیداری، زہد اور کثرتِ روزے","حدیث و فقہ کی حفاظت"],heroicAttributesEnglish:["Scholarly Preeminence","Deep Legal Insight","Premier Hadith Transmitter","Eloquence and Oratory"],dailySunnahLessons:[{ur:"دین کے علم، فقہ اور حدیث کو باریکی اور تحقیق کے ساتھ سیکھنا۔",en:"Pursuing deep sacred knowledge and transmitting accurate Islamic understanding to others."},{ur:"الزام تراشی اور غیبت سے اپنی زبان کی سختی کے ساتھ حفاظت کرنا۔",en:"Guarding one's tongue strictly against backbiting, rumors, and slanders."},{ur:"حاجت مندوں پر کثرت سے صدقہ کرنا چاہے اپنے پاس ایک لقمہ ہی کیوں نہ ہو۔",en:"Giving charity to the needy selflessly even when facing personal hardship."}],sanadVerificationHash:"SANAD-AISHA-TIRMIDHI-SAHIH-002",lineageAndBackgroundUrdu:"سیدتنا عائشہ بنت ابی بکر صدیق عبد اللہ بن عثمان التیمیہ القرشیہ۔ آپ کی والدہ ماجدہ ام رومان بنت عامر کنانیہ ہیں۔ آپ کا گھرانہ اسلام کا پہلا وہ مبارک گھرانہ ہے جس کے تمام افراد ایمان کے نور سے منور ہوئے۔ آپ کی پیدائش اسلام کے ابتدائی دور میں ہوئی اور آپ نے آنکھ کھولتے ہی گھر میں توحید اور رسول اللہ ﷺ کا نام سنا۔",lineageAndBackgroundEnglish:"Aisha bint Abi Bakr as-Siddiq Abd Allah ibn Uthman al-Taymiyyah al-Qurashiyyah. Her mother was Umm Ruman bint Amir. Born into the earliest household of Islam, she never breathed the air of idolatry.",propheticPraiseHadithArabic:"\xabفَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ\xbb [صحيح البخاري: ۳۷۶۸] — وَقَالَ أَبُو مُوسَى: \xabمَا أَشْكَلَ عَلَيْنَا أَصْحَابَ رَسُولِ اللَّهِ ﷺ حَدِيثٌ قَطُّ فَسَأَلْنَا عَائِشَةَ إِلَّا وَجَدْنَا عِنْدَهَا مِنْهُ عِلْمًا\xbb [جامع الترمذي: ۳۸۸۳]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے فرمایا: "عائشہ کی فضیلت تمام عورتوں پر ایسی ہے جیسے ثرید (عمدہ ترین کھانے) کی فضیلت باقی تمام کھانوں پر ہے"۔ اور حضرت ابو موسیٰ اشعری نے فرمایا: "ہم صحابہ کو جب بھی کسی حدیث یا مسئلے میں اشکال پیش آیا، ہم نے عائشہ سے پوچھا تو ان کے پاس اس کا یقینی علم موجود پایا"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ stated: "The superiority of Aisha over other women is like the superiority of Tharid over all other food." (Sahih al-Bukhari) Abu Musa al-Ash\'ari reported: "Never did a difficult matter confront the companions of the Prophet ﷺ except that we asked Aisha and found knowledge regarding it with her." (Jami al-Tirmidhi)',propheticPraiseSource:"صحیح البخاری، حدیث ۳۷۶۸ / جامع الترمذی، حدیث ۳۸۸۳ (حدیث صحیح غریب)",exhaustiveBiographyUrdu:['سیدتنا عائشہ صدیقہ رضی اللہ عنہا امتِ مسلمہ کی وہ مایہ ناز علمی اور روحانی عبقری تھیں جن کے ذریعے شریعتِ اسلامیہ کا نصف سے زیادہ حصہ امت تک پہنچا۔ آپ کا حافظہ، فصاحت و بلاغت اور فہمِ دین اس قدر بے مثل تھا کہ امام زہری فرماتے ہیں: "اگر تمام مردوں اور ازواجِ مطہرات کا علم ایک پلڑے میں رکھا جائے اور عائشہ کا علم دوسرے پلڑے میں، تو عائشہ کا پلڑا بھاری رہے گا"۔','جب منافقین نے واقعۂ افک میں ناپاک الزام تراشی کی، تو سیدتنا عائشہ نے صبر کا وہ اعلیٰ ترین نمونہ پیش فرمایا کہ آپ نے فرمایا: "واللہ! میں صرف وہی کہتی ہوں جو حضرت یوسف علیہ السلام کے والد نے فرمایا تھا: فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَى مَا تَصِفُونَ"۔ اس پر اللہ تعالیٰ نے عرشِ بریں سے سورۃ النور کی ۱۰ آیات نازل فرما کر قیامت تک کے لیے ان کی طہارت اور براءت پر مہر لگا دی۔',"آپ زہد اور قناعت کا پیکر تھیں۔ عروہ بن زبیر فرماتے ہیں کہ میں نے سیدتنا عائشہ کو دیکھا کہ ایک دن میں ستر ہزار (۷۰,۰۰۰) درہم صدقہ فرما دیے اور اپنے چادر مبارک میں پیوند لگے ہوئے تھے۔ اکثر مسلسل روزے رکھتیں اور شام کو سوکھی روٹی اور زیتون کے تیل سے افطار فرماتیں۔","رسول اللہ ﷺ کے مرضِ وصال کے آخری ایام سیدتنا عائشہ کے حجرہ مبارکہ میں گزرے۔ سرکارِ دو عالم ﷺ نے سیدتنا عائشہ کی گود میں سر مبارک رکھے ہوئے وصال فرمایا اور آپ کے حجرے ہی میں مدفون ہوئے، جو آج کائنات کا مقدس ترین روضۂ اطہر ہے۔","آپ نے ۵۸ ہجری میں ۱۷ رمضان المبارک کو مدینہ منورہ میں وصال فرمایا۔ حضرت ابوہریرہ رضی اللہ عنہ نے نمازِ جنازہ پڑھائی اور وصیت کے مطابق رات کے وقت جنت البقیع میں تدفین عمل میں آئی۔"],exhaustiveBiographyEnglish:["Sayyidatuna Aisha Siddiqah (رضي الله عنها) stands as the supreme female scholar and jurist in human history. Transmitting 2,210 authentic traditions, she was a master not only of Hadith and Fiqh, but also of medicine, inheritance law, and classical Arabic literature.",'When hypocrites forged the slander of the Ifk, Aisha placed her total trust in Allah: "By Allah, I know nothing to say except what the father of Yusuf said: Beautiful patience is my course, and Allah is the One sought for help against that which you describe." In response, Allah revealed 10 verses of Surah An-Nur directly exonerating her for all eternity.',"Her generosity was legendary. Her nephew Urwah ibn al-Zubayr testified that he witnessed her distribute 70,000 dirhams in charity in a single afternoon while wearing a patched garment, not keeping a single coin to buy food for her own fast.","The Prophet ﷺ spent his final earthly days in her chamber, and breathed his noble last in her embrace. His blessed resting place was dug directly within her room, transforming her home into the holiest sanctuary on earth.","She passed away on the 17th of Ramadan, 58 AH, at the age of 67. Abu Hurayrah led her funeral prayers, and in accordance with her modest wishes, she was laid to rest at night in Jannat al-Baqi alongside her fellow Mothers of the Believers."],majorHistoricalMilestones:[{eventTitleUrdu:"نکاحِ مبارک اور مدینہ منورہ کی ہجرت",eventTitleEnglish:"Blessed Marriage and Migration to Madinah",descriptionUrdu:"حضور ﷺ کے نکاح میں آئیں اور مدینہ منورہ میں حجرہ مبارکہ کو اپنا مسکن بنایا۔",descriptionEnglish:"Wed the Prophet ﷺ and established the blessed domestic sanctuary in Madinah."},{eventTitleUrdu:"واقعۂ افک اور سورۃ النور کی آیاتِ براءت",eventTitleEnglish:"The Slander of Ifk and Divine Exoneration",descriptionUrdu:"منافقین کے بہتان کے جواب میں اللہ تعالیٰ نے آسمان سے ۱۰ آیاتِ قرآنی نازل فرمائیں۔",descriptionEnglish:"Allah revealed 10 verses of Surah An-Nur establishing her perpetual innocence."},{eventTitleUrdu:"رسول اللہ ﷺ کا وصالِ مبارک حجرۂ عائشہ میں",eventTitleEnglish:"The Passing of the Prophet ﷺ in Her Chamber",descriptionUrdu:"حضور ﷺ نے آپ کی گود میں وصال فرمایا اور حجرۂ عائشہ ہی روضۂ رسول بنا۔",descriptionEnglish:"The Prophet ﷺ passed away in her embrace, resting eternally within her room."},{eventTitleUrdu:"کبار صحابہ کی فقہی رہنمائی اور فتاویٰ کا مسند",eventTitleEnglish:"Juristic Authority and Decrees to the Sahabah",descriptionUrdu:"حضرت عمر اور عثمان کے دور میں فتاویٰ دینا اور احادیث کی تدریس فرمانا۔",descriptionEnglish:"Issued definitive legal rulings and trained the greatest scholars of Islam."},{eventTitleUrdu:"وصالِ مبارک اور جنت البقیع میں تدفین",eventTitleEnglish:"Demise and Resting in Jannat al-Baqi",descriptionUrdu:"۵۸ ہجری میں وصال فرمایا اور جنت البقیع میں ازواجِ مطہرات کے ساتھ مدفون ہوئیں۔",descriptionEnglish:"Passed away in 58 AH, laid to rest in Jannat al-Baqi under night skies."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن شہاب الزہری (رحمہ اللہ)",scholarNameEnglish:"Imam Ibn Shihab al-Zuhri",bookTitle:"تہذیب التہذیب",verbatimQuoteUrdu:"اگر تمام لوگوں کا علم اور تمام ازواج کا علم جمع کیا جائے تو عائشہ کا علم ان سب سے وسیع تر نکلے گا۔",verbatimQuoteEnglish:"If the knowledge of all people and all wives of the Prophet were gathered, Aisha's knowledge would surpass them all."},{scholarNameUrdu:"امام بدر الدین الزرکشی (رحمہ اللہ)",scholarNameEnglish:"Imam Badr al-Din al-Zarkashi",bookTitle:"الإجابة لإيراد ما استدركته عائشة على الصحابة",verbatimQuoteUrdu:"سیدتنا عائشہ نے نہ صرف احادیث روایت کیں بلکہ فہم، قیاس اور استدلال میں کبار صحابہ کی علمی تصحیح فرمائی۔",verbatimQuoteEnglish:"Aisha not only transmitted Hadith, but audited and corrected senior companions through profound juristic critique."}]},{id:"sah-03",nameUrdu:"سیدۂ کائنات حضرت فاطمۃ الزہراء",nameArabic:"فاطمة بنت رسول الله الزهراء البتول (رضي الله عنها)",nameEnglish:"Sayyidatuna Fatimah az-Zahra (رضي الله عنها)",titleUrdu:"سیدۃ نساء اہل الجنہ، بتول، زہراء، بضعۃ النبی، ام ابیہا",titleEnglish:"Leader of the Women of Paradise, Az-Zahra, Badi'at al-Nabi",kinshipToProphet:"رسول اللہ ﷺ کی سب سے چہیتی صاحبزادی، حضرت علی المرتضیٰ کی زوجہ، حسنین کریمین کی والدہ ماجدہ",kinshipToProphetEnglish:"Beloved Youngest Daughter of the Prophet ﷺ, Mother of the Youths of Paradise (Imam Hasan and Imam Husayn)",classicalCitation:"صحیح البخاری، حدیث ۳۷۱۴، ۳۷۶۷ / صحیح مسلم، حدیث ۲۴۴۹",era:"متوفی ۱۱ ہجری (وصالِ نبوی کے ۶ ماہ بعد مدینہ منورہ)",biographyUrdu:"رسول اللہ ﷺ کے جگر کا ٹکڑا، حسن و سیرت میں ہو بہو شبیہِ مصطفیٰ، اور جنت کی تمام عورتوں کی سردار۔ بچپن میں مکہ میں حضور ﷺ کا دفاع کیا، فقر و فاقہ میں چکی پیستے ہوئے صبر و قناعت کی تاریخ رقم کی اور حسنین کریمین جیسی پاکیزہ نسل پروان چڑھائی۔",biographyEnglish:"The flesh and blood of the Prophet ﷺ, his mirror image in noble carriage and character, and the Leader of the Women of Paradise. Stood fearlessly in childhood defending the Prophet at the Ka'bah, personified absolute contentment in poverty, and mothered the sacred Hasani-Husayni lineage.",heroicAttributes:["اعلیٰ ترین حیا اور عفت","بے مثل زہد، قناعت اور صبر","حضور ﷺ سے بے پناہ عشق اور شبیہِ نبوی","اہلِ بیتِ اطہار کی سرداری"],heroicAttributesEnglish:["Supreme Piety","Patience in Poverty","Devotion to Parents","Dignity of Labor"],dailySunnahLessons:[{ur:"سادگی، قناعت اور پردے کو اپنی زینت بنانا اور دنیاوی نمود و نمائش سے بچنا۔",en:"Adopting contentment and modesty, steering clear of ostentatious worldly displays."},{ur:"گھر کے کام کاج کو عبادت کی نیت سے صبر اور اخلاص کے ساتھ انجام دینا۔",en:"Carrying out household duties with patience, viewing family care as rewarded worship."},{ur:"تسبیحِ فاطمہ (۳۳ سبحان اللہ، ۳۳ الحمد للہ، ۳۴ اللہ اکبر) کو ہر رات سوتے وقت لازم پڑھنا۔",en:"Reciting Tasbih-e-Fatimah before sleeping every night for spiritual and physical strength."}],sanadVerificationHash:"SANAD-FATIMAH-BUKHARI-SAHIH-003",lineageAndBackgroundUrdu:'سیدہ فاطمہ بنت سید الاولین والآخرین محمد بن عبد اللہ ﷺ۔ آپ کی والدہ ماجدہ ام المؤمنین سیدتنا خدیجہ الکبریٰ رضی اللہ عنہا ہیں۔ آپ مکہ مکرمہ میں بعثت کے وقت پیدا ہوئیں اور نورِ نبوت کے سایۂ عاطفت میں پرورش پائی۔ آپ کا لقب "زہراء" (روشن و چمکدار چہرے والی) اور "بتول" (دنیا کی آلائشوں سے کٹ کر خالص اللہ کی عبادت میں مگن رہنے والی) تھا۔',lineageAndBackgroundEnglish:"Fatimah bint Muhammad ﷺ, daughter of the Seal of Prophets and Khadijah al-Kubra. Born in Makkah around the commencement of revelation. Titled Az-Zahra (The Radiant) and Al-Batul (The Ascetic Devotee devoted solely to Allah).",propheticPraiseHadithArabic:"\xabفَاطِمَةُ بَضْعَةٌ مِنِّي، فَمَنْ أَغْضَبَهَا أَغْضَبَنِي\xbb [صحيح البخاري: ۳۷۱۴] — وَقَالَ ﷺ: \xabيَا فَاطِمَةُ، أَمَا تَرْضَيْنَ أَنْ تَكُونِي سَيِّدَةَ نِسَاءِ أَهْلِ الجَنَّةِ؟\xbb [صحيح البخاري: ۳۶۲۴]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "فاطمہ میرے جگر کا ٹکڑا ہے، جس نے اسے ناراض کیا اس نے مجھے ناراض کیا"۔ اور سرگوشی میں فرمایا: "اے فاطمہ! کیا تم اس بات پر راضی نہیں ہو کہ تم جنت کی تمام عورتوں کی سردار ہو؟"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ proclaimed: "Fatimah is a part of me; whoever angers her angers me." (Sahih al-Bukhari) And he whispered to her: "O Fatimah, are you not pleased to be the Leader of the Women of Paradise?" (Sahih al-Bukhari)',propheticPraiseSource:"صحیح البخاری، کتاب فضائل اصحاب النبی، حدیث رقم ۳۷۱۴، ۳۶۲۴ / صحیح مسلم، حدیث رقم ۲۴۴۹",exhaustiveBiographyUrdu:['سیدتنا فاطمۃ الزہراء رضی اللہ عنہا کا مقام و مرتبہ تمام کائنات کی خواتین میں سب سے بلند ہے۔ سیدتنا عائشہ صدیقہ فرماتی ہیں: "میں نے شکل و صورت، گفتگو، عادات و اطوار اور اٹھنے بیٹھنے میں رسول اللہ ﷺ سے زیادہ مشابہ فاطمہ کے علاوہ کسی اور کو نہیں دیکھا۔ جب بھی وہ تشریف لاتیں، حضور ﷺ فرطِ محبت سے کھڑے ہو جاتے، ان کا ہاتھ چومتے اور اپنی جگہ پر بٹھاتے تھے"۔','بچپن ہی میں جب کفارِ مکہ نے کعبہ میں حالتِ سجدہ میں حضور ﷺ کی پشتِ مبارک پر اونٹ کی اوجھڑی ڈالی، تو یہ ننھی شہزادی تن تنہا دوڑتی ہوئی آئیں، اپنے ہاتھوں سے نجاست کو ہٹایا اور قریش کے سرداروں کو جھنجھوڑ دیا۔ اسی جاں نثاری کی بنا پر حضور ﷺ انہیں "ام ابیہا" (اپنے باپ کی ماں) کا پیارا لقب دیتے تھے۔',"حضرت علی المرتضیٰ رضی اللہ عنہ کے ساتھ نکاحِ مبارک انتہائی سادگی کے ساتھ عمل میں آیا۔ جہیز میں صرف ایک بستر، چمڑے کا تکیہ، مشکیزہ اور چکی تھی۔ آپ گھر کا تمام کام خود کرتیں، چکی پیستے پیستے مبارک ہاتھوں میں چھالے پڑ جاتے اور مشک اٹھاتے اٹھاتے سینے پر نشانات پڑ جاتے مگر زبان پر کبھی شکوہ نہیں آیا۔ جب حضور ﷺ سے خادم مانگنے گئیں تو حضور ﷺ نے خادم کے بدلے تسبیحِ فاطمہ کا تحفہ عطا فرمایا۔","غزوۂ احد میں جب حضور ﷺ کا چہرۂ انور زخمی ہوا اور خون رک نہیں رہا تھا، تو سیدہ فاطمہ نے چٹائی جلا کر اس کی راکھ زخم پر لگائی جس سے خون تھم گیا۔",'حضور اقدس ﷺ کے وصال پر آپ پر غم کے وہ پہاڑ ٹوٹے جنہیں بیان کرتے ہوئے آپ نے فرمایا: "صُبَّتْ عَلَيَّ مَصَائِبُ لَوْ أَنَّهَا، صُبَّتْ عَلَى الْأَيَّامِ صِرْنَ لَيَالِيَا" (مجھ پر ایسی مصیبتیں انڈیل دی گئیں کہ اگر وہ روشن دنوں پر پڑتیں تو وہ سیاہ راتوں میں بدل جاتیں)۔ حضور ﷺ کے وصال کے محض ۶ ماہ بعد ۳ رمضان ۱۱ ہجری کو مدینہ منورہ میں وصال فرمایا۔'],exhaustiveBiographyEnglish:['Sayyidatuna Fatimah az-Zahra (رضي الله عنها) holds the supreme station among the women of all creation. Sayyidatuna Aisha testified: "I never saw anyone who resembled the Prophet ﷺ more in speech, manners, and demeanor than Fatimah. Whenever she entered, the Prophet ﷺ would stand up to welcome her, kiss her hand, and seat her in his own place."','In early childhood in Makkah, when Quraysh tyrants dumped filth upon the Prophet ﷺ while he was prostrating before the Ka\'bah, young Fatimah ran forward fearlessly, cleansed her father with her own hands, and rebuked the pagan chiefs, earning the title "Umm Abiha" (Mother of her Father).',"Her marriage to Ali ibn Abi Talib was celebrated with celestial simplicity. Her dowry comprised a sheepskin bed, a leather pillow stuffed with palm fiber, a water-skin, and a hand-mill. She performed all arduous household chores herself until blisters formed on her hands, personifying sublime asceticism.","At the Battle of Uhud, when the Prophet's helmet was broken and his blessed face was bleeding profusely, Fatimah burned a piece of straw matting and applied its ashes to stem the flow of blood.","Following the passing of the Prophet ﷺ, she lived in profound spiritual contemplation, passing away just six months later on the 3rd of Ramadan, 11 AH, at the young age of 29. In accordance with her supreme modesty, her funeral was carried out quietly at night in Jannat al-Baqi."],majorHistoricalMilestones:[{eventTitleUrdu:"کعبہ میں حضور ﷺ کا کمسنی میں دلیرانہ دفاع",eventTitleEnglish:"Heroic Defense of the Prophet at the Ka'bah",descriptionUrdu:"مشرکین کے سجدے میں اوجھڑی ڈالنے پر نجاست ہٹائی اور کفار کو للکارا۔",descriptionEnglish:"Fearlessly removed filth placed upon the Prophet during Sujud at the Ka'bah."},{eventTitleUrdu:"حضرت علی سے نکاح اور تسبیحِ فاطمہ کا عطیہ",eventTitleEnglish:"Marriage to Ali and the Gift of Tasbih-e-Fatimah",descriptionUrdu:"انتہائی سادگی سے نکاح ہوا اور حضور ﷺ نے سونے سے قبل تسبیح کا نبوی تحفہ دیا۔",descriptionEnglish:"Wed Ali in celestial simplicity, receiving the immortal gift of Tasbih-e-Fatimah."},{eventTitleUrdu:"غزوۂ احد میں رسول اللہ ﷺ کے زخموں کی مرہم پٹی",eventTitleEnglish:"Nursing the Prophet's Wounds at Uhud",descriptionUrdu:"چٹائی کی راکھ لگا کر حضور ﷺ کے چہرۂ انور کا خون بند کیا۔",descriptionEnglish:"Tended to the Prophet's facial wounds at Uhud, staunching the bleeding with ashes."},{eventTitleUrdu:"جنت کی تمام عورتوں کی سرداری کی بشارت",eventTitleEnglish:"Proclamation as Leader of the Women of Paradise",descriptionUrdu:"حضور ﷺ نے راز میں سرگوشی فرما کر سیدۃ نساء اہل الجنہ کی خوشخبری دی۔",descriptionEnglish:"Prophetically designated as Sayyidat Nisa' Ahl al-Jannah by her noble father."},{eventTitleUrdu:"وصالِ مبارک اور رات کے اندھیرے میں تدفین",eventTitleEnglish:"Demise and Nocturnal Burial in Baqi",descriptionUrdu:"وصالِ نبوی کے ۶ ماہ بعد وصال فرمایا اور وصیت کے مطابق رات کو تدفین ہوئی۔",descriptionEnglish:"Passed away 6 months after the Prophet ﷺ, laid to rest at night in Jannat al-Baqi."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام جلال الدین السیوطی (رحمہ اللہ)",scholarNameEnglish:"Imam Jalal al-Din al-Suyuti",bookTitle:"ثغور الباسم في مناقب سيدتنا فاطمة",verbatimQuoteUrdu:"سیدہ فاطمہ الزہراء بضعۃ منی کا وہ پاکیزہ نور ہیں جن کی تعظیم و محبت ہر مومن پر فرض ہے۔",verbatimQuoteEnglish:"Fatimah az-Zahra is the immaculate light of the Prophetic essence whose love and reverence is obligatory upon every believer."},{scholarNameUrdu:"شیخ عبد الحق محدث دہلوی (رحمہ اللہ)",scholarNameEnglish:"Shaykh Abd al-Haqq Muhaddith Dehlawi",bookTitle:"مدارج النبوۃ (قسم پنجم)",verbatimQuoteUrdu:"سیدہ بتول کا زہد اور حیا کائنات کی تمام خواتین کے لیے قیامت تک کا معیار ہے۔",verbatimQuoteEnglish:"The asceticism and modesty of Sayyidah al-Batul remains the eternal benchmark for all women until the Day of Judgment."}]},{id:"sah-04",nameUrdu:"ام المؤمنین سیدتنا ام سلمہ",nameArabic:"هند بنت أبي أمية بن المغيرة المخزومية (رضي الله عنها)",nameEnglish:"Sayyidatuna Umm Salamah (رضي الله عنها)",titleUrdu:"ام المؤمنین، صاحبۃ الرائے الصائب، مہاجرۃ الہجرتین",titleEnglish:"Mother of the Believers, The Wise Counselor of Hudaybiyyah",kinshipToProphet:"رسول اللہ ﷺ کی زوجۂ مطہرہ، قریش کے مخزوم قبیلے کی معزز ترین خاتون",kinshipToProphetEnglish:"Noble Spouse of the Prophet ﷺ, Renowned Jurist and Wise Counselor at the Truce of Hudaybiyyah",classicalCitation:"صحیح البخاری، حدیث ۲۷۳۱، ۲۷۳۲ / صحیح مسلم، حدیث ۹۱۸",era:"متوفی ۶۲ ہجری مدینہ منورہ (سب سے آخر میں وصال پانے والی زوجۂ مطہرہ)",biographyUrdu:'حبشہ اور مدینہ دونوں طرف ہجرت کرنے والی جلیل القدر خاتون۔ صلحِ حدیبیہ کے موقع پر آپ کی بے مثل حکمت اور دانشمندانہ مشورے نے امت کو بحران سے نکالا۔ مصیبت کے وقت ان کی سکھائی ہوئی دعا "اللهم أجرني في مصيبتي" ہر مسلمان کے لیے مشعلِ راہ ہے۔',biographyEnglish:"Migrant of both Abyssinia and Madinah. Celebrated for her consummate political intellect and wisdom. At the Treaty of Hudaybiyyah, her strategic counsel saved the Muslim army from spiritual crisis. She was the last of the Mothers of the Believers to pass away.",heroicAttributes:["گہری سیاسی و معاشرتی بصیرت","مصیبت میں انا للہ کا مکمل یقین","فقہی و روایتی مہارت","یتیم بچوں کی مثالی تربیت"],heroicAttributesEnglish:["Political Wisdom","Profound Patience","Sound Counsel","Legal Understanding"],dailySunnahLessons:[{ur:'کسی بھی نقصان یا صدمے پر یہ مسنون دعا پڑھنا: "اللهم أجرني في مصيبتي وأخلف لي خيراً منها"۔',en:'Supplicating during any loss: "O Allah, reward me in my affliction and grant me better in return."'},{ur:"گھریلو اور خاندانی مسائل میں جلد بازی کے بجائے گہری حکمت اور صبر سے مشورہ دینا۔",en:"Offering thoughtful, sincere, and constructive counsel when asked for guidance."}],sanadVerificationHash:"SANAD-UMM-SALAMAH-BUKHARI-004",lineageAndBackgroundUrdu:'ہند بنت ابی امیہ بن المغیرہ بن عبد اللہ بن عمر بن مخزوم القرشیہ المخزومیہ۔ آپ کے والد ابو امیہ مکہ کے اس قدر سخی رئیس تھے کہ انہیں "زاد الرکب" (قافلے والوں کا خرچ اٹھانے والا) کہا جاتا تھا۔ آپ کے پہلے شوہر ابو سلمہ عبد اللہ بن عبد الاسد مخزومی تھے، جو اسلام کے اولین جاں نثاروں میں سے تھے۔',lineageAndBackgroundEnglish:"Hind bint Abi Umayyah ibn al-Mughirah al-Makhzumiyyah. Her father was so famously generous that he was titled Zad al-Rakib (The Provider of Caravans). Her first husband was Abu Salamah, one of the earliest champions of Islam.",propheticPraiseHadithArabic:"\xabمَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللَّهُ: {إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ} اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللَّهُ لَهُ خَيْرًا مِنْهَا\xbb [صحيح مسلم: ۹۱۸]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے فرمایا: "جس مسلمان کو بھی کوئی مصیبت پہنچے اور وہ یہ دعا پڑھے: {انا للہ وانا الیہ راجعون} اے اللہ مجھے میری مصیبت میں اجر عطا فرما اور اس کا بہترین نعم البدل عطا فرما، تو اللہ تعالیٰ اسے اس سے بہتر نعم البدل عطا فرماتا ہے"۔ سیدہ ام سلمہ فرماتی ہیں کہ جب ابو سلمہ کا وصال ہوا تو میں نے یہ دعا پڑھی اور اللہ نے مجھے رسول اللہ ﷺ کا رشتہ عطا فرمایا۔',propheticPraiseHadithEnglish:'The Prophet ﷺ taught: "Whenever a Muslim is afflicted by calamity and recites: {Inna Lillahi wa Inna Ilayhi Raji\'un} O Allah, reward me in my affliction and replace it with better, Allah surely grants them better in exchange." (Sahih Muslim)',propheticPraiseSource:"صحیح مسلم، کتاب الجنائز، حدیث رقم ۹۱۸",exhaustiveBiographyUrdu:["سیدتنا ام سلمہ رضی اللہ عنہا نہ صرف حیا اور تقویٰ کی پیکر تھیں بلکہ اسلام کی تاریخ میں اعلیٰ ترین بصیرت اور عقل و فہم کی حامل خاتون تھیں۔ جب آپ نے اپنے شوہر ابو سلمہ کے ساتھ ہجرت کا ارادہ کیا، تو بنو مخزوم نے آپ کو روک لیا اور آپ کے ننھے بچے سلمہ کو چھین لیا۔ آپ ایک سال تک روزانہ مکہ سے باہر آ کر روتی رہیں حتیٰ کہ قریش کے دل پسیج گئے اور آپ نے تن تنہا مکہ سے مدینہ کا خطرناک صحرائی سفر طے کر کے ہجرت مکمل فرمائی۔",'جب غزوۂ احد میں حضرت ابو سلمہ کے زخموں نے شدت اختیار کی اور ان کا وصال ہوا، تو رسول اللہ ﷺ نے سیدتنا ام سلمہ کو نکاح کا پیغام بھیجا۔ انہوں نے عاجزی سے عرض کیا: "یا رسول اللہ! مجھ میں تین باتیں ہیں: میں سخت غیرت مند ہوں، صاحبِ اولاد ہوں اور میری عمر ڈھل چکی ہے"۔ حضور ﷺ نے شفقت سے فرمایا: "اللہ تمہاری غیرت دور فرما دے گا، تمہارے بچے میرے بچے ہیں اور عمر میری بھی ڈھل چکی ہے"۔','صلحِ حدیبیہ کے کڑے موقع پر جب معاہدہ لکھا گیا اور صحابہ کرام صدمے اور ملال کے باعث احرام کھولنے اور قربانی کرنے سے ٹھٹک رہے تھے، تو رسول اللہ ﷺ مغموم ہو کر ام سلمہ کے خیمے میں تشریف لائے۔ ام سلمہ نے وہ تاریخی مشورہ دیا جو سنہری حروف سے لکھا گیا: "یا رسول اللہ! آپ کسی سے کچھ نہ کہیے، باہر تشریف لے جائیے اور خود اپنا اونٹ ذبح کر کے سر منڈوا لیجیے"۔ چنانچہ جب صحابہ نے حضور ﷺ کو دیکھا تو سب نے فورا پیروی کی اور ایک بہت بڑا بحران ٹل گیا۔',"آپ نے رسول اللہ ﷺ سے ۳۷۸ احادیث مبارکہ روایت فرمائیں۔ ازواجِ مطہرات میں سب سے طویل عمر پائی اور ۶۲ ہجری میں سانحۂ کربلا کے بعد مدینہ منورہ میں وصال فرمایا۔"],exhaustiveBiographyEnglish:["Sayyidatuna Umm Salamah (رضي الله عنها) was a beacon of extraordinary intelligence, patience, and political acumen. When she first attempted to migrate to Madinah, pagan clans seized her young son and barred her travel. For an entire year, she wept in the outskirts of Makkah until clan elders softened, allowing her to undertake the perilous journey to Madinah.",'Following the death of Abu Salamah from wounds sustained at Uhud, she supplicated as the Prophet ﷺ taught. When the Prophet proposed, she modestly noted her jealousy and large family; the Prophet ﷺ assured her with unmatched mercy: "Your children are my children, and I will pray that Allah removes your jealousy."',"Her moment of historic statesmanship occurred at the Treaty of Hudaybiyyah in 6 AH. Shocked by the treaty's terms, the companions froze when commanded to shave their heads and sacrifice their animals. Seeing the Prophet's distress, Umm Salamah counseled: \"O Messenger of Allah, do not command them verbally. Go out, slaughter your camel, and have your head shaved in their sight.\" The moment the companions saw his action, they rushed to follow suit, averting catastrophic disobedience.","Transmitting 378 traditions, she outlived all other Mothers of the Believers, passing away in 62 AH at the age of 84 following the tragedy of Karbala. She was laid to rest in Jannat al-Baqi."],majorHistoricalMilestones:[{eventTitleUrdu:"حبشہ اور مدینہ منورہ کی دوہری ہجرت اور صبر",eventTitleEnglish:"Dual Migration to Abyssinia and Madinah",descriptionUrdu:"بچے سے علیحدگی کے باوجود استقامت دکھائی اور صحرا کا تن تنہا سفر کیا۔",descriptionEnglish:"Endured family separation and completed the arduous solitary migration to Madinah."},{eventTitleUrdu:"ابو سلمہ کی شہادت اور نکاحِ نبوی کا شرف",eventTitleEnglish:"Widowhood and Marriage to the Prophet ﷺ",descriptionUrdu:"مسنون دعا کے نعم البدل کے طور پر رسول اللہ ﷺ کے حرم میں داخل ہوئیں۔",descriptionEnglish:"Blessed with marriage to the Prophet ﷺ as the divine reward of her patient prayer."},{eventTitleUrdu:"صلحِ حدیبیہ کا تاریخی دانشمندانہ مشورہ",eventTitleEnglish:"The Strategic Counsel at Hudaybiyyah",descriptionUrdu:"احرام کھولنے اور قربانی کا وہ مشورہ دیا جس نے لشکرِ اسلام کو متحد کر دیا۔",descriptionEnglish:"Her decisive advice to the Prophet ﷺ averted crisis and preserved Muslim unity."},{eventTitleUrdu:"طویل ترین حیات اور سانحۂ کربلا پر گریہ",eventTitleEnglish:"Longest Lifespan and Grief over Karbala",descriptionUrdu:"سب سے آخر میں وصال پایا اور امام حسین کی شہادت پر زار و قطار روئیں۔",descriptionEnglish:"Surviving all Mothers of the Believers, she deeply mourned the martyrdom of Imam Husayn."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن کثیر (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Kathir",bookTitle:"البداية والنهاية",verbatimQuoteUrdu:"ام سلمہ عقل، دیانت، پاکدامنی اور صائب الرائے ہونے میں تمام خواتین کے لیے ایک درخشندہ مثال تھیں۔",verbatimQuoteEnglish:"Umm Salamah was an illustrious paragon of intellect, piety, chastity, and infallible counsel."}]},{id:"sah-05",nameUrdu:"سیدتنا اسماء بنت ابی بکر (ذات النطاقین)",nameArabic:"أسماء بنت أبي بكر الصديق التيمية (رضي الله عنها)",nameEnglish:"Sayyidatuna Asma bint Abi Bakr (رضي الله عنها)",titleUrdu:"ذات النطاقین (دو کمر بند والی)، شجاعۃ الایمان",titleEnglish:"Dhat an-Nitaqayn (Possessor of the Two Belts)",kinshipToProphet:"ام المؤمنین عائشہ کی بڑی ہمشیرہ، حضرت ابوبکر کی بیٹی، حواریِ رسول حضرت زبیر بن عوام کی زوجہ، عبداللہ بن زبیر کی والدہ",kinshipToProphetEnglish:"Daughter of Sayyiduna Abu Bakr al-Siddiq, Elder Sister of Sayyidah Aisha, Mother of Abdullah ibn al-Zubayr",classicalCitation:"صحیح البخاری، حدیث ۲۹۷۹، ۳۱۱۶ / صحیح مسلم، حدیث ۲۵۰۵",era:"متوفی ۷۳ ہجری مکہ مکرمہ (۱۰۰ سال کی عمر مبارک)",biographyUrdu:'ہجرتِ نبوی کی عظیم ہیروئن جنہوں نے غارِ ثور میں کھانا پہنچانے کے لیے اپنا کمر بند پھاڑ کر سامان باندھا، جس پر حضور ﷺ نے "ذات النطاقین" کا لقب عطا فرمایا۔ ابو جہل کے ظالمانہ تھپڑ کھا کر بھی راز فاش نہ کیا۔ سو سال کی عمر میں ظالم حجاج بن یوسف کے سامنے حق کا کلمہ بلند کیا۔',biographyEnglish:"The fearless heroine of the Hijrah who tore her waist-belt in two to secure provisions for the Prophet ﷺ in Cave Thawr. Endured Abu Jahl's violent strike without breaking silence, lived to age 100 with pristine intellect, and fearlessly confronted the tyrant al-Hajjaj.",heroicAttributes:["بے پناہ جرات اور رازداری","محنت، مشقت اور خودداری","ظالم کے سامنے کلمۂ حق کہنا","اولاد میں غیرتِ ایمانی پیدا کرنا"],heroicAttributesEnglish:["Courage at Cave Thawr","Steely Endurance","Truthfulness","Fearlessness before Tyrants"],dailySunnahLessons:[{ur:"خاندان اور دوستوں کے رازوں کو اپنے سینے میں ہمیشہ محفوظ رکھنا۔",en:"Guarding family confidences and trust with ironclad loyalty."},{ur:"گھریلو محنت اور حلال مشقت سے کبھی عار محسوس نہ کرنا۔",en:"Embracing hard work with dignity, fortitude, and reliance on Allah."}],sanadVerificationHash:"SANAD-ASMA-BUKHARI-SAHIH-005",lineageAndBackgroundUrdu:"اسماء بنت ابی بکر صدیق عبد اللہ بن عثمان التیمیہ القرشیہ۔ آپ حضرت عائشہ صدیقہ سے ۱۰ سال بڑی تھیں۔ اسلام کی اٹھارہویں (۱۸) مسلمان ہونے کا شرف حاصل کیا۔ آپ کا نکاح رسول اللہ ﷺ کے پھوپھی زاد اور جاں نثار صحابی حضرت زبیر بن عوام رضی اللہ عنہ سے ہوا۔",lineageAndBackgroundEnglish:"Asma bint Abi Bakr as-Siddiq. Ten years older than her sister Aisha, she was the 18th person to embrace Islam in Makkah. Married to the Prophet's cousin and disciple, Zubayr ibn al-Awwam.",propheticPraiseHadithArabic:"\xabأَبْدَلَكِ اللَّهُ بِنِطَاقِكِ هَذَا نِطَاقَيْنِ فِي الجَنَّةِ\xbb [صحيح البخاري: ۲۹۷۹]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے فرمایا: "اللہ تعالیٰ نے تمہارے اس کمر بند کے بدلے جنت میں تمہیں دو نورانی کمر بند عطا فرمائے ہیں"۔',propheticPraiseHadithEnglish:'The Messenger of Allah ﷺ said to her: "Allah has replaced this belt of yours with two belts in Paradise." (Sahih al-Bukhari)',propheticPraiseSource:"صحیح البخاری، کتاب الجہاد، حدیث رقم ۲۹۷۹",exhaustiveBiographyUrdu:['سیدتنا اسماء رضی اللہ عنہا استقامت، شجاعت اور خودداری کا وہ درخشندہ مینار تھیں جنہوں نے ہجرت کے کڑے لمحات میں تاریخ لکھی۔ ہجرت کی رات جب حضور ﷺ اور حضرت ابوبکر غارِ ثور میں تشریف فرما تھے، تو سیدتنا اسماء رات کے اندھیرے میں خطرناک راستوں سے کھانا اور پانی پہنچاتیں۔ روانگی کے وقت جب سامان باندھنے کے لیے کوئی رسی نہ ملی تو انہوں نے اپنا کمر بند (نطاق) پھاڑ کر دو ٹکڑے کیے اور مشکیزہ و کھانا باندھ دیا۔ حضور ﷺ نے انہیں "ذات النطاقین" کا ابدی لقب دیا۔',"جب ابو جہل تلوار لے کر گھر آیا اور پوچھا کہ تیرا باپ کہاں ہے، تو اس شیر دل خاتون نے خاموشی اختیار کی، جس پر ابو جہل نے اس زور کا تھپڑ مارا کہ ان کی بالی دور جا گری مگر ان کی زبان سے راز کا ایک شوشہ نہ نکلا۔","مدینہ منورہ پہنچ کر جب ان کے ہاں حضرت عبداللہ بن زبیر پیدا ہوئے، تو وہ ہجرت کے بعد مہاجرین کے ہاں پیدا ہونے والے پہلے بچے تھے، جس پر تمام مسلمانوں نے اللہ اکبر کا نعرہ لگایا کیونکہ یہودیوں نے افواہ اڑا رکھی تھی کہ مسلمانوں پر جادو ہو چکا ہے۔",'۷۳ ہجری میں جب حجاج بن یوسف نے مکہ پر چڑھائی کی اور کعبہ پر منجنیقیں برسائیں، تو سو سالہ ضعیفہ نابینا ہونے کے باوجود اپنے بیٹے عبداللہ بن زبیر کے سامنے چٹان بن کر کھڑی ہوئیں اور فرمایا: "اے میرے بیٹے! اگر تم حق پر ہو تو موت کی پروا نہ کرو، تلوار کا زخم ذلت کی زندگی سے ہزار گنا بہتر ہے"۔ جب بیٹے کی لاش سولی پر لٹکائی گئی تو حجاج کو دیکھ کر فرمایا: "کیا اس شہسوار کے اترنے کا وقت ابھی نہیں آیا؟"'],exhaustiveBiographyEnglish:["Sayyidatuna Asma (رضي الله عنها) was a titan of courage and endurance. During the Hijrah, she secretly scaled the rugged heights of Mount Thawr at night to deliver provisions to the Prophet ﷺ and Abu Bakr. Lacking a rope to secure the food, she tore her waist-belt into two strips, earning the Prophet's immortal title Dhat an-Nitaqayn (Possessor of Two Belts).","When Abu Jahl raided their home demanding her father's whereabouts, she met him with silence; he struck her so violently that her earring flew off, yet she revealed nothing.","Her son Abdullah ibn al-Zubayr was the first Muslim born in Madinah after the Hijrah, delivering a crushing refutation to pagan rumors that Muslims had been cursed with infertility.",'In 73 AH, at the grand age of 100, though blind, she counseled Abdullah ibn al-Zubayr as the ruthless tyrant al-Hajjaj laid siege to the Ka\'bah: "My son, if you are upon the truth, die for it honorably! A stroke of the sword is far nobler than a life of humiliation." When Hajjaj hung her martyred son upon a gibbet, she confronted the tyrant with majestic dignity.'],majorHistoricalMilestones:[{eventTitleUrdu:"غارِ ثور کی مہم اور ذات النطاقین کا شرف",eventTitleEnglish:"The Cave Thawr Mission and Title of Dhat an-Nitaqayn",descriptionUrdu:"راتوں کو کھانا پہنچایا اور کمر بند سے سامان باندھ کر بشارت پائی۔",descriptionEnglish:"Supplied Cave Thawr and earned the title Dhat an-Nitaqayn from the Prophet ﷺ."},{eventTitleUrdu:"ابو جہل کا سامنا اور رازداری کا کمال",eventTitleEnglish:"Standing Firm against Abu Jahl",descriptionUrdu:"طمانچے کھا کر بھی رسول اللہ ﷺ کی ہجرت کا راز فاش نہ کیا۔",descriptionEnglish:"Endured violent assault without compromising the Prophet's escape route."},{eventTitleUrdu:"مدینہ میں ہجرت کے پہلے بچے کی ولادت",eventTitleEnglish:"Birth of the First Muhajir Child in Madinah",descriptionUrdu:"حضرت عبداللہ بن زبیر کی پیدائش سے مدینہ میں خوشی کی لہر دوڑ گئی۔",descriptionEnglish:"Gave birth to Abdullah ibn al-Zubayr, breaking pagan superstitions."},{eventTitleUrdu:"۱۰۰ سال کی عمر میں ظالم حجاج کے سامنے للکار",eventTitleEnglish:"Confronting Al-Hajjaj at Age 100",descriptionUrdu:"حجاج کی بربریت کے سامنے بیٹے کو حق پر جان دینے کا حوصلہ دیا۔",descriptionEnglish:"Defiantly rebuked the tyrant al-Hajjaj with majestic eloquence at age 100."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"حافظ ابن کثیر (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Kathir",bookTitle:"البداية والنهاية",verbatimQuoteUrdu:"اسماء بنت ابی بکر دین، مروت، عقل اور شجاعت میں مردوں پر بھی سبقت لے جانے والی خاتون تھیں۔",verbatimQuoteEnglish:"Asma bint Abi Bakr surpassed even legendary men in courage, faith, and noble defiance."}]},{id:"sah-06",nameUrdu:"سیدتنا نسیبہ بنت کعب (ام عمارہ)",nameArabic:"نسيبة بنت كعب المازنية الأنصارية (رضي الله عنها)",nameEnglish:"Sayyidatuna Nusaybah bint Ka'b / Umm 'Umarah (رضي الله عنها)",titleUrdu:"فارسۃ الاسلام، مجاہدۂ احد، حامیۃ الرسول",titleEnglish:"The Knight of Islam, Defender of the Prophet at Uhud",kinshipToProphet:"انصار کی بیعتِ عقبہ ثانیہ کی اولین خاتون، مجاہدۂ اسلام",kinshipToProphetEnglish:"Noble Ansar Matron who took the Second Pledge of Aqabah, Steely Defender at the Battle of Uhud",classicalCitation:"الطبقات الکبریٰ لابن سعد، ج ۸، ص ۴۱۵ / سبل الہدیٰ والرشاد",era:"متوفی ۱۳ ہجری (جنگِ یمامہ کے بعد مدینہ منورہ)",biographyUrdu:'غزوۂ احد کی وہ دلیر مجاہدہ جنہوں نے اس نازک وقت میں تلوار اور تیر چلا کر رسول اللہ ﷺ کے گرد ڈھال بن کر دفاع کیا جب بڑے بڑوں کے پاؤں اکھڑ رہے تھے۔ رسول اللہ ﷺ نے دعا فرمائی: "اے اللہ! انہیں جنت میں میرا رفیق بنا دے"۔ جنگِ یمامہ میں مسیلمہ کذاب کے خلاف لڑتے ہوئے ایک ہاتھ کٹوا بیٹھیں مگر کذاب کے خاتمے تک ڈٹی رہیں۔',biographyEnglish:"The legendary warrior companion at Uhud who drew her sword and bow to shield the Prophet ﷺ when others retreated. The Prophet ﷺ prayed that she and her family would be his companions in Paradise. Later lost an arm at the Battle of Yamamah fighting Musaylimah the Liar.",heroicAttributes:["بے پناہ حربی شجاعت","حضور ﷺ سے والہانہ عشق اور جاں نثاری","مسیلمہ کذاب کے خلاف فیصلہ کن جہاد"],heroicAttributesEnglish:["Battlefield Valor","Direct Defense of the Prophet ﷺ","Steadfast Faith","Unmatched Heroism"],dailySunnahLessons:[{ur:"دینِ حق کے دفاع میں بزدلی اور کمزوری کو چھوڑ کر شجاعت اور بہادری پیدا کرنا۔",en:"Cultivating moral courage and steadfastness in upholding sacred truth."},{ur:"ہر دعا میں حضور ﷺ کی رفاقتِ جنت کا سوال کرنا۔",en:"Supplicating for the Prophet's close companionship in Jannat al-Firdaws."}],sanadVerificationHash:"SANAD-UMM-UMARAH-IBN-SAD-006",lineageAndBackgroundUrdu:"نسیبہ بنت کعب بن عمرو بن عوف بن مبذول الانصاریہ النجاریہ۔ آپ مدینہ منورہ کے قبیلہ خزرج کی شاخ بنو مازن سے تھیں۔ آپ نے بیعتِ عقبہ ثانیہ میں مکہ آ کر رات کی تاریکی میں رسول اللہ ﷺ کے دستِ حق پرست پر بیعت فرمائی۔",lineageAndBackgroundEnglish:"Nusaybah bint Ka'b al-Maziniyyah al-Ansariyyah. From the Banu Mazin of the Khazraj in Madinah. Pledged allegiance to the Prophet ﷺ during the Second Pledge of al-Aqabah.",propheticPraiseHadithArabic:"\xabمَا الْتَفَتُّ يَوْمَ أُحُدٍ يَمِينًا وَلَا شِمَالًا إِلَّا وَأَنَا أَرَاهَا تُقَاتِلُ دُونِي\xbb [الطبقات الكبرى لابن سعد: ۸/۴۱۵] — وَقَالَ ﷺ: \xabاللَّهُمَّ اجْعَلْهُمْ رُفَقَائِي فِي الجَنَّةِ\xbb",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے احد کے دن ارشاد فرمایا: "میں احد کے دن دائیں مڑتا یا بائیں، میں نسیبہ (ام عمارہ) کو ہی اپنی حفاظت میں تلوار چلاتے پاتا تھا"۔ اور ان کے لیے دعا فرمائی: "اے اللہ! نسیبہ اور اس کے گھر والوں کو جنت میں میرا رفیق بنا دے"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ testified regarding Uhud: "Whenever I looked to my right or to my left on the day of Uhud, I saw her fighting in my defense." And he prayed: "O Allah, make them my companions in Paradise!" (Ibn Sa\'d)',propheticPraiseSource:"الطبقات الکبریٰ لابن سعد، ج ۸، ص ۴۱۵ / دلائل النبوۃ للبیہقی",exhaustiveBiographyUrdu:["سیدتنا ام عمارہ رضی اللہ عنہا نے غزوۂ احد میں مشکیزہ اٹھا کر زخمیوں کو پانی پلانے کا کام شروع کیا، لیکن جب تیر اندازوں کی غلطی سے لشکرِ اسلام میں افراتفری مچی اور مشرکین نے رسول اللہ ﷺ کو گھیرے میں لے لیا، تو ام عمارہ نے مشکیزہ پھینک کر تلوار سونت لی اور کمان اٹھا لی۔ آپ اپنے شوہر زید اور دونوں بیٹوں حبیب اور عبداللہ کے ساتھ حضور ﷺ کے گرد سیسہ پلائی دیوار بن گئیں۔",'جب ابن قمیئہ ملعون نے رسول اللہ ﷺ پر وار کرنے کا ارادہ کیا، تو ام عمارہ نے آگے بڑھ کر اس پر تلوار سے کاری وار کیا، اگرچہ اس نے دوہری زرہ پہن رکھی تھی اس لیے بچ گیا اور اس نے ام عمارہ کے کاندھے پر ایسا گہرا زخم لگایا جس سے فوارے کی طرح خون ابل پڑا۔ حضور ﷺ نے ان کے بیٹے سے فرمایا: "اپنی ماں کی پٹی باندھو! تمہاری ماں کا مقام فلاں فلاں سے بلند ہے"۔','اس دن ام عمارہ کے جسم پر نیزوں اور تیروں کے ۱۲ کاری زخم آئے، لیکن انہوں نے زخموں کی پروا کیے بغیر قتال جاری رکھا۔ جب حضور ﷺ نے پوچھا کہ کچھ مانگو، تو انہوں نے صرف یہ عرض کیا: "یا رسول اللہ! دعا فرمائیے کہ اللہ ہمیں جنت میں آپ کی رفاقت نصیب فرمائے"۔ حضور ﷺ نے فورا دعا فرمائی، جس پر انہوں نے پکارا: "اب مجھے دنیا کی کسی مصیبت کی پروا نہیں!"',"دورِ فاروقی میں جنگِ یمامہ میں جب مسیلمہ کذاب نے ان کے بیٹے حبیب کو ٹکڑے ٹکڑے کر کے شہید کر دیا، تو یہ بہادر ماں یمامہ کے میدان میں پہنچی اور ۱۱ زخم کھائے اور اپنا ایک ہاتھ کٹوا بیٹھی، یہاں تک کہ مسیلمہ کذاب واصلِ جہنم ہوا۔"],exhaustiveBiographyEnglish:["At the Battle of Uhud in 3 AH, Nusaybah bint Ka'b initially tended to the wounded. However, when the lines shattered and pagan cavalry surrounded the Prophet ﷺ, she cast aside her water-skin, unsheathed her sword, and took up a bow, forming a living human fortress around the Messenger of Allah alongside her husband and two sons.","When the pagan champion Ibn Qami'ah charged aiming to slay the Prophet ﷺ, Nusaybah intercepted him, striking him repeatedly before suffering a deep wound to her shoulder. The Prophet ﷺ ordered her son: \"Bandage your mother's wound! May Allah bless your household!\"",'She sustained 12 severe wounds that day. When the Prophet ﷺ asked what she desired, she requested no worldly comfort, only pleading: "Pray to Allah that we may be your companions in Paradise!" The Prophet ﷺ prayed: "O Allah, make them my companions in Paradise!" Upon hearing this, she cried: "Now I care not for whatever afflicts me in this world!"',"Later, during the Caliphate of Abu Bakr, when Musaylimah the Liar murdered her son Habib, the aging heroine marched to the Battle of Yamamah. She sustained 11 wounds and severed her arm in combat until the false prophet was slain."],majorHistoricalMilestones:[{eventTitleUrdu:"بیعتِ عقبہ ثانیہ میں مدینہ کا معاہدہ",eventTitleEnglish:"The Second Pledge of al-Aqabah",descriptionUrdu:"رات کے وقت مکہ آ کر حضور ﷺ کے دستِ حق پر بیعت فرمائی۔",descriptionEnglish:"Pledged allegiance to the Prophet ﷺ in Makkah alongside early Ansar leaders."},{eventTitleUrdu:"غزوۂ احد میں تلوار سونت کر رسول اللہ ﷺ کا دفاع",eventTitleEnglish:"Heroic Sword Combat at the Battle of Uhud",descriptionUrdu:"۱۲ کاری زخم کھا کر حضور ﷺ کے گرد سیسہ پلائی دیوار بن گئیں۔",descriptionEnglish:"Shielded the Prophet ﷺ with sword and bow, sustaining 12 severe combat wounds."},{eventTitleUrdu:"جنت میں رفاقتِ نبوی کی دائمی بشارت",eventTitleEnglish:"Prophetic Guarantee of Companionship in Paradise",descriptionUrdu:"حضور ﷺ نے ان کے اور ان کے خاندان کے لیے جنت کی رفاقت کی دعا فرمائی۔",descriptionEnglish:"Earned the Prophet's prayer for eternal companionship in Jannat al-Firdaws."},{eventTitleUrdu:"جنگِ یمامہ میں ہاتھ کٹوا کر مسیلمہ کذاب کا خاتمہ",eventTitleEnglish:"Battle of Yamamah and Severing of Her Arm",descriptionUrdu:"مسیلمہ کے خلاف قتال میں ایک ہاتھ شہید ہوا مگر فتح تک ڈٹی رہیں۔",descriptionEnglish:"Fought Musaylimah's army, lost an arm, and witnessed the victory of Islam."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن سعد (رحمہ اللہ)",scholarNameEnglish:"Allama Ibn Sa'd",bookTitle:"الطبقات الکبریٰ (جلد ۸)",verbatimQuoteUrdu:"ام عمارہ شجاعت اور دلیری میں کائنات کی ان چند ہستیوں میں سے ہیں جن کی نظیر تاریخ پیش کرنے سے قاصر ہے۔",verbatimQuoteEnglish:"Umm 'Umarah demonstrated valor in combat that history has rarely witnessed in any woman."}]},{id:"sah-07",nameUrdu:"سیدتنا سمیہ بنت خیاط (اول شہیدہ)",nameArabic:"سمية بنت خياط أم عمار بن ياسر (رضي الله عنها)",nameEnglish:"Sayyidatuna Sumayyah bint Khayyat (رضي الله عنها)",titleUrdu:"اول شہیدہ فی الاسلام، شہیدۃ التوحید",titleEnglish:"The First Martyr of Islam",kinshipToProphet:"سابقینِ اولین، حضرت عمار بن یاسر کی والدہ ماجدہ، آلِ یاسر",kinshipToProphetEnglish:"First Martyr of Islam, Mother of Sayyiduna Ammar ibn Yasir, Exemplar of the House of Yasir",classicalCitation:"الطبقات الکبریٰ لابن سعد، ج ۸، ص ۲۶۴ / الاصابة لابن حجر، ج ۸",era:"قبلِ ہجرت ۷ سال قبل مکہ مکرمہ",biographyUrdu:"اسلام کی اولین شہید خاتون۔ مکہ کی تپتی ریت پر جب ابو جہل نے دہکتے انگاروں پر لٹا کر کفر بکنے کا مطالبہ کیا، تو اس ضعیفہ نے کلمۂ توحید کا نعرہ بلند کیا۔ ابو جہل نے غصے میں آ کر نیزہ مار کر شہید کیا۔ ان کی شہادت نے ثابت کیا کہ ایمان کی طاقت ہر دنیاوی فرعون پر غالب ہے۔",biographyEnglish:"The very first martyr in the history of Islam. An elderly woman who withstood horrific tortures under the scorching desert sun from Abu Jahl, refusing to recant Tawhid. Struck down by Abu Jahl's spear, her martyrdom became an eternal monument of unyielding faith.",heroicAttributes:["عقیدۂ توحید پر چٹان جیسا ثبات","موت کے خوف پر ایمان کی برتری","ظالم کے سامنے بے خوفی"],heroicAttributesEnglish:["First Martyr of Islam","Unshakable Creed","Triumph over Torture","Pinnacle of Steadfastness"],dailySunnahLessons:[{ur:"عقیدے اور سچائی پر کبھی سمجھوتہ نہ کرنا، چاہے حالات کتنے ہی ناسازگار ہوں۔",en:"Never compromising core Islamic faith and values, regardless of worldly pressure."},{ur:"مصیبت اور ظلم کے وقت اللہ کی نصرت اور جنت کے وعدے پر یقین رکھنا۔",en:"Maintaining absolute trust in Allah's ultimate justice during times of persecution."}],sanadVerificationHash:"SANAD-SUMAYYAH-FIRST-MARTYR-007",lineageAndBackgroundUrdu:"سمیہ بنت خیاط۔ آپ قبیلہ بنو مخزوم کے حلیف ابو حذیفہ بن المغیرہ کی باندی تھیں، جنہوں نے یاسر بن عامر سے نکاح کیا۔ آپ کا پورا گھرانہ (آلِ یاسر) اسلام قبول کرنے والے ابتدائی سات نفوس میں شامل تھا۔",lineageAndBackgroundEnglish:"Sumayyah bint Khayyat, an emancipated elder of the Banu Makhzum clan who wed Yasir ibn Amir. Her entire household stood among the first seven individuals to proclaim Islam publicly.",propheticPraiseHadithArabic:"\xabصَبْرًا يَا آلَ يَاسِرٍ، فَإِنَّ مَوْعِدَكُمُ الجَنَّةُ\xbb [المستدرك على الصحيحين للحاكم: ۵۶۶۶ / مسند أحمد]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ کا جب مکہ کے صحرا سے گزر ہوتا اور آلِ یاسر کو تپتی ریت پر جلتے دیکھتے تو فرماتے: "صبر کرو اے آلِ یاسر! بے شک تمہارے لیے جنت کا قطعی وعدہ ہے"۔',propheticPraiseHadithEnglish:'Whenever the Prophet ﷺ passed by the family of Yasir being tortured under the scorching sun, he proclaimed: "Patience, O family of Yasir! For your appointed meeting place is Paradise!" (Mustadrak al-Hakim)',propheticPraiseSource:"المستدرک علی الصحیحین، حدیث ۵۶۶۶ (صحیح علی شرط مسلم)",exhaustiveBiographyUrdu:["سیدتنا سمیہ رضی اللہ عنہا تاریخِ انسانیت کی وہ عظیم خاتون ہیں جنہوں نے اپنے خون سے اسلام کی پہلی شہادت کی بنیاد رکھی۔ جب مکہ میں قریش نے غریب اور بے سہارا مسلمانوں پر ظلم کے پہاڑ توڑے، تو سیدتنا سمیہ، ان کے شوہر حضرت یاسر اور بیٹے حضرت عمار کو لوہے کی زرہیں پہنا کر دوپہر کی چلچلاتی دھوپ میں تپتے ہوئے انگاروں اور ریت پر لٹایا جاتا۔",'ابو جہل ملعون ان کے سر پر کھڑا ہو کر کلمۂ کفر اور بتوں کی تعریف کا مطالبہ کرتا، لیکن اس نحیف اور بوڑھی صحابیہ کی زبان سے تپتے ہوئے صحرا میں صرف ایک ہی صدا گونجتی تھی: "اَحَدٌ، اَحَدٌ، لَا اِلٰہَ اِلَّا اللّٰہُ مُحَمَّدٌ رَّسُوْلُ اللّٰہِ"۔',"جب ابو جہل ہر حربے میں ناکام ہو گیا اور اس ضعیفہ کے عزم کو نہ توڑ سکا، تو غیظ و غضب میں اندھا ہو کر اس نے نیزہ اٹھایا اور سیدتنا سمیہ کے جسم میں پیوست کر کے انہیں شہید کر دیا۔ وہ اسلام کی پہلی شہید بنیں جن کے خون نے مکہ میں کفر کے بتوں کو ہمیشہ کے لیے لرزا دیا۔",'جب غزوۂ بدر میں ابو جہل قتل ہوا، تو رسول اللہ ﷺ نے حضرت عمار سے فرمایا: "اللہ نے تمہاری والدہ کے قاتل کو انجام تک پہنچا دیا"'],exhaustiveBiographyEnglish:["Sayyidatuna Sumayyah (رضي الله عنها) was the first person to sacrifice her life for the message of Tawhid. When pagan elites subjected powerless believers to horrific persecution, Sumayyah, her husband Yasir, and her son Ammar were clad in heavy iron armor and pinned to burning desert sands at midday.",'Abu Jahl demanded that she renounce the Prophet ﷺ and praise pagan idols, but from her parched lips issued only: "Ahad, Ahad! None has the right to be worshipped except Allah, and Muhammad is His Messenger."',"Furious that he could not break the spiritual resolve of an elderly woman, Abu Jahl thrust his spear into her heart, martyring her. She entered eternity as the very first Shahid of Islam.",'Years later, when Abu Jahl lay slain at the Battle of Badr, the Prophet ﷺ turned to Ammar declaring: "Allah has executed justice upon the murderer of your mother."'],majorHistoricalMilestones:[{eventTitleUrdu:"اسلام قبول کرنے والے ابتدائی سات نفوس میں شمولیت",eventTitleEnglish:"Among the First Seven Proclaimers of Islam",descriptionUrdu:"مکہ میں علانیہ کلمۂ توحید کا اعلان کرنے والی اولین خاتون۔",descriptionEnglish:"One of the first seven individuals to proclaim faith openly in Makkah."},{eventTitleUrdu:"مکہ کے تپتے صحرا میں لوہے کی زرہوں میں تشدد پر صبر",eventTitleEnglish:"Enduring Iron Armor Tortures in the Desert",descriptionUrdu:"دہکتی ریت پر احد احد کا ورد کر کے عزمِ ایمانی ثابت کیا۔",descriptionEnglish:"Tortured under scorching heat while maintaining unbending proclamation of Tawhid."},{eventTitleUrdu:"اسلام کی سب سے پہلی شہادت کا لازوال شرف",eventTitleEnglish:"Attaining the Supreme Crown of First Martyrdom",descriptionUrdu:"ابو جہل کے نیزے کے وار سے جامِ شہادت نوش فرمایا۔",descriptionEnglish:"Martyred by Abu Jahl's spear, becoming the eternal first martyr of Islam."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"حافظ ابن حجر العسقلانی (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Hajar al-Asqalani",bookTitle:"الإصابة في تمييز الصحابة (جلد ۸)",verbatimQuoteUrdu:"سمیہ بنت خیاط اسلام کی پہلی شہید ہیں، جنہوں نے عذاب کی شدت کے باوجود کفر کا ایک لفظ نہ کہا۔",verbatimQuoteEnglish:"Sumayyah is the first martyr of Islam; despite the extremity of torment, she never uttered a word of compromise."}]},{id:"sah-08",nameUrdu:"سیدتنا ام سلیم بنت ملحان (الرمیصاء)",nameArabic:"الرميصاء أم سليم بنت ملحان الأنصارية (رضي الله عنها)",nameEnglish:"Sayyidatuna Umm Sulaym / Al-Rumaysa (رضي الله عنها)",titleUrdu:"الرمیصاء، عاقلۃ النساء، امِ انس",titleEnglish:"Al-Rumaysa, The Wise Matron, Mother of Anas",kinshipToProphet:"خادمِ رسول حضرت انس بن مالک کی والدہ ماجدہ، حضور ﷺ کی رضاعی خالہ",kinshipToProphetEnglish:"Mother of Sayyiduna Anas ibn Malik, Foster Aunt of the Prophet ﷺ, Sage Matron of Madinah",classicalCitation:"صحیح البخاری، حدیث ۵۰۴۹ / صحیح مسلم، حدیث ۲۴۵۶، ۲۴۵۷",era:"متوفی ۳۰ ہجری مدینہ منورہ",biographyUrdu:'وہ عظیم خاتون جن کے نکاح کا مہر سونا چاندی نہیں بلکہ "اسلام" تھا۔ ابو طلحہ کے پیغامِ نکاح پر فرمایا: اگر تم بت پرستی چھوڑ کر مسلمان ہو جاؤ تو یہی میرا مہر ہوگا۔ انہوں نے اپنے دس سالہ بیٹے حضرت انس کو حضور ﷺ کی خدمت کے لیے وقف کیا۔ رسول اللہ ﷺ نے خواب میں جنت میں ان کے قدموں کی آہٹ سنی۔',biographyEnglish:"The extraordinary woman whose bridal dowry was Islam itself. Refusing gold and silver, she accepted Abu Talha's marriage proposal only on condition of his conversion to Islam. She dedicated her son Anas ibn Malik to a decade of service to the Prophet ﷺ, who heard her footsteps in Paradise.",heroicAttributes:["دولت پر ایمان کو ترجیح دینا","اولاد کی مثالی اسلامی تربیت","جنت میں قدموں کی چاپ کی بشارت"],heroicAttributesEnglish:["Exemplary Dowry of Faith","Steadfast Motherhood","Service to the Messenger ﷺ","Heroism at Uhud"],dailySunnahLessons:[{ur:"رشتوں کے انتخاب میں دنیاوی مال و دولت کے بجائے دینداری اور اخلاق کو اولیت دینا۔",en:"Prioritizing sound religious practice and good character over worldly wealth in marriage."},{ur:"بچوں کو علمائے حق، مساجد اور دیندار صحبت سے وابستہ رکھنا۔",en:"Keeping children connected to righteous company, scholars, and spiritual environments."}],sanadVerificationHash:"SANAD-UMM-SULAYM-BUKHARI-008",lineageAndBackgroundUrdu:"ام سلیم بنت ملحان بن خالد بن زید بن حرام الانصاریہ النجاریہ۔ آپ مدینہ منورہ کے قبیلہ بنو نجار کی معزز خاتون تھیں۔ آپ کی ہمشیرہ ام حرام بنت ملحان بھی جلیل القدر صحابیہ اور سمندری غزوے کی شہید تھیں۔",lineageAndBackgroundEnglish:"Umm Sulaym bint Milhan of the Banu Najjar clan of Madinah. Her sister Umm Haram was also an illustrious companion who achieved martyrdom in the first naval expedition of Islam.",propheticPraiseHadithArabic:"\xabدَخَلْتُ الجَنَّةَ فَسَمِعْتُ خَشْفَةً، فَقُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذِهِ الرُّمَيْصَاءُ بِنْتُ مِلْحَانَ أُمُّ أَنَسِ بْنِ مَالِكٍ\xbb [صحيح مسلم: ۲۴۵۶]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "میں جنت میں داخل ہوا تو میں نے آگے کسی کے قدموں کی آہٹ سنی۔ میں نے پوچھا: یہ کون ہے؟ تو فرشتوں نے عرض کیا: یہ ام سلیم الرمیصاء بنت ملحان ہیں، جو انس بن مالک کی والدہ ہیں"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ stated: "I entered Paradise and heard footsteps ahead of me. I asked: Who is this? They said: This is al-Rumaysa bint Milhan, mother of Anas ibn Malik." (Sahih Muslim)',propheticPraiseSource:"صحیح مسلم، کتاب فضائل الصحابة، حدیث رقم ۲۴۵۶ / صحیح البخاری، حدیث ۳۶۷۹",exhaustiveBiographyUrdu:['سیدتنا ام سلیم رضی اللہ عنہا انصار کی سب سے دانشمند اور عظیم المرتبت خواتین میں شمار ہوتی تھیں۔ جب ان کے پہلے شوہر مالک بن نضر نے اسلام کی مخالفت کی اور شام جا کر ہلاک ہوا، تو مدینہ کے سب سے امیر اور معزز سردار ابو طلحہ انصاری نے بے پناہ سونے چاندی اور باغات کے عوض نکاح کا پیغام بھیجا۔ ام سلیم نے وہ تاریخ ساز جواب دیا جو قیامت تک کے لیے مینارۂ نور ہے: "اے ابو طلحہ! تم لکڑی کے اس بت کو پوجتے ہو جسے زمین سے اگنے والے درخت سے نجار نے تراشا ہے، جو نہ نفع دے سکتا ہے نہ نقصان۔ اگر تم اسلام قبول کر لو تو میں تم سے نکاح کر لوں گی اور مجھے مہر میں ایک درہم بھی نہیں چاہیے، تمہارا اسلام ہی میرا مہر ہوگا!" چنانچہ ابو طلحہ نے کلمہ پڑھا اور تاریخِ اسلام کا سب سے باعزت نکاح عمل میں آیا۔','جب رسول اللہ ﷺ مدینہ منورہ تشریف لائے اور انصار نے حضور ﷺ کی بارگاہ میں تحائف پیش کیے، تو ام سلیم اپنے دس سالہ بیٹے حضرت انس کا ہاتھ پکڑ کر حاضر ہوئیں اور عرض کیا: "یا رسول اللہ! میرے پاس مال و دولت تو نہیں ہے، یہ میرا جگر گوشہ انس ہے، اسے اپنی خدمت کے لیے قبول فرما لیجیے"۔ حضرت انس نے دس سال حضور ﷺ کی خدمت کا شرف پایا۔','غزوۂ حنین کے موقع پر جب کفار نے تیروں کی بارش کی، تو ام سلیم نے اپنی کمر سے خنجر باندھ رکھا تھا۔ حضور ﷺ نے پوچھا: "اے ام سلیم! یہ خنجر کس لیے ہے؟" تو عرض کیا: "یا رسول اللہ! اگر کوئی مشرک آپ کے قریب آئے گا تو میں اس کا پیٹ چاک کر دوں گی"۔',"ان کے ایک ننھے بچے کا انتقال ہوا تو انہوں نے شوہر کے آنے پر پہلے ان کی خدمت کی، کھانا کھلایا اور پھر کمالِ حکمت سے صبر کی تلقین فرمائی، جس پر حضور ﷺ نے ان کی اس رات میں برکت کی دعا فرمائی اور اللہ نے انہیں نو (۹) ایسے بیٹے عطا فرمائے جو سب کے سب قرآن کے حافظ بنے۔"],exhaustiveBiographyEnglish:['Sayyidatuna Umm Sulaym (رضي الله عنها) was a matron of incomparable wisdom. Following the death of her first husband, the wealthy nobleman Abu Talha proposed with lavish fortunes of gold. She replied: "O Abu Talha, you worship a block of wood carved by a carpenter that can neither benefit nor harm you. If you accept Islam, that will be my dowry, and I ask for nothing else!" Deeply moved, Abu Talha embraced Islam, making hers the noblest dowry in history.',"When the Prophet ﷺ migrated to Madinah, Umm Sulaym brought her 10-year-old son Anas ibn Malik, offering him as a dedicated servant to the Prophet ﷺ. Anas served the Prophet ﷺ for a decade, becoming one of the premier transmitters of Sunnah.",'At the Battle of Hunayn, she carried a dagger secured to her waist. When the Prophet ﷺ inquired about it, she declared fearlessly: "O Messenger of Allah, if any pagan approaches you, I will rip him open with it!"',"When her young infant passed away, she concealed her immense grief until her husband returned, fed him, attended to his comfort, and then gently led him to submit to Allah's decree. The Prophet ﷺ prayed for their blessed union, and Allah granted them nine sons who all became master memorizers of the Quran."],majorHistoricalMilestones:[{eventTitleUrdu:"اسلام کو مہر بنا کر ابو طلحہ سے تاریخی نکاح",eventTitleEnglish:"Accepting Islam as Her Noble Dowry",descriptionUrdu:"سونے چاندی کو ٹھکرا کر ابو طلحہ کے قبولِ اسلام کو اپنا مہر مقرر کیا۔",descriptionEnglish:"Refused gold and designated Abu Talha's conversion to Islam as her bridal dowry."},{eventTitleUrdu:"حضرت انس بن مالک کو خدمتِ نبوی میں پیش کرنا",eventTitleEnglish:"Dedicating Anas ibn Malik to Prophetic Service",descriptionUrdu:"اپنے لختِ جگر کو دس سال کے لیے حضور ﷺ کی خدمت میں وقف کیا۔",descriptionEnglish:"Dedicated her 10-year-old son Anas to serve the Messenger of Allah ﷺ."},{eventTitleUrdu:"غزوۂ حنین میں خنجر باندھ کر حضور ﷺ کی نصرت",eventTitleEnglish:"Guarding the Prophet with Dagger at Hunayn",descriptionUrdu:"میدانِ جنگ میں حضور ﷺ کے دفاع کے لیے کمر سے خنجر باندھے رکھا۔",descriptionEnglish:"Carried a dagger into combat ready to strike down any enemy approaching the Prophet."},{eventTitleUrdu:"جنت میں قدموں کی چاپ کی نبوی بشارت",eventTitleEnglish:"Hearing Her Footsteps in Paradise",descriptionUrdu:"حضور ﷺ نے خواب میں جنت کے اندر ام سلیم کے قدموں کی آہٹ سنی۔",descriptionEnglish:"Blessed with the Prophet's testimony of hearing her footsteps in Paradise."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن حجر عسقلانی (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Hajar al-Asqalani",bookTitle:"الإصابة في تمييز الصحابة",verbatimQuoteUrdu:"ام سلیم جیسی دانشمند اور صابرہ خاتون کی نظیر تاریخ میں ملنا نایاب ہے۔",verbatimQuoteEnglish:"A matron combining such profound juristic wisdom, forbearance, and sacrifice is exceptionally rare in human history."}]},{id:"sah-09",nameUrdu:"ام المؤمنین سیدتنا حفصہ بنت عمر",nameArabic:"حفصة بنت عمر بن الخطاب العدوية (رضي الله عنها)",nameEnglish:"Sayyidatuna Hafsah bint Umar (رضي الله عنها)",titleUrdu:"صوامۃ قوامۃ (کثرت سے روزے رکھنے اور شب بیداری کرنے والی)، حارثۃ المصحف",titleEnglish:"The Nocturnal Devotee, Custodian of the Master Quranic Codex",kinshipToProphet:"رسول اللہ ﷺ کی زوجۂ مطہرہ، امیر المؤمنین عمر بن الخطاب کی لختِ جگر",kinshipToProphetEnglish:"Noble Spouse of the Prophet ﷺ, Daughter of Umar ibn al-Khattab, Custodian of the Master Quranic Codex",classicalCitation:"صحیح البخاری، حدیث ۴۹۸۷ (جمع القرآن) / سنن ابی داؤد، حدیث ۲۲۸۳",era:"متوفی ۴۵ ہجری مدینہ منورہ (تدفین جنت البقیع)",biographyUrdu:"حضرت عمر فاروق کی صاحبزادی اور کثرت سے روزے رکھنے اور راتوں کو عبادت کرنے والی جلیل القدر ام المؤمنین۔ ان کا سب سے عظیم تاریخی کارنامہ یہ ہے کہ حضرت ابوبکر صدیق اور حضرت عمر کے دور میں جمع کیا گیا قرآن مجید کا اولین اصل تحریری نسخہ (المصحف الامام) انہی کی تحویل اور حفاظت میں رکھا گیا، جس سے بعد میں خلافتِ عثمانی میں تمام نسخے نقل ہوئے۔",biographyEnglish:'Daughter of Umar ibn al-Khattab and an extraordinary ascetic described by Angel Jibril as "frequently fasting and standing in prayer". Her monumental historical legacy was serving as the sole trusted custodian of the primary official written codex (Mushaf) of the Holy Quran, from which all copies were transcribed.',heroicAttributes:["قرآن مجید کے اولین نسخے کی امانت دار","کثرتِ صوم اور تہجد گزاری","کتابت اور تعلیم کی ماہر"],heroicAttributesEnglish:["Custodian of the Holy Codex","Vigilance in Worship","Truthfulness","Deep Devotion to Prayer"],dailySunnahLessons:[{ur:"تلاوتِ قرآن اور کلامِ الٰہی کی حفاظت و تعظیم کو اپنی ترجیح بنانا۔",en:"Making Quranic recitation, preservation, and reverence the center of life."},{ur:"کثرت سے نفلی روزے رکھنا اور راتوں کو قیام اللیل (تہجد) کی عادت ڈالنا۔",en:"Cultivating voluntary fasting and regular nocturnal prayer (Tahajjud)."}],sanadVerificationHash:"SANAD-HAFSAH-BUKHARI-SAHIH-009",lineageAndBackgroundUrdu:"حفصہ بنت عمر بن الخطاب بن نفیل العدویہ القرشیہ۔ آپ کی والدہ ماجدہ زینب بنت مظعون تھیں جو کبار صحابی عثمان بن مظعون کی ہمشیرہ تھیں۔ آپ نے مکہ میں اسلام قبول کیا اور اپنے پہلے شوہر خنیس بن حذافہ کے ساتھ مدینہ کی طرف ہجرت فرمائی۔ غزوۂ بدر میں شوہر کی شہادت کے بعد حضور ﷺ کے حبالۂ عقد میں آئیں۔",lineageAndBackgroundEnglish:"Hafsah bint Umar ibn al-Khattab al-Adawiyyah. Her mother was Zaynab bint Madh'un. Migrated to Madinah with her first husband Khunays, who was martyred after the Battle of Badr, after which she wed the Prophet ﷺ.",propheticPraiseHadithArabic:"\xabأَتَانِي جِبْرِيلُ فَقَالَ: رَاجِعْ حَفْصَةَ؛ فَإِنَّهَا صَوَّامَةٌ قَوَّامَةٌ، وَإِنَّهَا زَوْجَتُكَ فِي الجَنَّةِ\xbb [سنن أبي داود: ۲۲۸۳ / المستدرك]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے ارشاد فرمایا: "میرے پاس حضرت جبرائیل علیہ السلام تشریف لائے اور فرمایا: حفصہ سے رجوع فرما لیجیے، بے شک وہ کثرت سے روزے رکھنے والی اور راتوں کو طویل قیام کرنے والی ہیں، اور وہ جنت میں بھی آپ کی زوجہ ہیں"۔',propheticPraiseHadithEnglish:'The Messenger of Allah ﷺ stated: "Jibril came to me and said: Take Hafsah back, for verily she is constantly fasting and standing in nocturnal prayer, and she is your wife in Paradise!" (Sunan Abi Dawud)',propheticPraiseSource:"سنن ابی داؤد، حدیث رقم ۲۲۸۳ / المستدرک للحاکم، حدیث ۶۷۵۳ (صحیح علی شرط مسلم)",exhaustiveBiographyUrdu:["سیدتنا حفصہ رضی اللہ عنہا کا اسلام کی تاریخ میں وہ منفرد مقام ہے جو کسی اور کو حاصل نہیں ہوا۔ جب خلیفۂ اول حضرت ابوبکر صدیق رضی اللہ عنہ نے جنگِ یمامہ میں کبار حفاظ کی شہادت کے بعد قرآن مجید کو ایک جلد میں مدون فرمایا، تو وہ اصل نسخہ حضرت ابوبکر کے پاس رہا، پھر حضرت عمر فاروق کے پاس منتقل ہوا۔ حضرت عمر نے اپنے وصال کے وقت پوری امت میں سب سے زیادہ امانت دار اور لائق ہستی اپنی بیٹی سیدتنا حفصہ کو سمجھا اور وہ مقدس نسخہ ان کے سپرد فرمایا۔",'جب حضرت عثمان غنی رضی اللہ عنہ کے دور میں قراءتوں کے اختلاف کے سدِ باب کے لیے سرکاری نسخے تیار کرنے کا فیصلہ ہوا، تو حضرت عثمان نے سیدتنا حفصہ کی خدمت میں پیغام بھیجا: "ہمیں وہ مصحف عنایت فرمائیے تاکہ ہم اس سے مزید نسخے نقل کر کے واپس کر دیں"۔ سیدتنا حفصہ نے وہ امانت پیش فرمائی جس سے آج دنیا بھر میں موجود قرآن کے تمام نسخے نقل ہوئے۔ اسی لیے ائمہ انہیں "حارثۃ القرآن" (قرآن کی محافظہ) کہتے ہیں۔',"آپ نے رسول اللہ ﷺ سے ۶۰ احادیث مبارکہ روایت فرمائیں۔ ۴۵ ہجری میں مدینہ منورہ میں وصال فرمایا اور جنت البقیع میں مدفون ہوئیں۔"],exhaustiveBiographyEnglish:["Sayyidatuna Hafsah (رضي الله عنها) occupies an unparalleled position in the preservation of the divine scripture. When Caliph Abu Bakr compiled the first master codex of the Quran following the martyrdom of numerous memorizers at Yamamah, the master manuscript was entrusted to Umar, who upon his deathbed entrusted it to his daughter Hafsah as the sole guardian of the Word of Allah.",'During the Caliphate of Uthman ibn Affan, when dialectical variations required unifying the Ummah upon a single standardized text, Caliph Uthman sent an envoy to Hafsah requesting: "Send us the Mushaf so that we may transcribe master codices and return it to you." Hafsah provided the manuscript, from which all universal Qurans in existence today trace their direct orthography.','Angel Jibril personally lauded her devotion to the Prophet ﷺ, describing her as "Sawwamah, Qawwamah" (a woman of unceasing fasts and nocturnal Tahajjud). She passed away in 45 AH and was interred in Jannat al-Baqi.'],majorHistoricalMilestones:[{eventTitleUrdu:"غزوۂ بدر کے بعد رسول اللہ ﷺ سے نکاحِ مبارک",eventTitleEnglish:"Marriage to the Prophet ﷺ following Badr",descriptionUrdu:"شوہر کی شہادت کے بعد حضور ﷺ کے ازواجِ مطہرات میں شامل ہوئیں۔",descriptionEnglish:"Wed the Prophet ﷺ in Madinah, cementing alliances and sacred honor."},{eventTitleUrdu:"حضرت جبرائیل کی جانب سے صوامۃ قوامۃ کی گواہی",eventTitleEnglish:"Angel Jibril's Divine Testimony of Her Piety",descriptionUrdu:"جبرائیل علیہ السلام نے آ کر ان کے روزوں، تہجد اور جنت کی زوجیت کی گواہی دی۔",descriptionEnglish:"Jibril testified to her profound nocturnal prayer and eternal station in Jannah."},{eventTitleUrdu:"قرآن مجید کے اولین اصل نسخے (مصحفِ حفصہ) کی حفاظت",eventTitleEnglish:"Custodian of the Master Quranic Codex",descriptionUrdu:"خلافتِ صدیقی و فاروقی کا جمع شدہ اصل قرآنی نسخہ ان کی تحویل میں رہا۔",descriptionEnglish:"Served as the sole trusted guardian of the primary written Quranic manuscript."},{eventTitleUrdu:"عہدِ عثمانی میں مصحف کی فراہمی اور عالمی نقل",eventTitleEnglish:"Supplying the Codex for Standardized Compilation",descriptionUrdu:"حضرت عثمان کو نسخہ دیا جس سے نقل ہو کر پوری دنیا میں قرآن پھیلا۔",descriptionEnglish:"Provided the codex to Caliph Uthman for the universal transcription of the Quran."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن کثیر (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Kathir",bookTitle:"البداية والنهاية",verbatimQuoteUrdu:"ام المؤمنین حفصہ رضی اللہ عنہا نے امت پر قرآن کی حفاظت کی جو عظیم ذمہ داری نبھائی، وہ تاریخ کا روشن ترین باب ہے۔",verbatimQuoteEnglish:"Hafsah's guardianship of the primary Quranic codex remains one of the greatest services rendered to Islam."}]},{id:"sah-10",nameUrdu:"سیدتنا الشفاء بنت عبد اللہ العدویہ",nameArabic:"الشفاء بنت عبد الله القرشية العدوية (رضي الله عنها)",nameEnglish:"Sayyidatuna Ash-Shifa bint Abdullah (رضي الله عنها)",titleUrdu:"معلمۃ القراءۃ والکتابۃ، نگرانِ بازارِ مدینہ",titleEnglish:"The Teacher of Literacy, Market Administrator of Madinah",kinshipToProphet:"حضور ﷺ کی قریبی معتمد صحابیہ، ام المؤمنین حفصہ کی استاد",kinshipToProphetEnglish:"Distinguished Scholar, Physician, Teacher of Reading & Writing in Madinah, Trusted by Umar Farooq",classicalCitation:"سنن ابی داؤد، حدیث ۳۸۸۷ / الاصابة لابن حجر، ج ۸، ص ۲۰۱",era:"متوفی ۲۰ ہجری دورِ خلافتِ فاروقی مدینہ منورہ",biographyUrdu:"مکہ مکرمہ کی ان گنی چنی ہستیوں میں سے تھیں جو لکھنا پڑھنا اور طب جانتی تھیں۔ رسول اللہ ﷺ نے ان کی علمی صلاحیتوں کو سراہا اور ام المؤمنین سیدتنا حفصہ کو کتابت سکھانے کا حکم دیا۔ خلیفۂ دوم حضرت عمر فاروق رضی اللہ عنہ نے ان کی دیانت، ذہانت اور فہم کی بنا پر انہیں مدینہ منورہ کی مارکیٹ (بازار) کی نگرانی اور معاشی احتساب کی ذمہ داری سونپی۔",biographyEnglish:"One of the exceptionally rare literate scholars of pre-Islamic Makkah. The Prophet ﷺ commissioned her to instruct Mother of the Believers Hafsah in writing. Caliph Umar ibn al-Khattab respected her integrity and commercial ethics so profoundly that he consulted her on marketplace administration in Madinah.",heroicAttributes:["اعلیٰ علمی و ادبی قابلیت","انتظامی فراست اور مارکیٹ کا نظم و نسق","پردے کے ساتھ امت کی رہنمائی"],heroicAttributesEnglish:["First Female Teacher in Madinah","Healing and Medicine","Administrative Trust","Scholarly Erudition"],dailySunnahLessons:[{ur:"دوسروں کو لکھنا پڑھنا، مفید ہنر اور دینی علم سکھانا صدقہ جاریہ ہے۔",en:"Teaching literacy, beneficial skills, and Quran to others is perpetual charity (Sadaqah Jariyah)."},{ur:"خواتین شرعی پردے اور وقار کے ساتھ معاشرے کے لیے مفید خدمات انجام دے سکتی ہیں۔",en:"Muslim women can contribute fruitfully to community welfare within the boundaries of Haya."}],sanadVerificationHash:"SANAD-SHIFA-ABI-DAWUD-010",lineageAndBackgroundUrdu:'الشفاء بنت عبد اللہ بن عبد شمس بن خلف القرشیہ العدویہ۔ آپ حضرت عمر فاروق کے قبیلے بنو عدی سے تھیں۔ آپ کا اصل نام لیلیٰ تھا مگر شفابخش دم اور ادویات کی مہارت کی وجہ سے "الشفاء" کے لقب سے مشہور ہوئیں۔',lineageAndBackgroundEnglish:'Ash-Shifa bint Abd Allah al-Adawiyyah. From the clan of Banu Adi. Originally named Layla, her skill in therapeutic remedies and literacy earned her the honorific title "Ash-Shifa" (The Healer).',propheticPraiseHadithArabic:"\xabأَلَا تُعَلِّمِينَ هَذِهِ رُقْيَةَ النَّمْلَةِ كَمَا عَلَّمْتِيهَا الكِتَابَةَ؟\xbb [سنن أبي داود: ۳۸۸۷]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے سیدتنا الشفاء سے ارشاد فرمایا: "کیا تم حفصہ کو جلد کی بیماری کا یہ مفید دم نہیں سکھاتیں جیسے تم نے اسے لکھنا پڑھنا سکھایا ہے؟"۔',propheticPraiseHadithEnglish:'The Messenger of Allah ﷺ said to Ash-Shifa: "Will you not teach Hafsah the therapeutic remedy for skin ailments just as you taught her how to write?" (Sunan Abi Dawud)',propheticPraiseSource:"سنن ابی داؤد، کتاب الطب، حدیث رقم ۳۸۸۷ (حدیث صحیح)",exhaustiveBiographyUrdu:["سیدتنا الشفاء بنت عبد اللہ رضی اللہ عنہا ان اولین خواتین میں شامل تھیں جنہوں نے اسلام کی آمد سے قبل ہی مکہ کے ناخواندہ معاشرے میں کتابت اور خوشخطی کا ہنر سیکھا۔ جب وہ مسلمان ہوئیں تو رسول اللہ ﷺ نے ان کے علم کو نہ صرف برقرار رکھا بلکہ اسے فروغ دینے کا حکم فرمایا اور انہیں ام المؤمنین حفصہ کا استاد مقرر فرمایا۔","حضور ﷺ ان کے گھر تشریف لے جاتے اور قیلولہ فرماتے۔ انہوں نے حضور ﷺ کے لیے ایک چادر اور بستر خاص کر رکھا تھا جسے بعد میں ان کی اولاد نے تبرک کے طور پر محفوظ رکھا۔","امیر المؤمنین حضرت عمر فاروق رضی اللہ عنہ ان کی رائے اور تجارتی باریکیوں کو بے حد وقعت دیتے تھے۔ روایات کے مطابق حضرت عمر بازارِ مدینہ میں معاشی نظم و نسق، ناپ تول کے ترازو کی درستی اور دھوکہ دہی کے خاتمے کے لیے سیدتنا الشفاء کی رائے پر عمل فرماتے تھے اور انہیں مارکیٹ کے انتظامی امور سونپتے تھے۔"],exhaustiveBiographyEnglish:["Sayyidatuna Ash-Shifa (رضي الله عنها) was a pioneer of female literacy in Arabia. Embracing Islam early in Makkah, she migrated to Madinah where the Prophet ﷺ formally commissioned her to teach writing, literacy, and medicinal remedies to Mother of the Believers Hafsah.","The Prophet ﷺ frequently visited her home, where she maintained a dedicated bed for his afternoon rest (Qaylulah), preserved by her descendants as sacred relics.","Caliph Umar ibn al-Khattab held her intellectual sharpness and ethical judgment in the highest esteem, regularly consulting her on marketplace regulations, fair trade practices, and commercial supervision in Madinah."],majorHistoricalMilestones:[{eventTitleUrdu:"مکہ مکرمہ میں قبل از اسلام کتابت و خواندگی کی مہارت",eventTitleEnglish:"Mastery of Literacy and Medicine in Pre-Islamic Arabia",descriptionUrdu:"ناخواندہ دور میں خوشخطی اور طب کی نادر صلاحیت حاصل کی۔",descriptionEnglish:"Acquired rare literacy and therapeutic skills during the era of Jahiliyyah."},{eventTitleUrdu:"ام المؤمنین حضرت حفصہ کی باضابطہ استاد مقرر ہونا",eventTitleEnglish:"Appointed Royal Instructor to Mother of Believers Hafsah",descriptionUrdu:"حضور ﷺ کے حکم سے حضرت حفصہ کو کتابت اور علاج کی تعلیم دی۔",descriptionEnglish:"Commissioned by the Prophet ﷺ to teach writing to Sayyidatuna Hafsah."},{eventTitleUrdu:"دورِ فاروقی میں مدینہ کے بازار کا معاشی احتساب",eventTitleEnglish:"Marketplace Administration under Caliph Umar",descriptionUrdu:"حضرت عمر نے تجارتی امور اور مارکیٹ کے نظم و نسق میں ان پر اعتماد فرمایا۔",descriptionEnglish:"Consulted by Caliph Umar on commercial ethics and marketplace oversight."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"حافظ ابن عبد البر (رحمہ اللہ)",scholarNameEnglish:"Imam Ibn Abd al-Barr",bookTitle:"الاستيعاب في معرفة الأصحاب",verbatimQuoteUrdu:"الشفاء بنت عبد اللہ کبار عقلاء اور صاحبِ فضیلت خواتین میں سے تھیں جن کی رائے پر حضرت عمر اعتماد فرماتے تھے۔",verbatimQuoteEnglish:"Ash-Shifa was among the most intellectually gifted women of her era, deeply trusted by Caliph Umar."}]},{id:"sah-11",nameUrdu:"سیدتنا مریم بنت عمران (علیہا السلام)",nameArabic:"مريم بنت عمران البتول العذراء (عليها السلام)",nameEnglish:"Sayyidatuna Maryam bint Imran (Peace be upon her)",titleUrdu:"بتول، عذراء، صدیقہ، مصطفاۃ علی نساء العالمین",titleEnglish:"The Chaste Virgin, As-Siddiqah, Chosen Above All Women",kinshipToProphet:"سیدنا عیسیٰ علیہ السلام کی والدہ ماجدہ، قرآن میں جن کے نام پر مکمل سورہ ہے",kinshipToProphetEnglish:"Mother of Prophet Isa (Jesus) peace be upon him, Divinely Purified Sovereign Lady with a Quranic Surah named after her",classicalCitation:"سورۃ آل عمران: ۴۲ / سورۃ مریم / صحیح البخاری، حدیث ۳۴۳۱",era:"دورِ بنی اسرائیل قبلِ میلادِ مسیح (بیت المقدس)",biographyUrdu:"کائنات کی تمام عورتوں پر برگزیدہ اور پاکباز ہستی جن کی والدہ نے انہیں ولادت سے قبل ہی بیت المقدس کی خدمت کے لیے وقف کر دیا تھا۔ حضرت زکریا علیہ السلام کی کفالت میں محرابِ عبادت میں رہیں۔ اللہ تعالیٰ نے بے موسم کے جنتی پھلوں سے ان کی ضیافت فرمائی اور بغیر باپ کے حضرت عیسیٰ علیہ السلام کے معجزانہ حمل کی بشارت دی، جس پر انہوں نے بے مثال صبر اور تقویٰ کی مثال قائم کی۔",biographyEnglish:"The pure, sanctified matriarch chosen by Allah Almighty above all the women of the universe. Dedicated to the Temple by her mother Hannah, nurtured under Prophet Zakariyya, provided with miraculous divine sustenance in her sanctuary (Mihrab), and chosen for the miraculous virgin birth of Prophet Isa (peace be upon him).",heroicAttributes:["اعلیٰ ترین حیا اور عفت","شب و روز کی کامل یکسوئی والی عبادت","الزام تراشی پر چٹان جیسا صبر"],heroicAttributesEnglish:["Chastity and Devotion","Trust in Divine Decree","Sanctuary Worship","Exalted Quranic Rank"],dailySunnahLessons:[{ur:"اپنی پاکدامنی اور عفت کی ہر قیمت پر حفاظت کرنا اور لغو مجالس سے دور رہنا۔",en:"Safeguarding personal chastity, modesty, and honor uncompromisingly in all environments."},{ur:"رزق کے معاملے میں صرف اللہ تعالیٰ کی ذات پر کامل توکل رکھنا۔",en:"Placing absolute reliance upon Allah for sustenance and unearned divine blessings."},{ur:"جب لوگ بلاوجہ بدگمانی کریں تو خاموشی اور اللہ کے عدل پر بھروسہ رکھنا۔",en:"Responding to unfair slander with quiet dignity and serene trust in divine vindication."}],sanadVerificationHash:"SANAD-MARYAM-QURAN-BUKHARI-011",lineageAndBackgroundUrdu:"مریم بنت عمران بن ماثان بن سلیمان بن داؤد علیہم السلام۔ آپ کا تعلق بنو اسرائیل کے معزز ترین انبیاء کے گھرانے اور آلِ عمران سے ہے۔ آپ کی والدہ کا نام حنہ تھا جنہوں نے نذر مانی تھی کہ جو بچہ پیدا ہوگا اسے بیت المقدس کے لیے آزاد وقف کروں گی۔",lineageAndBackgroundEnglish:"Maryam bint Imran ibn Mathan of the lineage of Prophet Dawud and the noble House of Imran. Her mother Hannah consecrated her before birth to perpetual service of the Holy Sanctuary (Bayt al-Maqdis).",propheticPraiseHadithArabic:"\xabخَيْرُ نِسَائِهَا مَرْيَمُ ابْنَتُ عِمْرَانَ، وَخَيْرُ نِسَائِهَا خَدِيجَةُ\xbb [صحيح البخاري: ۳۴۳۱] — وَقَالَ ﷺ: \xabكَمُلَ مِنَ الرِّجَالِ كَثِيرٌ، وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلَّا مَرْيَمُ ابْنَتُ عِمْرَانَ، وَآسِيَةُ امْرَأَةُ فِرْعَوْنَ\xbb [صحيح البخاري: ۳۷۶۹]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے فرمایا: "آسمان و زمین کی عورتوں میں سب سے افضل مریم بنت عمران ہیں، اور سب سے افضل خدیجہ ہیں"۔ اور فرمایا: "مردوں میں سے بہت سے کامل ہوئے، لیکن عورتوں میں سے سوائے مریم بنت عمران اور فرعون کی بیوی آسیہ کے کوئی کامل نہیں ہوا"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ declared: "The best of the women of the worlds is Maryam bint Imran, and the best of the women is Khadijah." (Bukhari #3431) And he said: "Many men reached perfection, but none reached perfection among women except Maryam bint Imran and Asiyah the wife of Pharaoh." (Bukhari #3769)',propheticPraiseSource:"صحیح البخاری، کتاب احادیث الانبیاء، حدیث رقم ۳۴۳۱ و ۳۷۶۹ / صحیح مسلم، حدیث ۲۴۳۱",exhaustiveBiographyUrdu:['سیدتنا مریم بنت عمران علیہا السلام وہ واحد خاتون ہیں جن کا نامِ نامی قرآنِ مجید میں ۳۴ بار صراحتاً مذکور ہے اور قرآن کی ۱۹ویں سورہ کا نام "سورۃ مریم" رکھا گیا۔ قرآن نے خود گواہی دی کہ اللہ تعالیٰ نے انہیں تمام جہانوں کی عورتوں پر برگزیدہ فرمایا: "وَإِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَىٰ نِسَاءِ الْعَالَمِينَ"۔','جب آپ پیدا ہوئیں تو حضرت زکریا علیہ السلام نے آپ کی کفالت کا شرف حاصل کیا۔ بیت المقدس کے ایک پاکیزہ حجرے (محراب) میں آپ ہمہ وقت مصروفِ عبادت رہتیں۔ جب بھی حضرت زکریا آپ کے پاس آتے تو وہاں تازہ بے موسم پھل پاتے؛ سردیوں میں گرمیوں کے پھل اور گرمیوں میں سردیوں کے پھل! جب دریافت فرماتے کہ مریم یہ کہاں سے آئے؟ تو عرض کرتیں: "هُوَ مِنْ عِندِ اللَّهِ ۖ إِنَّ اللَّهَ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ" (یہ اللہ کے پاس سے ہے، بیشک اللہ جسے چاہے بے حساب رزق دیتا ہے)۔','پھر حضرت جبرائیل علیہ السلام ایک خوبصورت انسان کی صورت میں تشریف لائے اور ایک پاکیزہ بیٹے (حضرت عیسیٰ علیہ السلام) کی خوشخبری دی جو بغیر باپ کے کلمۃ اللہ کے طور پر پیدا ہوں گے۔ جب حمل کے بعد ولادت کا وقت قریب آیا اور تنہائی میں درد کی شدت ہوئی، تو پکار اٹھیں: "يَا لَيْتَنِي مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا"۔ مگر اللہ تعالیٰ نے ان کے قدموں کے نیچے میٹھے پانی کا چشمہ جاری فرمایا اور کھجور کے تنے کو ہلانے پر تر و تازہ کھجوریں نچھاور کیں۔','جب وہ اپنے نوزائیدہ بچے کو گود میں اٹھا کر اپنی قوم کے پاس آئیں اور شریروں نے تہمت لگانا چاہی، تو آپ نے روزۂ سکوت کا اشارہ فرمایا۔ اس پر گہوارے میں ننھے حضرت عیسیٰ علیہ السلام نے کلام فرما کر اپنی والدہ کی برات کا اعلان کیا: "إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا"۔ اللہ نے قیامت تک کے لیے ان کی عفت کو قرآن کا لازوال حصہ بنا دیا۔'],exhaustiveBiographyEnglish:['Sayyidatuna Maryam bint Imran (peace be upon her) is the sole woman honored by explicit name in the Holy Quran (mentioned 34 times), with the entire 19th Surah titled after her. The Divine Word confirms her supreme election: "And when the angels said: O Maryam! Surely Allah has chosen you and purified you, and selected you above the women of all the worlds." (3:42)','Nurtured under Prophet Zakariyya in the holy sanctuary of Jerusalem, she devoted her youth to ceaseless adoration. Whenever Zakariyya entered her chamber, he found miraculous unseasonal provisions—summer fruits in winter and winter produce in summer. When asked of their origin, she serenely replied: "It is from Allah; indeed Allah provides for whom He wills without measure."',"Archangel Jibril manifested before her to announce the immaculate conception of Prophet Isa (peace be upon him) as a Word and Spirit from Allah. When labor contractions drove her to the trunk of a date palm in solitary anguish, Allah caused a fresh spring to gush at her feet and ripe dates to shower upon her.",'Upon returning to her people carrying the newborn infant, when skeptics sought to accuse her, she gestured toward the child observing a vow of silence. In that supreme miracle, infant Isa spoke from the cradle: "Indeed I am the servant of Allah; He has given me the Scripture and made me a Prophet." Her peerless purity was enshrined in the divine decree forever.'],majorHistoricalMilestones:[{eventTitleUrdu:"بیت المقدس کے لیے ولادت سے قبل نذر اور وقف",eventTitleEnglish:"Consecration to the Holy Temple by Mother Hannah",descriptionUrdu:"حضرت حنہ نے اپنی بیٹی کو عبادت اور خدمتِ بیت المقدس کے لیے وقف کیا۔",descriptionEnglish:"Dedicated exclusively to divine worship in the Holy Sanctuary before birth."},{eventTitleUrdu:"محرابِ عبادت میں بے موسم جنتی پھلوں کی کرامت",eventTitleEnglish:"Miraculous Heavenly Provisions in the Sanctuary",descriptionUrdu:"حضرت زکریا علیہ السلام نے سردیوں میں گرمیوں کے جنتی پھل دیکھے۔",descriptionEnglish:"Blessed with unseasonal divine fruits in her secluded prayer chamber."},{eventTitleUrdu:"روح القدس (حضرت جبرائیل) کے ذریعے کلمۃ اللہ کی بشارت",eventTitleEnglish:"Annunciation by Archangel Jibril",descriptionUrdu:"جبرائیل علیہ السلام نے بغیر باپ کے سیدنا عیسیٰ کی پیدائش کی خوشخبری دی۔",descriptionEnglish:"Bestowed the miraculous immaculate tidings of Prophet Isa (peace be upon him)."},{eventTitleUrdu:"گہوارے میں نومولود عیسیٰ علیہ السلام کی معجزانہ گواہی",eventTitleEnglish:"Infant Isa's Miraculous Speech from the Cradle",descriptionUrdu:"حضرت عیسیٰ نے گہوارے میں کلام فرما کر والدہ کی عفت و طہارت ثابت کی۔",descriptionEnglish:"Newborn Isa spoke from the cradle exonerating his mother of all false accusations."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام ابن کثیر (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Kathir",bookTitle:"البدایہ والنہایہ، ج ۲",verbatimQuoteUrdu:"مریم بنت عمران تمام جہانوں کی عورتوں میں سب سے افضل صدیقہ ہیں جن کے تقویٰ اور کرامات پر قرآن شاہد ہے۔",verbatimQuoteEnglish:"Maryam bint Imran is the supreme Siddiqah above all women of existence, her piety attested by the Quran."}]},{id:"sah-12",nameUrdu:"سیدتنا آسیہ بنت مزاحم (علیہا السلام)",nameArabic:"آسية بنت مزاحم امرأة فرعون (عليها السلام)",nameEnglish:"Sayyidatuna Asiyah bint Muzahim (Peace be upon her)",titleUrdu:"شہیدۂ توحید، زوجۂ فرعون، سیدۃ نساء اہل الجنہ",titleEnglish:"The Champion of Tawhid, Wife of Pharaoh, Matron of Paradise",kinshipToProphet:"سیدنا موسیٰ علیہ السلام کی مربی والدہ، جنت میں حضور ﷺ کی رفیقہ",kinshipToProphetEnglish:"Queen of Faith who rescued Prophet Musa (Moses) from the Nile, Martyr of Divine Monotheism",classicalCitation:"سورۃ التحریم: ۱۱ / صحیح البخاری، حدیث ۳۴۱۱ / المعجم الکبیر",era:"دورِ فرعونِ مصر (قبلِ ہجرت بنی اسرائیل)",biographyUrdu:"مصر کے سب سے متکبر اور خدائی کا دعویٰ کرنے والے بادشاہ فرعون کی ملکہ جنہوں نے محلات کی شاہانہ آسائشوں کو ٹھکرا کر اللہ کی وحدانیت کو قبول کیا۔ دریائے نیل سے حضرت موسیٰ علیہ السلام کے صندوق کو نکال کر اپنے سینے سے لگایا اور فرعون کے سامنے ان کی جان بچائی۔ جب فرعون کو ان کے ایمان کا پتہ چلا تو ان پر ہولناک تشدد کیا گیا مگر ان کے پائے ثبات میں لرزش نہ آئی۔",biographyEnglish:"The Queen of Egypt who defied the supreme tyrant of history. She plucked baby Musa from the Nile, compelled Pharaoh to adopt him, embraced pure Monotheism (Tawhid) in the heart of royal oppression, and chose excruciating martyrdom over idolatrous palaces, praying for an eternal home in Paradise near Allah.",heroicAttributes:["شاہی آسائشوں پر ایمان کو ترجیح دینا","فرعون کے جبر کے سامنے فولادی عزم","سیدنا موسیٰ کی مربیانہ حفاظت"],heroicAttributesEnglish:["Rejection of Tyranny","Spiritual Sovereignty","Palace of Paradise","Unyielding Faith"],dailySunnahLessons:[{ur:"دنیا کی دولت، عہدے اور آسائشیں ایمان کے مقابلے میں کوئی وقعت نہیں رکھتیں۔",en:"Worldly wealth, royal comfort, and power pale into insignificance when weighed against faith."},{ur:"ظالم ترین ماحول میں بھی اپنے دل میں ایمان کا چراغ روشن رکھا جا سکتا ہے۔",en:"One can maintain pristine faith and moral purity even within toxic and oppressive surroundings."},{ur:"مصیبت کے وقت دنیا کی عمارتوں کے بجائے جنت میں اللہ کے قرب کا محل مانگنا۔",en:"Praying for divine nearness in Paradise rather than ephemeral worldly monuments during distress."}],sanadVerificationHash:"SANAD-ASIYAH-QURAN-TAHRIM-012",lineageAndBackgroundUrdu:"آسیہ بنت مزاحم بن عبید بن الریان۔ آپ کا تعلق مصر کے شاہی خاندان سے تھا۔ فرعونِ مصر نے اپنے اقتدار اور حسن کی بنا پر ان سے شادی کی تھی۔ وہ محلات کی ملکہ تھیں مگر ان کا دل جاہلیت اور تکبر سے بالکل پاک تھا۔",lineageAndBackgroundEnglish:"Asiyah bint Muzahim of ancient Egyptian royal lineage. Married to the Pharaoh who claimed divinity, she lived amidst imperial opulence yet kept her soul unstained by tyranny and arrogance.",propheticPraiseHadithArabic:"\xabوَضَرَبَ اللَّهُ مَثَلًا لِّلَّذِينَ آمَنُوا امْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ وَنَجِّنِي مِن فِرْعَوْنَ وَعَمَلِهِ\xbb [التحريم: ۱۱] — وَقَالَ ﷺ: \xabأَفْضَلُ نِسَاءِ أَهْلِ الْجَنَّةِ خَدِيجَةُ، وَفَاطِمَةُ، وَمَرْيَمُ، وَآسِيَةُ\xbb [المستدرك على الصحيحين: ۳۸۳۶]",propheticPraiseHadithUrdu:'قرآن نے فرمایا: "اور اللہ نے ایمان والوں کے لیے فرعون کی بیوی (آسیہ) کی مثال بیان فرمائی جب انہوں نے عرض کی: اے میرے رب! میرے لیے اپنے پاس جنت میں ایک گھر بنا دے اور مجھے فرعون اور اس کے عمل سے نجات دے"۔ اور رسول اللہ ﷺ نے فرمایا: "اہلِ جنت کی عورتوں میں سب سے افضل خدیجہ، فاطمہ، مریم، اور آسیہ ہیں"۔',propheticPraiseHadithEnglish:'Allah presented her as the eternal archetype of faith in Surah At-Tahrim: "My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds." (66:11) And the Prophet ﷺ declared: "The most noble women of Paradise are Khadijah, Fatimah, Maryam, and Asiyah." (Mustadrak al-Hakim)',propheticPraiseSource:"سورۃ التحریم، آیت ۱۱ / المستدرک علی الصحیحین للحاکم، حدیث ۳۸۳۶ (صحیح علی شرط مسلم)",exhaustiveBiographyUrdu:['سیدتنا آسیہ بنت مزاحم علیہا السلام تاریخِ انسانی کی وہ عظیم خاتون ہیں جنہیں اللہ تبارک و تعالیٰ نے قیامت تک کے تمام مردوں اور عورتوں کے لیے ایمان کا کامل نمونہ بنا کر پیش فرمایا ہے۔ وہ ایسے وقت میں ایمان لائیں جب زمین پر فرعون کی مطلق العنانی تھی اور وہ کہتا تھا: "أَنَا رَبُّكُمُ الْأَعْلَى" (میں تمہارا سب سے بڑا رب ہوں)۔','جب اللہ نے نوزائیدہ موسیٰ علیہ السلام کے تابوت کو دریائے نیل کی لہروں پر بہایا اور وہ فرعون کے محل کے گھاٹ پر لگا، تو سیدتنا آسیہ نے اسے اٹھوایا۔ جب صندوق کھلا اور ننھے بچے کا نورانی چہرہ دیکھا تو ان کے دل میں مادری محبت کا سمندر امڈ آیا۔ فرعون بنی اسرائیل کے بچوں کو ذبح کرواتا تھا اور اس بچے کو بھی قتل کرنا چاہا، مگر آسیہ نے سینہ تان کر فرمایا: "قُرَّتُ عَيْنٍ لِّي وَلَكَ ۖ لَا تَقْتُلُوهُ عَسَىٰ أَن يَنفَعَنَا أَوْ نَتَّخِذَهُ وَلَدًا" (یہ میری اور تیری آنکھوں کی ٹھنڈک ہے، اسے قتل نہ کرو، ہو سکتا ہے یہ ہمیں نفع پہنچائے یا ہم اسے بیٹا بنا لیں)۔ اس طرح حضرت موسیٰ کی جان آسیہ کے ذریعے بچی۔','جب موسیٰ علیہ السلام نے نبوت کے بعد دربارِ فرعون میں جادوگروں کو شکست دی اور جادوگر سجدے میں گر گئے، تو سیدتنا آسیہ کا پوشیدہ ایمان کھل کر سامنے آ گیا۔ جب فرعون کو معلوم ہوا کہ اس کی اپنی ملکہ ربِ موسیٰ پر ایمان لا چکی ہے، تو وہ غضبناک ہو گیا اور اس نے دھمکی دی کہ اگر موسیٰ کے خدا کا انکار نہ کیا تو بدترین موت دی جائے گی۔ مگر ملکہ نے محلات، زیورات اور تاج کو ٹھکرا دیا اور فرمایا: "میرا رب صرف وہ ہے جو زمین و آسمان کا خالق ہے"۔','فرعون کے حکم پر تپتی دھوپ میں چاروں ہاتھ پاؤں میں میخیں گاڑ کر ان پر بھاری پتھر رکھ دیا گیا اور سخت اذیت دی گئی۔ اس وقت انہوں نے وہ تاریخ ساز دعا مانگی جو قرآن کا حصہ ہے: "رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ"۔ روایات کے مطابق اللہ تعالیٰ نے پردے ہٹا دیے اور انہوں نے شہادت سے پہلے ہی جنت میں اپنا سفید موتیوں کا محل دیکھ لیا اور مسکرا دیں۔ پھر فرعون کا پتھر گرنے سے پہلے ہی اللہ نے ان کی روح کو قبض فرما کر اپنے جوارِ رحمت میں لے لیا۔'],exhaustiveBiographyEnglish:['Sayyidatuna Asiyah bint Muzahim stands as the ultimate Quranic monument of unyielding faith. Living in the golden court of the tyrant who proclaimed "I am your supreme lord", she preserved an incorruptible soul anchored in pure Monotheism.','When the wooden ark carrying infant Musa drifted to the palace banks on the Nile, Asiyah retrieved it. Gazing upon the radiant child, maternal love overwhelmed her heart. As Pharaoh drew his blade to execute the Hebrew babe, Asiyah shielded him, declaring: "He will be a comfort of the eye for me and for you! Do not slay him; perhaps he will be of benefit to us or we may adopt him as a son." Through her courageous intercession, the Prophet of the Exodus was preserved.',"When Musa vanquished Pharaoh's magicians and the sorcerers fell in prostration to the Lord of Aaron and Moses, Asiyah publicly declared her allegiance to Tawhid. Enraged, Pharaoh stripped her of queenship, binding her limbs to stakes in the blazing desert sun beneath crushing boulders, demanding she recant. She spat upon his imperial decrees.",'In her final moments under excruciating torture, she uttered the immortal supplication immortalized in Surah At-Tahrim: "My Lord! Build for me near You a house in Paradise, and save me from Pharaoh and his deeds." Classical commentators record that the celestial veils parted; she beheld her palace of pearls in Paradise and smiled. Allah took her pure soul into His mercy before the executioner\'s final stone was dropped.'],majorHistoricalMilestones:[{eventTitleUrdu:"دریائے نیل سے سیدنا موسیٰ کی حفاظت اور پرورش",eventTitleEnglish:"Rescuing and Sheltering Infant Musa from the Nile",descriptionUrdu:"فرعون کے جلادوں کے سامنے ڈھال بن کر حضرت موسیٰ کو گود لیا۔",descriptionEnglish:"Confronted Pharaoh's executioners and nurtured Moses in the royal court."},{eventTitleUrdu:"دربارِ فرعون میں علی الاعلان توحید کا اقرار",eventTitleEnglish:"Public Declaration of Tawhid in Pharaoh's Court",descriptionUrdu:"جادوگروں کے ایمان لانے کے بعد اپنے ایمان کا اعلان فرمایا۔",descriptionEnglish:"Fearlessly proclaimed Monotheism, rejecting royal paganism and tyrant godhood."},{eventTitleUrdu:"میخوں پر ہولناک تشدد اور شہادت کے وقت جنت کا دیدار",eventTitleEnglish:"Martyrdom Under Desert Torture & Vision of Paradise",descriptionUrdu:"تپتی ریت پر میخوں میں جکڑے جانے پر جنت میں اپنے محل کا مشاہدہ کیا۔",descriptionEnglish:"Endured martyrdom under desert stakes, beholding her palace in Paradise before passing."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"علامہ فخر الدین رازی (رحمہ اللہ)",scholarNameEnglish:"Imam Fakhr al-Din al-Razi",bookTitle:"التفسیر الکبیر (مفاتیح الغیب)",verbatimQuoteUrdu:'آسیہ نے پہلے "عِندَكَ" (تیرے پاس) کہا پھر "بَيْتًا" (گھر) مانگا، جس سے ثابت ہوتا ہے کہ وہ مکان سے پہلے اللہ کے قرب کی طلبگار تھیں۔',verbatimQuoteEnglish:'Asiyah requested "Near You" before asking for "a House", proving she sought divine nearness above the physical dwelling.'}]},{id:"sah-13",nameUrdu:"سیدتنا زینب بنت رسول اللہ (رضی اللہ عنہا)",nameArabic:"زينب بنت محمد رسول الله القرشية الهاشمية",nameEnglish:"Sayyidatuna Zaynab bint Rasulillah (رضي الله عنها)",titleUrdu:"کبریٰ بناتِ رسول، صابرہ، مہاجرہ",titleEnglish:"The Eldest Daughter of the Prophet ﷺ, The Patient Migrant",kinshipToProphet:"رسول اللہ ﷺ اور سیدہ خدیجہ کی سب سے بڑی صاحبزادی",kinshipToProphetEnglish:"Eldest Daughter of the Prophet ﷺ and Sayyidah Khadijah, Heroic Emigrant of Truth",classicalCitation:"صحیح البخاری، حدیث ۳۱۳۸ / سنن ابی داؤد، حدیث ۲۶۹۲",era:"متوفی ۸ ہجری مدینہ منورہ (جنت البقیع)",biographyUrdu:'رسول اللہ ﷺ کی سب سے بڑی لختِ جگر جن کے اخلاق میں خدیجۃ الکبریٰ کا پرتو تھا۔ ابتدائے اسلام ہی میں مکہ میں والدہ کے ساتھ ایمان لائیں۔ ہجرت کے دوران قریش کے ظالم ہبار بن اسود نے نیزہ مارا جس سے اونٹ سے گریں اور شدید زخمی ہوئیں۔ حضور ﷺ نے ان کی قربانی پر فرمایا: "یہ میری سب سے بہترین بیٹی ہے جو میری محبت میں تکلیفوں سے گزاری گئی"۔',biographyEnglish:'The eldest noble daughter of the Prophet ﷺ and Sayyidatuna Khadijah. Embraced Islam at its inception. During her migration to Madinah, she was brutally attacked while pregnant by Habbar ibn al-Aswad, falling from her camel. The Prophet ﷺ praised her fortitude: "She was the best of my daughters who was afflicted for my sake."',heroicAttributes:["ہجرت میں جان لیوا زخموں پر صبر","والدِ محترم ﷺ پر والہانہ فداکاری","حیا اور وفائے شوہر کا اعلیٰ نمونہ"],heroicAttributesEnglish:["Patience during Hijrah","Marital Forbearance","Noble Lineage","Exemplary Devotion"],dailySunnahLessons:[{ur:"دینِ حق کی خاطر جسمانی و مالی تکالیف کو صبر اور رضا کے ساتھ برداشت کرنا۔",en:"Bearing physical and emotional hardships in the path of truth with serene fortitude."},{ur:"خاندان اور رشتوں کے اختلافات میں عدل اور پاکیزہ اخلاق کو نہ چھوڑنا۔",en:"Upholding justice, filial loyalty, and high moral standards amidst family conflicts."}],sanadVerificationHash:"SANAD-ZAYNAB-BUKHARI-SAHIH-013",lineageAndBackgroundUrdu:"زینب بنت رسول اللہ محمد بن عبد اللہ بن عبد المطلب القرشیہ الہاشمیہ۔ والدہ ماجدہ سیدتنا خدیجہ الکبریٰ ہیں۔ حضور ﷺ کی عمر مبارک کے تیسویں سال مکہ میں ولادت ہوئی۔ ان کا نکاح حضرت خدیجہ کی بہن ہالہ کے بیٹے حضرت ابو العاص بن الربیع سے ہوا تھا۔",lineageAndBackgroundEnglish:"The eldest daughter of the Prophet Muhammad ﷺ and Sayyidatuna Khadijah, born in Makkah when the Prophet ﷺ was 30 years old. Married prior to Islam to her maternal cousin Abu al-As ibn al-Rabi'.",propheticPraiseHadithArabic:"\xabهِيَ خَيْرُ بَنَاتِي، أُصِيبَتْ فِيَّ\xbb [سنن أبي داود: ۲۶۹۲ / المستدرك للحاكم: ۶۸۶۹]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے سیدتنا زینب کی فضیلت میں ارشاد فرمایا: "یہ میری بیٹیوں میں سب سے افضل ہے جو میری وجہ سے اتنی بڑی آزمائش میں ڈالی گئی"۔',propheticPraiseHadithEnglish:'The Messenger of Allah ﷺ said of her: "She was the finest of my daughters who suffered tribulations on my account." (Sunan Abi Dawud #2692 / Mustadrak al-Hakim)',propheticPraiseSource:"سنن ابی داؤد، کتاب الجہاد، حدیث رقم ۲۶۹۲ / الاصابة لابن حجر",exhaustiveBiographyUrdu:["سیدتنا زینب رضی اللہ عنہا آقائے دو جہاں ﷺ کی سب سے بڑی شہزادی تھیں۔ جب نبوت کا اعلان ہوا تو انہوں نے اپنی والدہ سیدہ خدیجہ کے فورا بعد اسلام قبول کیا۔ ان کے شوہر ابو العاص بن الربیع اس وقت تک مشرک تھے مگر اخلاق کے اچھے تھے۔ قریش نے ابو العاص پر دباؤ ڈالا کہ تم محمد (ﷺ) کی بیٹی کو طلاق دے دو ہم جس سردار کی بیٹی کہو تمہارے نکاح میں دے دیتے ہیں، مگر ابو العاص نے صاف انکار کر دیا کہ میں اپنی رفیقہ کو کبھی نہیں چھوڑوں گا۔",'غزوۂ بدر میں جب ابو العاص قیدی بن کر مدینہ آئے، تو مکہ سے فدیہ بھیجا گیا۔ سیدتنا زینب نے فدیے میں وہ متبرک ہار بھیجا جو ان کی والدہ حضرت خدیجہ نے رخصتی کے وقت انہیں پہنایا تھا۔ جب رسول اللہ ﷺ کی نظر اس ہار پر پڑی تو خدیجہ کی وفائیں یاد آ گئیں اور آنکھوں سے آنسو چھلک پڑے۔ آپ ﷺ نے صحابہ سے فرمایا: "اگر تم مناسب سمجھو تو زینب کا قیدی رہا کر دو اور اس کا ہار لوٹا دو"۔ صحابہ نے سر جھکا کر ہار اور قیدی دونوں واپس کر دیے۔',"رسول اللہ ﷺ نے ابو العاص سے وعدہ لیا کہ وہ زینب کو مدینہ بھیج دیں گے۔ جب زینب ہجرت کر کے مدینہ آ رہی تھیں، تو مکہ کے شریروں نے تعاقب کیا اور ہبار بن اسود نے نیزہ مار کر انہیں اونٹ کے کجاوے سے چٹان پر گرا دیا جس سے ان کا حمل ضائع ہو گیا اور شدید اندرونی چوٹیں آئیں۔ بالآخر وہ مدینہ منورہ پہنچیں اور حضور ﷺ نے فرطِ محبت سے ان کا استقبال فرمایا۔","بعد میں جب ابو العاص اسلام لے آئے تو حضور ﷺ نے سابقہ نکاح پر ہی دونوں کو اکٹھا فرما دیا۔ ہجرت کے دوران لگے ہوئے گہرے زخموں کی وجہ سے سیدتنا زینب ۸ ہجری میں مدینہ منورہ میں وصال پا گئیں۔ حضور ﷺ نے خود ان کے جنازے کی امامت فرمائی اور اپنی چادرِ مبارک ان کے کفن کے لیے عطا فرمائی۔"],exhaustiveBiographyEnglish:["Sayyidatuna Zaynab (رضي الله عنها) was the eldest daughter of the Prophet ﷺ. Embracing Islam immediately after her mother Khadijah, she demonstrated peerless loyalty during the bitter Makkan boycott.",'At the Battle of Badr, her husband Abu al-As was captured by Muslims. When ransoms arrived from Makkah, Zaynab sent the onyx necklace gifted to her by Khadijah on her wedding night. When the Prophet ﷺ recognized Khadijah\'s necklace, he wept openly and asked the companions: "If you deem it appropriate, release her captive and return her heirloom to her." The companions weeping consented immediately.',"Upon release, Abu al-As fulfilled his pledge to let Zaynab migrate to Madinah. As she departed Makkah, Habbar ibn al-Aswad ambushed her camel, striking her with a spear. She fell heavily upon a rock, suffering a miscarriage and severe internal hemorrhage. She reached Madinah where the Prophet ﷺ tended to her with immense tenderness.","When Abu al-As later embraced Islam, the Prophet ﷺ reunited them. Complications from her migration injuries persisted until she passed away in 8 AH in Madinah. The Prophet ﷺ personally lowered her into Jannat al-Baqi, offering his own blessed waist-wrapper (Izar) as her shroud."],majorHistoricalMilestones:[{eventTitleUrdu:"ابتدائے بعثت میں اسلام کی سب سے پہلی بیٹی",eventTitleEnglish:"First Daughter to Accept Islam in Makkah",descriptionUrdu:"سیدہ خدیجہ کے بعد بچپن ہی میں دینِ حق کی گواہی دی۔",descriptionEnglish:"Embraced the Da'wah alongside her mother Khadijah at dawn of Islam."},{eventTitleUrdu:"غزوۂ بدر میں سیدہ خدیجہ کے ہار کا تاریخ ساز واقعہ",eventTitleEnglish:"The Sacred Necklace of Khadijah at Badr",descriptionUrdu:"فدیے میں ہار بھیجا جس پر حضور ﷺ رو پڑے اور ہار واپس کروا دیا۔",descriptionEnglish:"Sent Khadijah's bridal necklace as ransom, moving the Prophet ﷺ to tears."},{eventTitleUrdu:"ہجرتِ مدینہ میں کاری زخم اور صبرِ ایوب",eventTitleEnglish:"Affliction During the Hijrah to Madinah",descriptionUrdu:"ہبار بن اسود کے حملے میں حمل ضائع ہوا مگر مدینہ پہنچ کر صبر فرمایا۔",descriptionEnglish:"Severely wounded by Makkan pursuers during Hijrah, enduring with patience."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"علامہ ابن عبد البر (رحمہ اللہ)",scholarNameEnglish:"Imam Ibn Abd al-Barr",bookTitle:"الاستیعاب فی معرفۃ الاصحاب",verbatimQuoteUrdu:"زینب حضور ﷺ کی سب سے بڑی بیٹی تھیں اور ان کی وفاداری اور صدمات پر صبر امت کے لیے مشعلِ راہ ہے۔",verbatimQuoteEnglish:"Zaynab was the eldest daughter of the Messenger ﷺ; her endurance of pain remains a beacon for the Ummah."}]},{id:"sah-14",nameUrdu:"سیدتنا رقیہ بنت رسول اللہ (رضی اللہ عنہا)",nameArabic:"رقية بنت محمد رسول الله القرشية الهاشمية",nameEnglish:"Sayyidatuna Ruqayyah bint Rasulillah (رضي الله عنها)",titleUrdu:"ذات الہجرتین، زوجۂ ذوالنورین، شہزادیٔ رسول",titleEnglish:"Dhat al-Hijratayn (Migrant of Two Hijrahs), Wife of Uthman",kinshipToProphet:"رسول اللہ ﷺ کی دوسری صاحبزادی، سیدنا عثمان غنی کی زوجۂ مطہرہ",kinshipToProphetEnglish:"Second Daughter of the Prophet ﷺ, Noble Spouse of Sayyiduna Uthman ibn Affan, Emigrant of Two Hijrahs",classicalCitation:"صحیح البخاری، حدیث ۳۱۳۰، ۳۶۹۸ / الطبقات الکبریٰ لابن سعد",era:"متوفی ۲ ہجری مدینہ منورہ (فتحِ بدر کے دن وصال)",biographyUrdu:"رسول اللہ ﷺ کی وہ پاکیزہ بیٹی جنہوں نے اسلام کی خاطر دو مرتبہ ہجرت فرمائی: پہلے حبشہ کی طرف اور پھر مدینہ منورہ کی طرف۔ سیدنا عثمان بن عفان رضی اللہ عنہ کے ساتھ ان کا نکاح آسمانوں پر مقدر تھا۔ غزوۂ بدر کے موقع پر شدید بیمار تھیں، حضور ﷺ نے حضرت عثمان کو ان کی تیمارداری کے لیے روکا اور انہیں بدر کے مجاہدین کے برابر اجر اور غنیمت کا حصہ عطا فرمایا۔",biographyEnglish:"The revered daughter of the Prophet ﷺ who undertook both foundational migrations of Islam: first to Abyssinia and then to Madinah alongside her husband Sayyiduna Uthman ibn Affan. During Badr, she fell mortally ill; the Prophet ﷺ ordered Uthman to nurse her, declaring he would receive the exact reward and spoils of a Badr warrior.",heroicAttributes:["حبشہ اور مدینہ کی دوہری ہجرت کا شرف","میکے اور سسرال کی مثالی پاکیزگی","مرضِ وفات پر صبر"],heroicAttributesEnglish:["Emigrant of Two Hijrahs","Patience in Sickness","Sacred Lineage","Serenity of Character"],dailySunnahLessons:[{ur:"دین کے تحفظ کے لیے اپنے وطن اور آسائشوں کو خوش دلی سے چھوڑ دینا۔",en:"Sacrificing personal comforts and homeland willingly to safeguard sacred faith."},{ur:"بیمار اہل خانہ اور شریکِ حیات کی تیمارداری کو جہاد کے برابر عبادت سمجھنا۔",en:"Treating the care of a sick spouse or parent as equal to the reward of frontline service."}],sanadVerificationHash:"SANAD-RUQAYYAH-BUKHARI-SAHIH-014",lineageAndBackgroundUrdu:"رقیہ بنت رسول اللہ محمد ﷺ بن عبد اللہ۔ والدہ سیدتنا خدیجہ الکبریٰ ہیں۔ بعثتِ نبوی سے سات سال قبل مکہ میں پیدا ہوئیں۔ ان کا نکاح سیدنا عثمان بن عفان رضی اللہ عنہ سے ہوا جو تاریخ کے سب سے باحیا انسان تھے۔",lineageAndBackgroundEnglish:"Second daughter of the Prophet ﷺ and Khadijah, born 7 years before Prophethood. Wed to Sayyiduna Uthman ibn Affan, forming the most noble and modest household in Madinah.",propheticPraiseHadithArabic:"\xabإِنَّ عُثْمَانَ وَرُقَيَّةَ لأَوَّلُ مَنْ هَاجَرَ إِلَى اللَّهِ بَعْدَ إِبْرَاهِيمَ وَلُوطٍ\xbb [المستدرك للحاكم: ۶۸۷۸ / مجمع الزوائد]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے سیدنا عثمان اور سیدہ رقیہ کے حق میں ارشاد فرمایا: "بے شک ابراہیم اور لوط علیہما السلام کے بعد عثمان اور رقیہ وہ پہلے انسان ہیں جنہوں نے اپنے اہل خانہ سمیت اللہ کی راہ میں ہجرت کی"۔',propheticPraiseHadithEnglish:'The Prophet ﷺ proclaimed regarding Uthman and Ruqayyah: "Verily, Uthman and Ruqayyah are the very first household to migrate in the path of Allah since Ibrahim and Lut." (Mustadrak al-Hakim)',propheticPraiseSource:"المستدرک علی الصحیحین، حدیث ۶۸۷۸ / صحیح البخاری، حدیث ۳۱۳۰",exhaustiveBiographyUrdu:['سیدتنا رقیہ رضی اللہ عنہا کو تاریخِ اسلام میں "ذات الہجرتین" (دو ہجرتوں والی عظیم خاتون) کے لقب سے جانا جاتا ہے۔ جب مکہ میں قریش کا ظلم و ستم انتہا کو پہنچ گیا اور مسلمانوں پر زمین تنگ کر دی گئی، تو رسول اللہ ﷺ نے حبشہ کی طرف ہجرت کا حکم دیا۔ سیدتنا رقیہ اپنے شوہر سیدنا عثمان بن عفان کے ساتھ سمندر کا پرخطر سفر طے کر کے حبشہ پہنچیں اور وہاں کئی سال غربت و جلاوطنی میں صبر سے گزارے۔',"جب رسول اللہ ﷺ نے مدینہ کی طرف ہجرت فرمائی، تو سیدہ رقیہ اور سیدنا عثمان حبشہ سے واپس مکہ آئے اور پھر وہاں سے مدینہ کی دوسری مبارک ہجرت فرمائی۔ مدینہ منورہ میں ان کے بیٹے حضرت عبد اللہ بن عثمان کی ولادت ہوئی جن کی وفات پر انہیں گہرا صدمہ پہنچا۔",'۲ ہجری میں جب مسلمان غزوۂ بدر کے لیے نکل رہے تھے، تو سیدتنا رقیہ کو شدید چیچک اور تیز بخار نے آ لیا۔ سیدنا عثمان غنی رسول اللہ ﷺ کے ساتھ بدر کے معرکے میں جانا چاہتے تھے، مگر حضور ﷺ نے حکم دیا: "تم رقیہ کے پاس ٹھہرو، تمہیں بدر میں حاضر ہونے والے مجاہد جتنا اجر اور مالِ غنیمت کا پورا حصہ ملے گا"۔',"جس دن حضرت زید بن حارثہ رضی اللہ عنہ بدر کی عظیم الشان فتح کی خوشخبری لے کر مدینہ منورہ میں داخل ہوئے، اسی دن سیدتنا رقیہ کا وصال ہوا اور انہیں جنت البقیع میں دفن کیا جا رہا تھا۔ سیدنا عثمان ان کی جدائی پر رو پڑے تو رسول اللہ ﷺ نے فرمایا کہ رقیہ اپنے سلفِ صالحین سے جا ملی ہیں۔"],exhaustiveBiographyEnglish:["Sayyidatuna Ruqayyah (رضي الله عنها) earned the immortal historical title Dhat al-Hijratayn (The Lady of Two Migrations). During the darkest persecutions in Makkah, she crossed the Red Sea with Sayyiduna Uthman to seek asylum under the righteous Negus of Abyssinia.","Upon hearing of the Prophet's migration to Madinah, the couple returned and undertook the second arduous journey to the City of the Prophet. In Madinah, she nurtured her young son Abdullah until his untimely passing, enduring maternal grief with steadfast prayer.",'In 2 AH, as the Muslim army mobilized for the decisive Battle of Badr, Ruqayyah contracted a virulent fever. Uthman ardently desired to march with the Prophet ﷺ, but the Messenger ordered: "Remain with Ruqayyah; you shall receive the full reward and war spoils of a warrior present at Badr." (Sahih al-Bukhari #3130).',"On the very afternoon that Zayd ibn Harithah rode into Madinah proclaiming the historic victory of Badr, Ruqayyah passed into the divine presence. She was laid to rest in Jannat al-Baqi, mourned by the entire Muslim community."],majorHistoricalMilestones:[{eventTitleUrdu:"حبشہ کی طرف پہلی پرخطر سمندری ہجرت",eventTitleEnglish:"The First Historic Migration to Abyssinia",descriptionUrdu:"سیدنا عثمان کے ساتھ اسلام کی پہلی بین الاقوامی ہجرت فرمائی۔",descriptionEnglish:"Part of the premier Muslim contingent seeking asylum across the Red Sea."},{eventTitleUrdu:"مدینہ منورہ کی طرف دوسری ہجرت (ذات الہجرتین)",eventTitleEnglish:"The Second Migration to Madinah",descriptionUrdu:"حبشہ سے واپسی کے بعد دربارِ رسالت مدینہ میں سکونت اختیار کی۔",descriptionEnglish:"Undertook the second migration to Madinah, earning the title Dhat al-Hijratayn."},{eventTitleUrdu:"فتحِ بدر کے دن وصال اور عثمان غنی کا بدری اجر پانا",eventTitleEnglish:"Passing on the Day of Badr Victory",descriptionUrdu:"حضور ﷺ کے حکم سے سیدنا عثمان نے تیمارداری کی اور بدری مجاہد کا درجہ پایا۔",descriptionEnglish:"Passed away as Badr victory tidings arrived; Uthman granted full Badr status."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"حافظ ابن حجر العسقلانی (رحمہ اللہ)",scholarNameEnglish:"Hafidh Ibn Hajar al-Asqalani",bookTitle:"الاصابة فی تمييز الصحابة",verbatimQuoteUrdu:"رقیہ بنت رسول اللہ ہجرتین کی فضیلت رکھنے والی تھیں اور ان کے حق میں حضور ﷺ کی دعائیں مستجاب تھیں۔",verbatimQuoteEnglish:"Ruqayyah possessed the merit of both migrations, and the Prophet's prayers for her were universally answered."}]},{id:"sah-15",nameUrdu:"سیدتنا ام کلثوم بنت رسول اللہ (رضی اللہ عنہا)",nameArabic:"أم كلثوم بنت محمد رسول الله القرشية الهاشمية",nameEnglish:"Sayyidatuna Umm Kulthum bint Rasulillah (رضي الله عنها)",titleUrdu:"کریمۂ مصطفیٰ، رفیقۂ ذوالنورین، صابرہ",titleEnglish:"Daughter of the Prophet ﷺ, The Second Light of Uthman",kinshipToProphet:"رسول اللہ ﷺ کی تیسری صاحبزادی، حضرت عثمان کی دوسری زوجۂ مطہرہ",kinshipToProphetEnglish:"Third Daughter of the Prophet ﷺ, Second Noble Spouse of Sayyiduna Uthman ibn Affan (Dhun-Nurayn)",classicalCitation:"صحیح البخاری، حدیث ۱۲۸۵ / سنن ابن ماجہ، حدیث ۱۴۵۹",era:"متوفی ۹ ہجری مدینہ منورہ (جنت البقیع)",biographyUrdu:'رسول اللہ ﷺ کی وہ عظیم الشان بیٹی جن کے عقد میں آنے کے بعد حضرت عثمان کو "ذوالنورین" (دو نوروں والا) کا تاریخی اور منفرد لقب ملا۔ جب سیدہ رقیہ کے وصال کے بعد رسول اللہ ﷺ نے اپنی تیسری بیٹی ام کلثوم کا نکاح حضرت عثمان سے فرمایا، تو ارشاد فرمایا: "اگر میری چالیس بیٹیاں بھی ہوتیں تو میں ایک کے بعد ایک کر کے سب عثمان کے نکاح میں دے دیتا"۔ شعبِ ابی طالب کی تین سالہ بھوک اور بائیکاٹ میں حضور ﷺ کی خدمت میں پیش پیش رہیں۔',biographyEnglish:"The blessed third daughter of the Prophet ﷺ whose marriage to Sayyiduna Uthman after Ruqayyah's passing cemented Uthman's eternal title Dhu al-Nurayn (Possessor of Two Lights). Endured the grueling 3-year siege of Shi'b Abi Talib. The Prophet ﷺ proclaimed: \"If I possessed forty daughters, I would marry them to Uthman one after another.\"",heroicAttributes:["شعبِ ابی طالب کے بائیکاٹ میں باپ کی خدمت","سیدنا عثمان کے گھر کو نور بنانے والی رفیقہ","بے پناہ زہد و حیا"],heroicAttributesEnglish:["Spouse of Dhun-Nurayn","Support of the Mission","Purity and Grace","Patience in the Path of Allah"],dailySunnahLessons:[{ur:"آزمائش کے وقت اپنے والدین اور بزرگوں کی دل و جان سے خدمت کرنا۔",en:"Standing selflessly beside parents and family elders during periods of intense trial."},{ur:"نیک اور باحیا شریکِ حیات کے ساتھ زندگی گزار کر گھر کو ذکر اور عبادت کا گہوارہ بنانا۔",en:"Transforming one's home into an abode of modesty, peace, and regular remembrance."}],sanadVerificationHash:"SANAD-UMM-KULTHUM-BUKHARI-015",lineageAndBackgroundUrdu:"ام کلثوم بنت رسول اللہ محمد ﷺ بن عبد اللہ بن عبد المطلب۔ والدہ ماجدہ سیدتنا خدیجہ الکبریٰ ہیں۔ اپنی چھوٹی بہن سیدہ فاطمۃ الزہراء رضی اللہ عنہا سے عمر میں بڑی تھیں۔ بعثت سے ۶ سال قبل مکہ میں ولادت ہوئی۔",lineageAndBackgroundEnglish:"Third daughter of the Prophet ﷺ and Khadijah. Older than Sayyidatuna Fatimah. Born in Makkah 6 years before the commencement of Prophethood.",propheticPraiseHadithArabic:"\xabلَوْ كَانَ عِنْدِي ثَالِثَةٌ لَزَوَّجْتُكَهَا يَا عُثْمَانُ\xbb [المعجم الكبير للطبراني / مجمع الزوائد: ۹/۸۳]",propheticPraiseHadithUrdu:'رسول اللہ ﷺ نے سیدتنا ام کلثوم کے وصال پر حضرت عثمان غنی سے فرمایا: "اے عثمان! اگر میرے پاس تیسری بیٹی بھی ہوتی تو میں اس کا نکاح بھی تم سے کر دیتا!"۔',propheticPraiseHadithEnglish:"The Messenger of Allah ﷺ comforted Sayyiduna Uthman: \"If I possessed a third daughter, O Uthman, I would surely have given her to you in marriage!\" (Al-Mu'jam al-Kabir / Majma' al-Zawa'id)",propheticPraiseSource:"المعجم الکبیر للطبرانی، ج ۲۲ / مجمع الزوائد للہیثمی، ج ۹، ص ۸۳",exhaustiveBiographyUrdu:["سیدتنا ام کلثوم رضی اللہ عنہا آقائے دو جہاں ﷺ کے گھرانے کا وہ روشن چراغ ہیں جنہوں نے اسلام کی خاطر بچپن ہی سے غیر معمولی مشقتیں دیکھیں۔ جب مشرکینِ مکہ نے رسول اللہ ﷺ اور بنو ہاشم کو شعبِ ابی طالب کی گھاٹی میں قید کیا، تو ام کلثوم نے اپنی والدہ حضرت خدیجہ اور بہنوں کے ساتھ تین سال تک پتے چبا کر اور بھوک پیاس کی سختیاں جھیل کر اپنے والد کا ساتھ دیا۔","جب مکہ سے مدینہ کی طرف ہجرت ہوئی، تو حضور ﷺ نے حضرت زید بن حارثہ کو مکہ بھیج کر سیدتنا ام کلثوم، سیدہ فاطمہ اور ام المؤمنین سودہ رضی اللہ عنہن کو باحفاظت مدینہ منورہ بلوایا۔ مدینہ میں آپ نے والدِ گرامی کی خدمت میں زندگی کے پرسکون ایام گزارے۔",'۳ ہجری میں جب سیدہ رقیہ کے انتقال کے بعد حضرت عثمان غنی غمزدہ تھے، تو رسول اللہ ﷺ نے وحیِ الٰہی کی روشنی میں ام کلثوم کا نکاح عثمان غنی سے فرمایا۔ تاریخِ انسانی میں حضرت عثمان کے سوا کسی انسان کو یہ شرف حاصل نہیں ہوا کہ اس کے نکاح میں کسی نبی کی دو بیٹیاں یکے بعد دیگرے آئی ہوں! اسی لیے انہیں "ذوالنورین" کہا جاتا ہے۔',"سیدتنا ام کلثوم حضرت عثمان کے گھر میں چھ سال تک پرسکون رفاقت میں رہیں، تاآنکہ ۹ ہجری کے شعبان میں ان کا وصال ہوا۔ رسول اللہ ﷺ نے خود ان کی نمازِ جنازہ پڑھائی، اور جب قبر میں اتارا جا رہا تھا تو حضور ﷺ کی آنکھوں سے آنسو رواں تھے۔ آپ نے صحابہ کو تلقین فرمائی کہ عثمان کے ساتھ حسنِ سلوک کریں کیونکہ اس نے میرے دو جگر کے ٹکڑوں کو پناہ دی تھی۔"],exhaustiveBiographyEnglish:["Sayyidatuna Umm Kulthum (رضي الله عنها) endured the fire of persecution from childhood. Confined with the Prophet ﷺ in the sun-baked gorge of Shi'b Abi Talib for three agonizing years, she sustained her ailing mother Khadijah and supported her father through starvation and societal boycott.","Following the Hijrah, the Prophet ﷺ dispatched Zayd ibn Harithah to escort Umm Kulthum, Fatimah, and Mother of the Believers Sawdah safely to Madinah, where she resumed household duties in the newly established Islamic commonwealth.","In 3 AH, following the grief of Ruqayyah's passing, the Prophet ﷺ informed Uthman that Archangel Jibril had descended commanding her marriage to him. No human being in history ever wed two daughters of a Messenger of Allah except Uthman, immortalizing him as Dhu al-Nurayn (Possessor of the Two Lights).","She graced Uthman's home for six harmonious years before falling ill and passing away in Sha'ban 9 AH. The Prophet ﷺ led her funeral prayer. As she was lowered into Jannat al-Baqi, tears streamed down the Prophet's face. He comforted Uthman, attesting: \"If I possessed a third daughter, I would give her to you.\""],majorHistoricalMilestones:[{eventTitleUrdu:"شعبِ ابی طالب کے تین سالہ محاصرے میں استقامت",eventTitleEnglish:"Fortitude During 3-Year Siege of Shi'b Abi Talib",descriptionUrdu:"بچپن میں بائیکاٹ اور فاقہ کشی کے ایام والد کے ساتھ کاٹے۔",descriptionEnglish:"Endured famine and economic blockade alongside the Prophet ﷺ."},{eventTitleUrdu:'سیدنا عثمان سے نکاح اور "ذوالنورین" کا لقب',eventTitleEnglish:"Marriage to Uthman & Bestowal of Dhu al-Nurayn",descriptionUrdu:"سیدہ رقیہ کے بعد نکاح میں آئیں اور حضرت عثمان دو نوروں والے بنے۔",descriptionEnglish:"Consecrated Uthman's eternal historical title of Possessor of Two Lights."},{eventTitleUrdu:"۹ ہجری میں وصال اور روضۂ اقدس کے پاس تدفین",eventTitleEnglish:"Passing in 9 AH & Jannat al-Baqi Burial",descriptionUrdu:"حضور ﷺ نے خود نمازِ جنازہ پڑھائی اور آنسوؤں سے رخصت فرمایا۔",descriptionEnglish:"The Prophet ﷺ wept as she was laid to rest beside her sister in Baqi."}],classicalScholarlyEndorsements:[{scholarNameUrdu:"امام جلال الدین السیوطی (رحمہ اللہ)",scholarNameEnglish:"Imam Jalal al-Din al-Suyuti",bookTitle:"الخصائص الکبریٰ",verbatimQuoteUrdu:"حضرت عثمان کے علاوہ تاریخ میں کسی بشر کو یہ شرف نہیں ملا کہ اس کے پاس کسی نبی کے دو نور جمع ہوئے ہوں۔",verbatimQuoteEnglish:"No human in history was honored to unite two lights of a Messenger in marriage except Sayyiduna Uthman."}]}],n=[{id:"f-01",titleUrdu:"حیض کی کم سے کم اور زیادہ سے زیادہ مدت",titleEnglish:"Minimum and Maximum Durations of Haidh (Menstruation)",titleRomanUrdu:"Haidh ki Kam se Kam aur Zyada se Zyada Muddat",category:"haidh",summaryUrdu:"فقہ حنفی میں حیض کی کم سے کم مدت ۳ دن اور ۳ راتیں (۷۲ گھنٹے) اور زیادہ سے زیادہ ۱۰ دن اور ۱۰ راتیں (۲۴۰ گھنٹے) ہیں۔",summaryEnglish:"In Hanafi Fiqh, the minimum duration of menses is 3 days and 3 nights (72 hours), while the maximum is 10 days and 10 nights (240 hours).",summaryRomanUrdu:"Fiqh Hanafi mein haidh ki kam se kam muddat 3 din aur 3 raatein (72 ghante) aur zyada se zyada 10 din aur 10 raatein (240 ghante) hain.",detailedRulingUrdu:'اگر خون ۳ دن اور ۳ راتوں سے کم آ کر بند ہو جائے، یا ۱۰ دن ۱۰ راتوں سے تجاوز کر جائے، تو وہ حیض نہیں بلکہ "استحاضہ" (بیماری کا خون) کہلائے گا۔ دو حیض کے درمیانی وقفے (طہر) کی کم سے کم مدت ۱۵ دن ہے، زیادہ کی کوئی حد نہیں۔',detailedRulingEnglish:"If bleeding stops in less than 72 hours, or exceeds 240 hours (10 days/nights), it is not Haidh but Istihadha (irregular bleeding due to illness). The minimum period of purity (Tuhr) between two menstrual cycles is 15 days; there is no maximum limit.",detailedRulingRomanUrdu:'Agar khoon 3 din aur 3 raaton se kam aa kar band ho jaye, ya 10 din 10 raaton se tajawuz kar jaye, to woh haidh nahi balkey "istihadha" (beemari ka khoon) kehlayega. Do haidh ke darmiyani waqfe (tuhr) ki kam se kam muddat 15 din hai, zyada ki koi hadd nahi.',hanafiReference:"بہارِ شریعت، حصہ ۲ / درِ مختار و رد المحتار، کتاب الطہارۃ",practicalGuidelines:["اپنے مخصوص ایام کے شروع اور ختم ہونے کے اوقات کا کیلنڈر یا ڈائری میں باقاعدہ اندراج رکھیں۔","عادت کے دنوں کا خاص خیال رکھیں، کیونکہ اکثر عورتوں کے دن مقرر ہوتے ہیں۔","۱۰ دن پورے ہونے پر فورا غسل کر کے نماز شروع کر دیں چاہے ہلکا داغ ہی کیوں نہ ہو۔"],practicalGuidelinesEnglish:["Maintain an exact record of the start and end dates/times of your bleeding in your journal.","Pay close attention to your established habit (Aadat), as most women have a fixed number of days.","Once 10 full days are completed, take Ghusl immediately and resume Salah, even if light spotting continues."],practicalGuidelinesRomanUrdu:["Apne makhsoos ayyam ke shuru aur khatam hone ke auqat ka calendar ya diary mein baqaeda indiraaj rakhein.","Aadat ke dinon ka khaas khayal rakhein, kyunke aksar aurton ke din muqarrar hote hain.","10 din poore hone par fauran ghusl kar ke namaz shuru kar dein chahe halka daagh hi kyun na ho."]},{id:"f-02",titleUrdu:"مخصوص ایام میں نماز، روزہ اور تلاوت کے احکام",titleEnglish:"Rules Regarding Prayer, Fasting, and Quran Recitation",titleRomanUrdu:"Makhsoos Ayyam mein Namaz, Roza aur Tilawat ke Ahkam",category:"haidh",summaryUrdu:"حیض کے ایام میں نماز بالکل معاف ہے (قضا بھی نہیں)، روزہ چھوڑنا واجب ہے (بعد میں قضا رکھنا فرض ہے)، اور مصحف کو چھونا و زبانی تلاوت کرنا منع ہے۔",summaryEnglish:"During menses, prayer is completely waived (no Qadha required), fasting is suspended (deferred Qadha is obligatory), and touching/reciting the Quran directly is prohibited.",summaryRomanUrdu:"Haidh ke ayyam mein namaz bilkul maaf hai (qadha bhi nahi), roza chhorna wajib hai (baad mein qadha rakhna farz hai), aur Mushaf ko chhoona wa zabani tilawat karna mana hai.",detailedRulingUrdu:"رسول اللہ ﷺ نے فرمایا کہ عورت کے لیے نماز اور روزہ چھوڑنا شریعت کی آسانی ہے۔ پاک ہونے کے بعد چھوٹے ہوئے روزوں کی قضا سردیوں یا آسانی کے دنوں میں ایک ایک کر کے رکھنا فرض ہے۔ قرآن پاک کی تلاوت کی نیت کے بغیر اگر کوئی دعا یا وظیفہ قرآن کی آیات میں سے پڑھا جائے (جیسے بسم اللہ، الحمد للہ، انا للہ) تو جائز ہے۔",detailedRulingEnglish:"The Prophet ﷺ confirmed that the waiver of prayer and postponement of fasting is a divine concession. Deferred Ramadan fasts must be made up individually when purified. While reciting the Quran with the intention of Tilawah is prohibited, reciting Quranic verses with the intention of Du'a, Dhikr, or remembrance (such as Bismillah, Alhamdulillah, or Inna Lillahi) is permissible.",detailedRulingRomanUrdu:"Rasoolullah ﷺ ne farmaya ke aurat ke liye namaz aur roza chhorna shariat ki aasani hai. Paak hone ke baad chhoote hue rozon ki qadha sardiyon ya aasani ke dinon mein ek ek kar ke rakhna farz hai. Quran Paak ki tilawat ki niyat ke baghair agar koi dua ya wazeefa Quran ki aayat mein se parha jaye (jaise Bismillah, Alhamdulillah, Inna Lillahi) to jaiz hai.",hanafiReference:"صحیح البخاری، حدیث ۳۰۴ / فتاویٰ عالمگیری، ج ۱",practicalGuidelines:["رمضان کے روزوں کی قضا اگلے رمضان سے پہلے کسی بھی وقت رکھی جا سکتی ہے۔","قرآن پاک کو کسی کپڑے یا غلاف سے پکڑا جا سکتا ہے لیکن چھونا جائز نہیں۔","دینی کتابیں جیسے جنتی زیور یا تفسیر کے وہ حصے جن میں ترجمہ و تشریح زیادہ ہو، پڑھنا جائز ہے۔"],practicalGuidelinesEnglish:["Deferred Ramadan fasts can be completed anytime before the arrival of the next Ramadan.","The Quran may be held using an unattached cloth, pouch, or case, but direct skin contact with the script is unlawful.","Reading Islamic books like Jannati Zewar or books of Tafsir where translation and commentary exceed Arabic script is permissible."],practicalGuidelinesRomanUrdu:["Ramadan ke rozon ki qadha agle Ramadan se pehle kisi bhi waqt rakhi ja sakti hai.","Quran Paak ko kisi kapray ya ghilaf se pakra ja sakta hai lekin choona jaiz nahi.","Deeni kitabein jaise Jannati Zewar ya Tafseer ke woh hisse jin mein tarjuma o tashreeh zyada ho, parhna jaiz hai."]},{id:"f-03",titleUrdu:"نفاس (بچے کی ولادت کے بعد کا خون) کے احکام",titleEnglish:"Rulings on Nifas (Postnatal Bleeding)",titleRomanUrdu:"Nifas (Bachhe ki Wiladat ke Baad ka Khoon) ke Ahkam",category:"nifas",summaryUrdu:"ولادت کے بعد آنے والے خون کو نفاس کہتے ہیں۔ اس کی زیادہ سے زیادہ مدت ۴۰ دن اور ۴۰ راتیں ہیں۔ کم سے کم کی کوئی قید نہیں، اگر ایک گھنٹے میں بھی بند ہو جائے تو غسل کر کے نماز فرض ہے۔",summaryEnglish:"Nifas is postnatal bleeding. The maximum limit is 40 days and nights. There is no minimum; if bleeding ceases after a few days or hours, Ghusl is obligatory immediately and prayers resume.",summaryRomanUrdu:"Wiladat ke baad aane wale khoon ko nifas kehte hain. Iski zyada se zyada muddat 40 din aur 40 raatein hain. Kam se kam ki koi qaid nahi, agar ek ghante mein bhi band ho jaye to ghusl kar ke namaz farz hai.",detailedRulingUrdu:"اگر خون چالیس دن سے پہلے ہی بند ہو گیا، مثلاً ۲۰ یا ۲۵ دن پر، تو چالیس دن کا انتظار کرنا سخت گناہ ہے! جیسے ہی خون بند ہو، فورا غسل کریں اور اپنی نمازیں شروع کریں۔ چالیس دن کے بعد آنے والا خون استحاضہ (بیماری) شمار ہوگا، اس میں نماز نہیں چھوڑی جائے گی۔",detailedRulingEnglish:"If bleeding stops before 40 days (e.g. on day 20 or 25), waiting for 40 days is prohibited. As soon as bleeding ceases and purity appears, Ghusl is immediately obligatory and Salah must resume. Any bleeding extending beyond 40 days is treated as Istihadha (illness), during which prayers cannot be abandoned.",detailedRulingRomanUrdu:"Agar khoon 40 din se pehle hi band ho gaya, maslan 20 ya 25 din par, to 40 din ka intezar karna sakht gunah hai! Jaise hi khoon band ho, fauran ghusl karein aur apni namazein shuru karein. 40 din ke baad aane wala khoon istihadha (beemari) shumar hoga, is mein namaz nahi chhori jayegi.",hanafiReference:"سنن ابی داؤد، حدیث ۳۱۱ / بہارِ شریعت، حصہ ۲",practicalGuidelines:["چالیس دن پورا ہونے کا بلاوجہ انتظار نہ کریں، سفیدی ظاہر ہوتے ہی غسل کریں۔","نفاس میں بھی حیض کی طرح نماز بالکل معاف ہے اور روزوں کی قضا بعد میں لازم ہے۔"],practicalGuidelinesEnglish:["Do not wait unnecessarily for 40 days to elapse; take Ghusl as soon as clear discharge appears.","Just like Haidh, prayers during Nifas are completely waived without Qadha, while fasts must be made up later."],practicalGuidelinesRomanUrdu:["40 din poora hone ka bila-wajah intezar na karein, safedi zahir hote hi ghusl karein.","Nifas mein bhi haidh ki tarah namaz bilkul maaf hai aur rozon ki qadha baad mein lazim hai."]},{id:"f-04",titleUrdu:"استحاضہ (بیماری کا خون) میں طہارت اور نماز کا طریقہ",titleEnglish:"Taharah and Salah Guidelines during Istihadha (Irregular Bleeding)",titleRomanUrdu:"Istihadha (Beemari ka Khoon) mein Taharah aur Namaz ka Tareeqah",category:"istihadha",summaryUrdu:'استحاضہ بیماری ہے، اس میں نماز اور روزہ کسی صورت معاف نہیں۔ ایسی بہن "معذورِ شرعی" کا حکم رکھتی ہے اور ہر فرض نماز کے وقت نیا وضو کر کے نماز پڑھے گی۔',summaryEnglish:"Istihadha is due to illness; prayer and fasting are NEVER exempt. A sister experiencing Istihadha performs a fresh Wudu for each obligatory prayer time and prays normally.",summaryRomanUrdu:"Istihadha beemari hai, is mein namaz aur roza kisi soorat maaf nahi. Aisi behen \"ma'zoor-e-shar'i\" ka hukm rakhti hai aur har farz namaz ke waqt naya wuzu kar ke namaz parhegi.",detailedRulingUrdu:"جب تک وہ نماز کا وقت باقی رہے گا، اس کا وضو قائم رہے گا، خون کے بہنے سے وضو نہیں ٹوٹے گا۔ اس دوران وہ جتنے چاہے نفل، قضا نمازیں اور تلاوتِ قرآن کر سکتی ہے۔ جب اگلی نماز کا وقت داخل ہوگا تو نیا وضو کرنا ہوگا۔",detailedRulingEnglish:"The Prophet ﷺ instructed that Istihadha is bleeding from a vessel, not the womb. A sister with Istihadha is considered excused (Ma'dhur): she performs Wudu once after the prayer time enters, and her Wudu remains valid for all obligatory and voluntary prayers throughout that entire prayer window regardless of continuous bleeding. When the next prayer time enters, a new Wudu is performed.",detailedRulingRomanUrdu:"Jab tak woh namaz ka waqt baqi rahega, uska wuzu qayam rahega, khoon ke behne se wuzu nahi tootega. Is dauran woh jitne chahe nafl, qadha namazein aur tilawat-e-Quran kar sakti hai. Jab agli namaz ka waqt dakhil hoga to naya wuzu karna hoga.",hanafiReference:"صحیح البخاری، حدیث ۲۲۸ / درِ مختار، باب الحیض",practicalGuidelines:["ہر نماز کی اذان کے بعد نیا تازہ وضو کریں۔","نماز سے پہلے صاف پیڈ یا کپڑا تبدیل کر لیں تاکہ نجاست کم سے کم رہے۔","استحاضہ میں روزہ رکھنا بالکل درست اور فرض ہے۔"],practicalGuidelinesEnglish:["Perform a fresh, valid Wudu after the Adhan / entry of each prayer time.","Use fresh hygiene pads before prayer to minimize external impurity as much as practically possible.","Fasting during Istihadha is completely valid and obligatory in Ramadan."],practicalGuidelinesRomanUrdu:["Har namaz ki azaan ke baad naya taaza wuzu karein.","Namaz se pehle saaf pad ya kapra tabdeel kar lein taake nijasat kam se kam rahe.","Istihadha mein roza rakhna bilkul durust aur farz hai."]},{id:"f-05",titleUrdu:"خواتین کی نماز میں حیا اور سجدے کی خاص ہیئت",titleEnglish:"Modesty and Physical Posture of Women in Prayer",category:"namaz_posture",summaryUrdu:"شریعت نے عورت کو نماز میں زیادہ سے زیادہ سمٹ کر رہنے کا حکم دیا ہے تاکہ مکمل پردہ اور حیا برقرار رہے۔",summaryEnglish:"In authentic Hanafi jurisprudence, women's prayer postures emphasize modesty, containment, and compactness to preserve complete covering.",detailedRulingUrdu:"تکبیر تحریمہ میں ہاتھ صرف سینے یا کندھوں تک چادر کے اندر سے اٹھائے جائیں۔ قیام میں ہاتھ سینے پر باندھے جائیں (سینہ کے اوپر بایاں ہاتھ اور اس پر دایاں ہاتھ)۔ رکوع میں صرف اتنا جھکیں کہ ہاتھ گھٹنوں تک پہنچ جائیں، انگلیاں گھٹنوں پر بغیر کشادہ کیے رکھیں۔ سجدے میں سمٹ کر سجدہ کریں، یعنی بازو زمین پر بچھا دیں اور پیٹ رانوں سے ملا رہے اور پاؤں کھڑے کرنے کے بجائے دائیں طرف نکال کر بچھا دیں۔",detailedRulingEnglish:"In Hanafi jurisprudence (Al-Hidayah and Bahar-e-Shari'at), women's prayer posture is rooted in modesty (Satr and Haya). In Takbeer Tahrimah, hands are raised only up to shoulders/chest beneath the veil. In Qiyam, hands are folded on the chest. In Ruku, bend only enough for hands to reach knees with fingers joined. In Sujud, keep the posture compact: rest arms flat on the floor, keep the abdomen close to thighs, and extend both feet outward to the right (Tawarruk).",hanafiReference:"مراسیل ابی داؤد، حدیث ۸۷ / الہدایہ للمرغینانی / فتاویٰ رضویہ",practicalGuidelines:["سر کے بالوں کی ایک لٹ بھی نماز کے دوران دوپٹے یا چادر سے باہر نہ نکلنے پائے۔","پاؤں کے ٹخنے اور کلائیاں بھی عورت کے ستر میں شامل ہیں، ان کا چھپانا فرض ہے۔","اگر بال یا کلائی کا چوتھائی حصہ ایک رکن کی ادائیگی (تین بار سبحان ربی الاعلیٰ کہنے کی مدت) کھلا رہا تو نماز فاسد ہو جائے گی۔"],practicalGuidelinesEnglish:["Ensure every strand of hair is completely concealed beneath the headscarf during prayer.","Ankles and wrists are part of the Aurah (nakedness) that must be covered during Salah.","If one-fourth of a limb (like hair or forearm) remains uncovered for the duration of a pillar (three Subhana Rabbiyal A'la), the prayer is invalidated."]},{id:"f-06",titleUrdu:"مخصوص ایام میں ذکر و عبادت کا جاری و ساری تسلسل",titleEnglish:"Maintaining an Unbroken Spiritual Rhythm During Menstruation",category:"spiritual_rhythm",summaryUrdu:"یہ ایک غلط فہمی ہے کہ مخصوص ایام میں عورت عبادت نہیں کر سکتی۔ نماز کے اوقات میں مصلے پر بیٹھ کر درود شریف، استغفار اور تسبیحات پڑھنا مستحب اور ثواب کا باعث ہے۔",summaryEnglish:"It is a profound misconception that women cannot worship during menstruation. Sitting on the prayer mat at prayer times for Dhikr, Salawat, and Istighfar is highly rewarded.",detailedRulingUrdu:"فقہائے کرام فرماتے ہیں کہ مستحب یہ ہے کہ جس طرح عام دنوں میں نماز کے وقت وضو کر کے مصلے پر بیٹھتی تھیں، اسی طرح مخصوص ایام میں بھی نماز کے اوقات میں باوضو ہو کر جائے نماز پر قبلہ رخ بیٹھیں اور اتنی دیر تک درود پاک، تسبیح، استغفار اور دعائیں پڑھتی رہیں جتنی دیر نماز میں لگتی تھی، تاکہ عبادت کی عادت اور نور برقرار رہے۔",detailedRulingEnglish:"Classical Hanafi jurists (Radd al-Muhtar) explain that it is commendable (Mustahabb) for a sister during her cycle to perform Wudu at each prayer time, sit facing the Qiblah on her prayer mat, and engage in remembrance of Allah, Salawat upon the Prophet ﷺ, and Istighfar for the duration of a standard prayer. This maintains continuous spiritual light and avoids spiritual apathy.",hanafiReference:"رد المحتار علی الدر المختار، ج ۱ / جنتی زیور",practicalGuidelines:["صبح اور شام کے مسنون اذکار (آیت الکرسی کے علاوہ یا دعا کی نیت سے) باقاعدگی سے پڑھیں۔","دل میں درود شریف (صلی اللہ علی النبی الامی) کی کثرت رکھیں، اس پر کوئی پابندی نہیں۔","قرآن پاک کی تلاوت سننے میں کوئی حرج نہیں، موبائل سے تلاوت سن کر تدبر کرنا جائز ہے۔"],practicalGuidelinesEnglish:["Recite morning and evening Adhkar regularly (reading Ayat-ul-Kursi with the intention of Du'a is permissible).","Abound in Salawat upon the Prophet ﷺ; there are zero restrictions on sending blessings.","Listening to Quranic recitation via audio and contemplating its meanings is permissible and deeply spiritually comforting."]},{id:"f-07",titleUrdu:"اسقاطِ حمل (مِس کیرج) کے بعد آنے والے خون کے تفصیلی احکام",titleEnglish:"Rulings on Bleeding Following Miscarriage (Isqat-e-Haml)",category:"nifas",summaryUrdu:"حمل ضائع ہونے پر اگر جنین کے کچھ اعضاء (انگلی، ناخن، بال) بن چکے تھے تو آنے والا خون نفاس ہے، ورنہ وہ نفاس نہیں بلکہ استحاضہ یا حیض ہے۔",summaryEnglish:"If physical limbs (finger, nail, hair) had formed before miscarriage (~120 days), the subsequent bleeding is Nifas; if an unformed clot, it is not Nifas but Istihadha.",detailedRulingUrdu:'فقہ حنفی کے مطابق اعضاء بننے کی مدت عموماً ۱۲۰ دن (چار ماہ) اور بعض اوقات ۸۱ دن میں بھی خدوخال ظاہر ہو سکتے ہیں۔ پس اگر ڈاکٹر یا دائی تصدیق کرے کہ ہاتھ، پاؤں یا انگلیوں کی بناوٹ شروع ہو چکی تھی تو ولادت کے بعد آنے والا خون "نفاس" ہے (جس میں نماز بالکل معاف ہے)۔ لیکن اگر محض خون کا لوتھڑا یا بغیر اعضاء کے گوشت گرا تو وہ نفاس نہیں۔ ایسی صورت میں اگر پچھلے طہر کے بعد ۱۵ دن گزر چکے تھے اور ۳ دن سے زیادہ خون آیا تو وہ حیض ہے، ورنہ "استحاضہ" (بیماری کا خون) ہے جس میں نماز بالکل معاف نہیں اور غسل کے بعد وضو کر کے ہر نماز پڑھنا فرض ہے۔',detailedRulingEnglish:"According to Hanafi jurisprudence (Al-Hidayah & Radd al-Muhtar), limb differentiation typically occurs by 120 days. If medical inspection confirms any limbs or features were visible, the bleeding is strictly Nifas (prayers are completely exempt). If the miscarriage was merely an unformed clot or tissue, it cannot be Nifas: it is classified as Haidh if 15 days of purity intervened and bleeding lasts 3+ days, otherwise it is Istihadha (prayers are strictly obligatory and cannot be abandoned).",hanafiReference:"بہارِ شریعت، حصہ ۲، باب النفاس / درِ مختار و رد المحتار، کتاب الطہارۃ، ج ۱",practicalGuidelines:["ہسپتال میں ڈاکٹر سے جنین کی حالت دریافت کریں کہ کیا اعضاء کے نقوش بن چکے تھے یا نہیں۔","اگر اعضاء نہیں بنے تھے اور خون جاری رہے تو اسے نفاس سمجھ کر نمازیں ہرگز نہ چھوڑیں، بلکہ غسل کر کے معذور کی طرح نماز ادا کریں۔","اگر ناواقفیت میں نمازیں چھوٹ گئیں تو اعضاء نہ بننے کی صورت میں ان نمازوں کی قضا پڑھنا لازم ہے۔"],practicalGuidelinesEnglish:["Ask the attending physician whether any morphological features or embryonic limbs had formed.","If limbs were absent and bleeding persists, do not abandon prayer; perform Ghusl and pray under the rules of an excused person.","If prayers were missed out of ignorance without formed limbs, those missed prayers must be made up as Qadha."]},{id:"f-08",titleUrdu:"خون کے مختلف رنگ اور طہارت کی حتمی علامت (قصۂ بیضاء)",titleEnglish:"Colors of Menstrual Discharge (Alwan-e-Damm) & The Purity Marker",category:"haidh",summaryUrdu:"حیض کے ایام میں سرخ کے علاوہ کالا، زرد (پیلا)، مٹیالا (خاکی)، اور سبز رنگ کا اخراج بھی حیض ہی شمار ہوتا ہے جب تک کہ مکمل سفیدی ظاہر نہ ہو۔",summaryEnglish:"During menstrual habit days, red, black, yellow, turbid (earthy/brown), and greenish discharge are all considered Haidh until pure white (Al-Qassah al-Bayda) or total dryness appears.",detailedRulingUrdu:'ام المؤمنین سیدتنا عائشہ صدیقہ رضی اللہ عنہا کی خدمت میں عورتیں روئی کے ٹکڑے بھیجتی تھیں جن پر زردی ہوتی تھی، تو آپ فرماتی تھیں: "جلدی نہ کرو جب تک کہ تم سفید دھاگہ یا سفید رطوبت (القصة البيضاء) نہ دیکھ لو"۔ فقہ حنفی میں عادت کے دنوں کے دوران اگر زرد، براؤن، خاکی یا مٹیالے رنگ کے دھبے بھی لگیں تو وہ سب حیض ہیں جب تک کہ ۱۰ دن کے اندر ہوں۔ طہارت اسی وقت مانی جائے گی جب بالکل صاف سفید رطوبت آئے یا پیڈ بالکل خشک نکلے۔',detailedRulingEnglish:'Women would send cotton pads with yellowish traces to Mother of the Believers Aisha, and she would instruct: "Do not hasten until you see the white discharge (Al-Qassah al-Bayda)." In Hanafi Fiqh, any yellow, brown, or turbid staining within habit days (up to 10 days) is legally Haidh. True purification occurs only when completely clear/white discharge appears or the hygiene pad emerges totally dry.',hanafiReference:"موطا امام مالک، باب الحیض / رد المحتار علی الدر المختار / جنتی زیور، ص ۸۱",practicalGuidelines:["ہلکے پیلے یا براؤن داغوں کو نظر انداز کر کے نماز شروع نہ کریں اگر وہ عادت کے ایام میں ہوں۔","صبح اٹھ کر یا رات سوتے وقت پیڈ کا معائنہ کریں، جب خالص سفیدی آ جائے تو سمجھیں طہر حاصل ہو گیا۔","طہر ظاہر ہوتے ہی تاخیر کے بغیر غسل کر کے نماز شروع کر دیں۔"],practicalGuidelinesEnglish:["Do not dismiss light yellow or brown spots as non-menstrual if they occur within your customary cycle days.","Inspect hygiene pads upon waking or before sleep; once pure white discharge or total dryness appears, purity is established.","Once purity is confirmed, perform Ghusl without unnecessary delay and resume obligatory prayers."]},{id:"f-09",titleUrdu:"عورت کے غسل میں مینڈھیاں اور گندھے ہوئے بال کھولنے کا حکم",titleEnglish:"Rulings on Braided Hair During Women's Obligatory Ghusl (Naqd al-Dhafa'ir)",category:"haidh",summaryUrdu:"اگر عورت کے بال گندھے ہوئے ہوں (مینڈھیاں ہوں) تو غسل میں بالوں کو کھولنا فرض نہیں، بشرطیکہ پانی بالوں کی جڑوں تک بغیر کھولے پہنچ جائے۔",summaryEnglish:"A woman with tightly braided or plaited hair is not legally required to undo her braids for Ghusl, provided water reaches the roots of her scalp.",detailedRulingUrdu:'صحیح مسلم میں سیدتنا ام سلمہ رضی اللہ عنہا کی حدیث ہے کہ انہوں نے عرض کیا: "یا رسول اللہ! میں اپنے سر کی مینڈھیاں مضبوطی سے باندھتی ہوں، کیا غسلِ جنابت و حیض کے لیے انہیں کھولوں؟" حضور ﷺ نے فرمایا: "نہیں! تمہارے لیے یہی کافی ہے کہ تم اپنے سر پر تین لپ پانی ڈال لو اور پھر اپنے سارے جسم پر پانی بہا دو"۔ فقہ حنفی میں عورت کے لیے تخفیف ہے کہ اگر بال گندھے ہیں تو صرف جڑوں کو گیلا کرنا اور ہر بال کی جڑ تک پانی پہنچانا فرض ہے۔ ہاں اگر بال کھلے ہوئے ہوں تو ہر ایک بال کو اوپر سے نیچے تک تر کرنا فرض ہے؛ اسی طرح اگر بال اتنے سخت گندھے ہوں کہ جڑوں تک پانی نہ پہنچ سکے تو کھولنا لازم ہوگا۔',detailedRulingEnglish:'In Sahih Muslim, Sayyidatuna Umm Salamah inquired: "O Messenger of Allah, I braid my hair tightly; should I undo it for Ghusl?" The Prophet ﷺ replied: "No, it is sufficient for you to pour three handfuls of water over your head, then pour water over the rest of your body." Hanafi jurists rule this a merciful divine dispensation for women: if hair is braided, only moistening the scalp roots is obligatory. However, if hair is loose/unbraided, every single strand must be wetted completely.',hanafiReference:"صحیح مسلم، حدیث رقم ۳۳۰ / الہدایہ شرح بدایۃ المبتدی، کتاب الطہارۃ / بہارِ شریعت",practicalGuidelines:["مینڈھیاں باندھی ہوں تو سر کی جلد پر ہاتھ کی انگلیوں سے پانی کو اچھی طرح جڑوں تک پہنچائیں۔","اگر بال کھلے ہوں تو پورے بالوں کو بھگونا اور دھونا فرض ہے، ایک بال بھی سوکھا نہ رہے۔","اگر بالوں میں ایسا تیل، جیل یا ویکس ہو جس سے پانی بالوں تک نہ پہنچے تو پہلے اسے دھو کر صاف کریں۔"],practicalGuidelinesEnglish:["When hair is plaited, work water deeply into the scalp with your fingertips so all roots are soaked.","If hair is worn loose, every strand must be completely soaked from root to tip without exception.","If heavy styling wax or impenetrable oils are applied, wash them out first to ensure water penetrates."]},{id:"f-10",titleUrdu:"واٹر پروف میک اپ، نیل پالش، مصنوعی ناخن اور مہندی کے احکام",titleEnglish:"Waterproof Cosmetics, Nail Polish, Acrylic Nails & Henna in Wudu/Ghusl",category:"namaz_posture",summaryUrdu:"ایسا میک اپ، نیل پالش یا مصنوعی ناخن جو ناخن یا جلد تک پانی پہنچنے سے مانع ہو، اس کی موجودگی میں وضو اور غسل نہیں ہوتا اور نماز باطل ہو جاتی ہے۔",summaryEnglish:"Any cosmetic coating, commercial nail polish, or acrylic nails that form an impermeable barrier preventing water contact invalidates both Wudu and Ghusl.",detailedRulingUrdu:'وضو اور غسل کے ارکانِ فرضیہ میں سے ہے کہ اعضائے مغسولہ کے ہر حصے تک پانی پہنچے۔ روایتی نیل پالش، مصنوعی ایکریلک ناخن اور واٹر پروف فاؤنڈیشن جلد پر پلاسٹک جیسی پرت چڑھا دیتے ہیں جو پانی کو چھونے نہیں دیتے۔ نام نہاد "سانس لینے والی نیل پالش" کے متعلق ائمۂ فتویٰ کا فتویٰ ہے کہ چونکہ وہ مکمل اور فوری طور پر پورے ناخن تک پانی نہیں پہنچاتی، لہٰذا اس پر وضو و غسل کرنا سخت خطرناک اور نماز کو مشکوک بنانا ہے۔ اس کے برعکس قدرتی مہندی (حناء) صرف رنگ چھوڑتی ہے اور کوئی پرت نہیں بناتی، اس لیے مہندی کے ساتھ وضو اور غسل بالکل درست اور سنت ہے۔',detailedRulingEnglish:'It is a strict legal requirement of Wudu and Ghusl that water must directly touch the outer skin and nail surface. Commercial nail enamels, artificial acrylic nails, and waterproof adhesives form an impermeable barrier preventing water contact, rendering purification void. Permeable ("breathable") polishes remain contentious and unsafe for valid Salah according to conservative fatwa councils. In contrast, pure natural Henna (Mehndi) merely deposits organic color stain without forming a physical crust, making it entirely permissible and Sunnah.',hanafiReference:"فتاویٰ عالمگیری (الہندیہ)، ج ۱، کتاب الطہارۃ / فتاویٰ رضویہ، ج ۱ / بہارِ شریعت",practicalGuidelines:["وضو اور غسل سے پہلے نیل پالش ریموور سے ناخنوں کو بالکل صاف کریں۔","ہاتھوں اور پیروں پر مصنوعی ایکریلک یا جیل ناخن نماز اور غسل کی صحت کے منافی ہیں۔","خوبصورتی اور زینت کے لیے خالص قدرتی مہندی استعمال کریں جو مسنون اور شرعاً بے داغ ہے۔"],practicalGuidelinesEnglish:["Remove all nail polish completely with polish remover prior to making Wudu or Ghusl.","Avoid acrylic, plastic, or glued-on artificial nails as they prevent water contact with nail beds.","Opt for natural Henna/Mehndi for beautification, which is recommended in the Sunnah and leaves no barrier."]},{id:"f-11",titleUrdu:"مانع حمل ادویات، ہارمونل امپلانٹس اور بے قاعدہ داغوں کے احکام",titleEnglish:"Hormonal Spotting & Contraceptive Irregular Bleeding (IUDs, Pills)",category:"istihadha",summaryUrdu:'برتھ کنٹرول گولیوں یا آئی یو ڈی کی وجہ سے اگر عادت کے ایام سے ہٹ کر ہلکے داغ آئیں تو وہ "استحاضہ" ہیں، ان میں نماز اور روزہ نہیں چھوڑا جا سکتا۔',summaryEnglish:"Irregular spotting caused by contraceptive implants, pills, or IUDs outside of customary cycle days is classified as Istihadha (illness); Salah and Sawm must never be suspended.",detailedRulingUrdu:"فقہ حنفی کا زریں اصول ہے کہ حیض کے لیے عادت اور دو حیض کے درمیان کم از کم ۱۵ دن کی طہارت کی شرط ہے۔ اگر کسی خاتون نے مانع حمل تدابیر کی وجہ سے ہر چند دن بعد ایک دو قطرے خون دیکھا، جبکہ اس کے حیض کا مہینہ پورا نہیں ہوا یا عادت کے دن نہیں ہیں، تو وہ قطرے محض استحاضہ (بیماری و عارضہ) شمار ہوں گے۔ ایسی بہن ہر نماز کے لیے وضو کرے، پرائیویٹ پارٹ کو صاف کر کے نیا پیڈ لگائے اور فرض و نفل نمازیں ادا کرے۔ ان داغوں کی وجہ سے نمازیں چھوڑنا سخت گناہ کا باعث ہے۔",detailedRulingEnglish:"A fundamental canon of Hanafi jurisprudence stipulates that regular habit (Aadat) governs menses, alongside a mandatory minimum interval of 15 days of purity (Tuhr) between cycles. Spotting caused by hormonal medications, birth control pills, or intrauterine devices (IUDs) outside customary menstruation days is legally Istihadha. A sister experiencing this washes the area, applies a fresh pad, performs fresh Wudu at each prayer time, and fulfills all obligatory prayers and fasts.",hanafiReference:"رد المحتار علی الدر المختار، باب الحیض / فتاویٰ فیض الرسول / جنتی زیور",practicalGuidelines:["اپنے ہارمونل ادویات شروع کرنے کی تاریخ اور سابقہ عادت کا مکمل تقابلی ریکارڈ رکھیں۔","عادت کے علاوہ دنوں میں آنے والے ہلکے دھبوں پر نماز ہرگز قضا نہ کریں بلکہ تازہ وضو کر کے پڑھیں۔","اگر مسلسل خون بہتا رہے تو وہ معذور کے حکم میں ہے اور ہر نماز کے وقت نیا وضو کرے۔"],practicalGuidelinesEnglish:["Maintain a precise medical log of your previous natural habit vs post-medication spotting dates.","Never abandon Salah due to irregular spotting outside your normal habit; perform fresh Wudu and pray.","If continuous bleeding occurs throughout the prayer window, you carry the legal status of an excused person (Ma'dhur)."]},{id:"f-12",titleUrdu:"مخصوص ایام میں سجدۂ تلاوت، نمازِ جنازہ اور اذان کے جواب کا حکم",titleEnglish:"Sajdah-e-Tilawah, Janazah Prayer, and Adhan Answering During Menses",category:"spiritual_rhythm",summaryUrdu:"حیض کے دوران اگر عورت سجدۂ تلاوت کی آیت سنے تو پاک ہونے کے بعد بھی اس پر سجدۂ تلاوت واجب نہیں ہوتا، یہ مکمل معاف ہے۔",summaryEnglish:"Hearing an Ayah of Sajdah during menses incurs zero obligation for Sajdah-e-Tilawah even after purification; it is completely waived like prayer.",detailedRulingUrdu:"فقہ حنفی کے مطابق سجدۂ تلاوت کا وجوب اس وقت عائد ہوتا ہے جب سننے والا نماز کا اہل ہو۔ چونکہ حیض اور نفاس کے ایام میں عورت نماز کی مکلف نہیں رہتی، اس لیے اگر اس نے قرآن پاک کی سجدے والی آیت کسی قاری سے سنی یا لاؤڈ اسپیکر سے سنی، تو پاک ہونے کے بعد اس سجدے کی کوئی قضا نہیں اور نہ ہی وہ گنہگار ہوگی۔ اسی طرح نمازِ جنازہ پڑھنا بھی مخصوص ایام میں ناجائز ہے۔ البتہ اذان سن کر دل میں یا زبان سے کلماتِ اذان دہرانا اور اذان کے بعد کی مسنون دعا پڑھنا بالکل جائز اور مستحب ہے کیونکہ یہ ذکر و تسبیح ہے تلاوت نہیں۔",detailedRulingEnglish:"In Hanafi jurisprudence (Nur al-Idah & Bahar-e-Shari'at), the obligation to perform Sajdah-e-Tilawah only falls upon those legally eligible for prayer at the moment of hearing. Because a menstruating woman is legally exempt from Salah, hearing a verse of prostration incurs no Qadha or sin whatsoever once purified. Similarly, Janazah prayer is prohibited during menses. However, repeating the words of the Adhan and supplicating with the post-Adhan Du'a is permissible and rewarded, as it constitutes remembrance (Dhikr), not Quranic recitation.",hanafiReference:"نور الایضاح، فصل فی سجود التلاوۃ / بہارِ شریعت، حصہ ۴ / درِ مختار",practicalGuidelines:["حیض کے دوران سجدۂ تلاوت سننے پر پریشان نہ ہوں، اس کی قضا شریعت نے معاف فرمائی ہے۔","اذان سن کر احتراماً خاموشی اختیار کریں اور دل ہی دل میں اذان کا مسنون جواب دیں۔","اذان کے بعد کا مسنون درود اور دعا (اللهم رب هذه الدعوة التامة) پڑھ کر ثواب حاصل کریں۔"],practicalGuidelinesEnglish:["Do not be troubled when hearing an Ayah of Sajdah during menstruation; its performance is entirely waived.","Maintain quiet respect during the Adhan and repeat the sacred phrases mentally or verbally.","Recite Salawat and the post-Adhan supplication (Allahumma Rabba hadhihid-da'wah) to earn intercession."]}],h=[{id:"dua-01",titleUrdu:"نیک اور صالح اولاد کے لیے قرآنی دعا",titleEnglish:"Dua for Righteous Offspring (Prophet Zakariyya's Supplication)",titleRomanUrdu:"Nek aur Saleh Aulaad ke liye Qurani Dua",category:"pregnancy_labor",arabicText:"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ",transliteration:"Rabbi hab li min ladunka dhurriyyatan tayyibatan innaka samee'ud-du'a",translationUrdu:"اے میرے پروردگار! مجھے اپنی جناب سے پاکیزہ اولاد عطا فرما، بیشک تو ہی دعا سننے والا ہے۔",translationEnglish:"My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication.",translationRomanUrdu:"Ae mere Parwardigar! Mujhe Apni janab se pakeezah aulaad ata farma, beshak Tu hi dua sunne wala hai.",reference:"سورۃ آل عمران، آیت ۳۸",spiritualVirtueUrdu:"حضرت زکریا علیہ السلام نے بڑھاپے میں یہ دعا مانگی تو اللہ تعالیٰ نے حضرت یحییٰ علیہ السلام کی بشارت عطا فرمائی۔ حمل کے دوران روزانہ کثرت سے پڑھیں۔",spiritualVirtueEnglish:"Supplicated by Prophet Zakariyya in old age, through which Allah blessed him with Prophet Yahya. Recommended to recite abundantly during pregnancy.",spiritualVirtueRomanUrdu:"Hazrat Zakariyya (A.S.) ne burhape mein yeh dua mangi to Allah Ta'ala ne Hazrat Yahya (A.S.) ki basharat ata farmayi. Hamal ke dauran rozana kasrat se parhein."},{id:"dua-02",titleUrdu:"آنکھوں کی ٹھنڈک اور صالح گھرانے کی دعا",titleEnglish:"Dua for Family Peace & Consolation of the Eyes",titleRomanUrdu:"Aankhon ki Thandak aur Saleh Gharaney ki Dua",category:"marital_peace",arabicText:"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",transliteration:"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqeena imama",translationUrdu:"اے ہمارے رب! ہمیں ہماری بیویوں اور ہماری اولاد کی طرف سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا پیشوا بنا۔",translationEnglish:"Our Lord, grant us from among our spouses and offspring comfort to our eyes and make us an example for the righteous.",translationRomanUrdu:"Ae hamare Rab! Humein hamari biwiyon aur hamari aulaad ki taraf se aankhon ki thandak ata farma aur humein parhezgaron ka peshwa bana.",reference:"سورۃ الفرقان، آیت ۷۴",spiritualVirtueUrdu:"ہر نماز کے بعد اس دعا کو پڑھنے سے شوہر اور بیوی کے درمیان محبت اور بچوں میں اطاعت پیدا ہوتی ہے۔",spiritualVirtueEnglish:"Reciting after each prayer nurtures mutual marital compassion and instills righteousness and respect in children.",spiritualVirtueRomanUrdu:"Har namaz ke baad is dua ko parhne se shauhar aur biwi ke darmiyan mohabbat aur bachon mein itaat paida hoti hai."},{id:"dua-03",titleUrdu:"بچوں کو نظرِ بد اور شیطان سے حفاظت کی نبوی پناہ",titleEnglish:"Prophetic Protection for Children from the Evil Eye (Ayn) and Harm",titleRomanUrdu:"Bachon ko Nazar-e-Bad aur Shaitan se Hifazat ki Nabawi Panah",category:"children_protection",arabicText:"أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ",transliteration:"U'eedhukuma bi-kalimatillahi at-tammah, min kulli shaytanin wa hammah, wa min kulli 'aynin lammah",translationUrdu:"میں تم دونوں کو اللہ کے تمام و کمال کلمات کی پناہ میں دیتا ہوں، ہر شیطان اور زہریلے جانور سے، اور ہر نظر لگ جانے والی بری آنکھ سے۔",translationEnglish:"I seek protection for you both in the perfect words of Allah, from every devil and poisonous reptile, and from every evil, envious eye.",translationRomanUrdu:"Main tum dono ko Allah ke tamam o kamal kalimaat ki panah mein deta hoon, har shaitan aur zahreeley janwar se, aur har nazar lag jane wali buri aankh se.",reference:"صحیح البخاری، حدیث رقم ۳۳۷۱",spiritualVirtueUrdu:"رسول اللہ ﷺ حضرت حسن اور حضرت حسین رضی اللہ عنہما کو یہ دعا پڑھ کر دم فرمایا کرتے تھے۔ ماؤں کو چاہیے کہ روزانہ اپنے بچوں پر پڑھ کر دم کریں۔",spiritualVirtueEnglish:"The Prophet ﷺ recited this to shield Hasan and Husayn. Mothers are encouraged to recite this daily upon their children.",spiritualVirtueRomanUrdu:"Rasoolullah ﷺ Hazrat Hasan aur Hazrat Husain (R.A.) ko yeh dua parh kar dam farmaya karte the. Maaon ko chahiye ke rozana apne bachon par parh kar dam karein."},{id:"dua-04",titleUrdu:"حمل کی حفاظت اور ولادت میں آسانی کی دعا",titleEnglish:"Dua for Ease in Childbirth & Removing Hardship",titleRomanUrdu:"Hamal ki Hifazat aur Wiladat mein Asani ki Dua",category:"pregnancy_labor",arabicText:"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، رَبِّ يَسِّرْ وَلَا تُعَسِّرْ وَتَمِّمْ بِالْخَيْرِ",transliteration:"Ya Hayyu Ya Qayyumu bi-rahmatika astagheeth, Rabbi yassir wa la tu'assir wa tammim bil-khayr",translationUrdu:"اے زندہ و جاوید اور سب کو قائم رکھنے والے پروردگار! میں تیری ہی رحمت سے فریاد کرتی ہوں، اے میرے رب! آسانی فرما اور تنگی نہ کر اور بھلائی کے ساتھ مکمل فرما۔",translationEnglish:"O Ever-Living, O Self-Sustaining, by Your mercy I seek assistance. My Lord, make this easy and do not make it difficult, and complete it in goodness.",translationRomanUrdu:"Ae Zinda o Javed aur sab ko qayam rakhne wale Parwardigar! Main Teri hi rahmat se faryad karti hoon, ae mere Rab! Asani farma aur tangi na kar aur bhalai ke sath mukammal farma.",reference:"جامع الترمذی، حدیث ۳۵۲۴ / حصنِ حصین",spiritualVirtueUrdu:"دردِ زہ کے وقت اور حمل کے آخری مہینوں میں پڑھنے سے ولادت میں حیرت انگیز آسانی نصیب ہوتی ہے۔",spiritualVirtueEnglish:"Reciting during labor contractions and the final trimester brings peace and divine ease during delivery.",spiritualVirtueRomanUrdu:"Dard-e-zeh ke waqt aur hamal ke aakhri mahinon mein parhne se wiladat mein hairat-angez asani naseeb hoti hai."},{id:"dua-05",titleUrdu:"نوزائیدہ بچے کی سنتیں اور مسنون آداب",titleEnglish:"Sunnah Protocols and Rituals for the Newborn Infant",titleRomanUrdu:"Nau-zaida Bachhe ki Sunnatein aur Masnoon Adaab",category:"newborn_sunnah",arabicText:"بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ",transliteration:"Barakallahu laka fil-mawhoobi laka, wa shakarta al-wahiba, wa balagha ashuddahu, wa ruziqta birrah",translationUrdu:"اللہ تعالیٰ تمہیں اس دی ہوئی نعمت میں برکت دے، اور تم دینے والے کا شکر ادا کرو، اور بچہ اپنی جوانی کو پہنچے اور تمہیں اس کی نیکی اور خدمت نصیب ہو۔",translationEnglish:"May Allah bless you in what was granted to you, and may you be grateful to the Giver, and may the child reach maturity and you be blessed with their righteousness.",translationRomanUrdu:"Allah Ta'ala tumhein is di hui na'mat mein barkat de, aur tum dene wale ka shukr ada karo, aur bachha apni jawani ko pahunche aur tumhein uski neki aur khidmat naseeb ho.",reference:"الاذکار للامام النووی / تحفۃ المودود لابن القیم",spiritualVirtueUrdu:"ولادت کے مبارک سنت آداب: دائیں کان میں اذان اور بائیں میں اقامت، میٹھی کھجور چبا کر تالو سے لگانا (تحنیک)، ساتویں دن اچھا نام رکھنا، سر کے بال منڈوا کر بالوں کے وزن کے برابر چاندی صدقہ کرنا، اور عقیقہ کرنا۔",spiritualVirtueEnglish:"Blessed newborn Sunnah rites: Adhan in right ear, Iqamah in left ear, Tahneek with softened date, naming on 7th day, shaving head and giving equivalent silver in charity, and performing Aqeeqah.",spiritualVirtueRomanUrdu:"Wiladat ke mubarak Sunnah adaab: dayen kaan mein Azaan aur bayen mein Iqamat, meethi khajoor chaba kar talu se lagana (Tahneek), saatwen din achha naam rakhna, sar ke baal mundwa kar chandi sadqah karna, aur Aqeeqah karna."},{id:"dua-06",titleUrdu:"میاں بیوی میں محبت، الفت اور ناچاقی دور کرنے کی قرآنی دعا",titleEnglish:"Dua for Mutual Marital Love, Softening Hearts & Harmony",titleRomanUrdu:"Miyan Biwi mein Mohabbat, Ulfat aur Nachaqi Door Karne ki Qurani Dua",category:"marital_peace",arabicText:"وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَّا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ اللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُ عَزِيزٌ حَكِيمٌ",transliteration:"Wa allafa bayna quloobihim, law anfaqta ma fil-ardi jamee'an ma allafta bayna quloobihim wa lakinnallaha allafa baynahum, innahu 'Azeezun Hakeem.",translationUrdu:"اور ان کے دلوں میں الفت پیدا کر دی۔ اگر آپ زمین میں جو کچھ ہے سب خرچ کر دیتے تب بھی ان کے دلوں میں الفت نہ ڈال سکتے، لیکن اللہ نے ان کے درمیان الفت پیدا کر دی، بیشک وہ غالب، حکمت والا ہے۔",translationEnglish:"And He brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allah brought them together. Indeed, He is Exalted in Might and Wise.",translationRomanUrdu:"Aur un ke dilon mein ulfat paida kar di. Agar aap zameen mein jo kuch hai sab kharch kar dete tab bhi unke dilon mein ulfat na daal sakte, lekin Allah ne unke darmiyan ulfat paida kar di, beshak Woh Ghalib, Hikmat wala hai.",reference:"سورۃ الانفال، آیت ۶۳",spiritualVirtueUrdu:"میاں بیوی میں رنجش یا دوری پیدا ہو تو اس قرآنی آیت کو روزانہ ۱۱ مرتبہ پڑھ کر دعا کرنا دلوں کی سختی دور کرنے اور باہمی الفت کے لیے مجرب ہے۔",spiritualVirtueEnglish:"Recited 11 times daily to soften hearts, resolve spousal discord, and rekindle compassionate warmth in marriage.",spiritualVirtueRomanUrdu:"Miyan biwi mein ranjish ya doori paida ho to is Qurani aayat ko rozana 11 martaba parh kar dua karna dilon ki sakhti door karne aur bahami ulfat ke liye mujarrab hai."},{id:"dua-07",titleUrdu:"بچے کو دودھ پلاتے وقت برکت اور نیکی کی دعا",titleEnglish:"Supplication for Nursing Mothers: Barakah in Maternal Milk & Infant Nurture",titleRomanUrdu:"Bachhe ko Doodh Pilate Waqt Barkat aur Neki ki Dua",category:"newborn_sunnah",arabicText:"اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ، وَاجْعَلْهُ رِزْقًا طَيِّبًا وَشِفَاءً مُبَارَكًا",transliteration:"Allahumma barik lana feehi wa zidna minhu, waj'alhu rizqan tayyiban wa shifa'an mubaraka.",translationUrdu:"اے اللہ! ہمارے لیے اس دودھ میں برکت عطا فرما اور ہمیں اس میں زیادتی بخش، اور اسے پاکیزہ رزق اور بابرکت شفا بنا۔",translationEnglish:"O Allah, bless us in this milk and increase it for us, and make it wholesome sustenance and blessed healing.",translationRomanUrdu:"Ae Allah! Hamare liye is doodh mein barkat ata farma aur humein is mein zyadati bakhsh, aur ise pakeezah rizq aur ba-barkat shifa bana.",reference:"سنن ابی داؤد، حدیث ۳۷۳۰ / جامع الترمذی، حدیث ۳۴۵۵",spiritualVirtueUrdu:"رسول اللہ ﷺ نے فرمایا کہ دودھ کے علاوہ کوئی چیز ایسی نہیں جو کھانے اور پینے دونوں کی جگہ کافی ہو جائے۔ مائیں دودھ پلاتے وقت بسم اللہ کے بعد یہ دعا پڑھیں تو بچے میں برکت اور صالحیت پیدا ہوتی ہے۔",spiritualVirtueEnglish:"Prophetic prayer upon drinking milk. When recited by nursing mothers, it invites divine Barakah into the child's growth, nutrition, and righteous disposition.",spiritualVirtueRomanUrdu:"Rasoolullah ﷺ ne farmaya ke doodh ke ilawa koi cheez aisi nahi jo khane aur peene dono ki jagah kafi ho jaye. Maaen doodh pilate waqt Bismillah ke baad yeh dua parhein to bachhe mein barkat aur salihiyat paida hoti hai."},{id:"dua-08",titleUrdu:"بعد از ولادت ذہنی دباؤ، اداسی اور خوف سے پناہ کی نبوی دعا",titleEnglish:"Prophetic Solace for Postpartum Anxiety, Depression & Mental Anguish",titleRomanUrdu:"Ba'ad az Wiladat Zehni Dabao, Udasi aur Khauf se Panah ki Nabawi Dua",category:"pregnancy_labor",arabicText:"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ",transliteration:"Allahumma inni a'udhu bika minal-hammi wal-hazani, wal-'ajzi wal-kasali, wal-bukhli wal-jubni, wa dala'id-dayni wa ghalabatir-rijal.",translationUrdu:"اے اللہ! میں تیری پناہ مانگتی ہوں فکر و پریشانی اور غم سے، اور عاجزی و کمزوری اور سستی سے، اور بخل اور بزدلی سے، اور قرض کے بوجھ اور لوگوں کے دباؤ سے۔",translationEnglish:"O Allah, I seek refuge in You from anxiety and grief, from incapacity and laziness, from stinginess and cowardice, from the burden of debt, and from the overpowering of people.",translationRomanUrdu:"Ae Allah! Main Teri panah mangti hoon fikr o pareshani aur gham se, aur ajizi o kamzori aur susti se, aur bukhl aur buzdili se, aur qarz ke bojh aur logon ke dabao se.",reference:"صحیح البخاری، حدیث ۲۸۹۳",spiritualVirtueUrdu:"زچگی کے بعد ہارمونز کے عدم توازن سے پیدا ہونے والی اداسی، ڈپریشن، بے سبب رونے اور گھبراہٹ کے وقت اس دعا کا ورد دل کو گہری تسکین اور روحانی ڈھارس دیتا ہے۔",spiritualVirtueEnglish:"The premier Prophetic shield against clinical grief, postpartum anxiety, emotional depletion, and irrational fear after childbirth.",spiritualVirtueRomanUrdu:"Zachgi ke baad paida hone wale depression, be-sabab rone aur udasi ke waqt is dua ka wird dil ko gehri taskeen aur ruhani dharas deta hai."},{id:"dua-09",titleUrdu:"والدین کے حق میں رحمت اور حسنِ سلوک کی قرآنی دعا",titleEnglish:"Supplication for Aging Parents: Filial Compassion and Mercy",titleRomanUrdu:"Walidain ke Haq mein Rahmat aur Husn-e-Suluk ki Qurani Dua",category:"marital_peace",arabicText:"رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا",transliteration:"Rabbi irhamhuma kama rabbayani sagheera.",translationUrdu:"اے میرے رب! تو ان دونوں (والدین) پر رحم فرما جیسا کہ انہوں نے مجھے بچپن میں پالا اور میری پرورش کی۔",translationEnglish:"My Lord, have mercy upon them both as they raised me when I was small.",translationRomanUrdu:"Ae mere Rab! Tu un dono (walidain) par raham farma jaisa ke unhon ne mujhe bachpan mein pala aur meri parwarish ki.",reference:"سورۃ الاسراء، آیت ۲۴",spiritualVirtueUrdu:"والدین کی حیات میں ان کی خوشنودی اور وفات کے بعد ان کی مغفرت اور درجات کی بلندی کے لیے ہر فرض نماز کے بعد یہ دعا مانگنا اولاد کی اولین ذمہ داری ہے۔",spiritualVirtueEnglish:"The direct Quranic command for honoring parents. Recited after obligatory prayers to seek divine mercy upon one's mother and father in this world and the Barzakh.",spiritualVirtueRomanUrdu:"Walidain ki hayat mein unki khushnoodi aur wafaat ke baad unki maghfirat aur darjaat ki bulandi ke liye har farz namaz ke baad yeh dua mangna aulaad ki awwileen zimmedari hai."},{id:"dua-10",titleUrdu:"بیمار بچے کے بخار اور تکلیف کے وقت کی نبوی دم و شفا",titleEnglish:"Prophetic Ruqyah for Sick Children, Fever & Relieving Pain",titleRomanUrdu:"Beemar Bachhe ke Bukhar aur Takleef ke Waqt ki Nabawi Dam o Shifa",category:"children_protection",arabicText:"بِسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ، بِسْمِ اللَّهِ أَرْقِيكَ",transliteration:"Bismillahi arqeeka, min kulli shay'in yu'dheeka, min sharri kulli nafsin aw 'ayni hasidin, Allahu yashfeeka, Bismillahi arqeeka.",translationUrdu:"اللہ کے نام سے میں تجھے دم کرتی ہوں، ہر اس چیز سے جو تجھے تکلیف پہنچائے، ہر جان کے شر سے یا حسد کرنے والی آنکھ سے، اللہ تجھے شفا عطا فرمائے، اللہ کے نام سے میں تجھے دم کرتی ہوں۔",translationEnglish:"In the Name of Allah I perform Ruqyah for you, from everything that harms you, from the evil of every soul or envious eye, may Allah heal you, in the Name of Allah I perform Ruqyah for you.",translationRomanUrdu:"Allah ke naam se main tujhe dam karti hoon, har us cheez se jo tujhe takleef pahunchaye, har jaan ke shar se ya hasad karne wali aankh se, Allah tujhe shifa ata farmaye, Allah ke naam se main tujhe dam karti hoon.",reference:"صحیح مسلم، حدیث رقم ۲۱۸۶ (عن ابی سعید الخدری)",spiritualVirtueUrdu:"جب بچے کو بخار ہو، دانت نکلنے کی تکلیف ہو یا بیمار ہو، تو ماں اپنا دایاں ہاتھ بچے کے سر پر رکھ کر ۳ بار یہ دعا پڑھے۔ حضرت جبرائیل علیہ السلام نے حضور ﷺ کی عیادت کے وقت یہی مسنون دم فرمایا تھا۔",spiritualVirtueEnglish:"The authentic Ruqyah performed by Archangel Jibril upon the Prophet ﷺ. Mothers should place their right hand upon a feverish or distressed child's forehead and recite thrice.",spiritualVirtueRomanUrdu:"Jab bachhe ko bukhar ho, daant nikalne ki takleef ho ya beemar ho, to maa apna dayen haath bachhe ke sar par rakh kar 3 baar yeh dua parhe. Hazrat Jibril (A.S.) ne Huzoor ﷺ ki iyadat ke waqt yahi masnoon dam farmaya tha."}];function s(a){let e=arguments.length>1&&void 0!==arguments[1]?arguments[1]:6;if(a<3)return{status:"DEFICIENT_ISTIHADHA",statusUrdu:"خون ۳ دن سے کم رہا — یہ حیض نہیں بلکہ استحاضہ (بیماری) ہے",statusEnglish:"Bleeding less than 3 days — Classified as Istihadha, not Haidh",statusRomanUrdu:"Khoon 3 din se kam raha — Yeh haidh nahi balkey istihadha (beemari) hai",haidhDays:0,istihadhaDays:a,qadhaSalahRequired:!0,qadhaDaysCount:a,ghuslObligationUrdu:"غسلِ حیض فرض نہیں ہے، صرف وضو اور نجاست دھونا کافی ہے۔",ghuslObligationEnglish:"Menstrual Ghusl is not obligatory; standard Wudu and cleansing suffice.",ghuslObligationRomanUrdu:"Ghusl-e-Haidh farz nahi hai, sirf wuzu aur nijasat dhona kafi hai.",prayerRulingsUrdu:"چونکہ خون ۳ دن سے کم رہا اس لیے یہ حیض نہیں تھا، لہٰذا ان ".concat(a," دنوں میں جو نمازیں چھوٹی ہیں، ان کی فورا قضا پڑھنا فرض ہے۔"),prayerRulingsEnglish:"Because bleeding lasted under 72 hours, it is not Haidh. Prayers missed during these ".concat(a," days must be performed as Qadha immediately."),prayerRulingsRomanUrdu:"Chunke khoon 3 din se kam raha is liye yeh haidh nahi tha, lihaza in ".concat(a," dinon mein jo namazein chhooti hain, unki fauran qadha parhna farz hai."),fastingRulingsUrdu:"اگر ان دنوں میں روزہ چھوڑا تھا تو اس کی قضا رکھنا لازم ہے۔",fastingRulingsEnglish:"If any fasts were deferred during this time, they must be made up.",fastingRulingsRomanUrdu:"Agar in dinon mein roza chhora tha to uski qadha rakhna lazim hai.",spiritualPrescriptionUrdu:["چھوٹی ہوئی نمازوں کی قضا جلد از جلد ادا کریں۔","ہر نماز کے وقت نیا وضو کر کے نماز ادا کریں۔","خون کے داغ کو صاف پانی سے دھو کر پاک کپڑے پہنیں۔"],spiritualPrescriptionEnglish:["Perform Qadha for all prayers missed during these days as soon as possible.","Perform a fresh Wudu at the start of each obligatory prayer time.","Wash away impurity with clean water and wear fresh garments for Salah."],spiritualPrescriptionRomanUrdu:["Chhooti hui namazon ki qadha jald az jald ada karein.","Har namaz ke waqt naya wuzu kar ke namaz ada karein.","Khoon ke daagh ko saaf pani se dho kar paak kapre pehnein."],referenceText:"بہارِ شریعت، حصہ ۲، حیض کا بیان / درِ مختار"};if(a>=3&&a<=10)return{status:"VALID_HAIDH",statusUrdu:"مکمل ".concat(a," دن حیض قرار پائے (شرعی مدت کے اندر)"),statusEnglish:"Full ".concat(a," days confirmed as valid Haidh (Within canonical 3–10 day window)"),statusRomanUrdu:"Mukammal ".concat(a," din haidh qarar paye (Shar'i muddat ke andar)"),haidhDays:a,istihadhaDays:0,qadhaSalahRequired:!1,qadhaDaysCount:0,ghuslObligationUrdu:"خون رکتے ہی طہارت کا غسل فرض ہو چکا ہے، غسل کے بعد فورا نماز شروع کریں۔",ghuslObligationEnglish:"Purification Ghusl is strictly obligatory upon cessation of bleeding. Pray immediately after.",ghuslObligationRomanUrdu:"Khoon rukte hi taharah ka ghusl farz ho chuka hai, ghusl ke baad fauran namaz shuru karein.",prayerRulingsUrdu:"ان تمام ".concat(a," دنوں کی نمازیں شریعت کی طرف سے بالکل معاف ہیں، ان کی قضا پڑھنا لازم نہیں ہے۔"),prayerRulingsEnglish:"Prayers during these ".concat(a," days are entirely exempt; no Qadha is ever required."),prayerRulingsRomanUrdu:"In tamam ".concat(a," dinon ki namazein shariat ki taraf se bilkul maaf hain, inki qadha parhna lazim nahi hai."),fastingRulingsUrdu:"رمضان کے روزے اگر چھوٹے ہیں تو ان کی بعد میں ایک ایک کر کے قضا رکھنا فرض ہے۔",fastingRulingsEnglish:"Deferred Ramadan fasts must be made up individually prior to next Ramadan.",fastingRulingsRomanUrdu:"Ramadan ke rozay agar chhoote hain to unki baad mein ek ek kar ke qadha rakhna farz hai.",spiritualPrescriptionUrdu:["غسل میں کلی کرنا اور ناک میں نرم ہڈی تک پانی پہنچانا یاد رکھیں۔","پاک ہوتے ہی مصلے پر شکرانے کے ساتھ حاضر ہوں۔","مخصوص ایام کے دوران روزانہ مصلے پر بیٹھ کر درود شریف پڑھتے رہنے سے روحانی نور قائم رہتا ہے۔"],spiritualPrescriptionEnglish:["Ensure the mandatory Faraidh of Ghusl: thorough gargling and rinsing the nose up to soft bone.","Return to your prayer rug with gratitude as soon as pure.","Sitting on your prayer mat during prayer times for Salawat preserves spiritual light and intimacy."],spiritualPrescriptionRomanUrdu:["Ghusl mein kulli karna aur naak mein narm haddi tak pani pahunchana yaad rakhein.","Paak hote hi musallay par shukranay ke sath hazir hon.","Makhsoos ayyam ke dauran rozana musallay par baith kar Durood Sharif parhte rehne se ruhani noor qayam rehta hai."],referenceText:"بہارِ شریعت، حصہ ۲ / جنتی زیور، ص ۷۸"};let i=e>=3&&e<=10?e:6,r=a-i,t=a>10?a-i:0;return{status:"EXCESS_ISTIHADHA",statusUrdu:"خون ۱۰ دن سے متجاوز ہو گیا — ابتدائی ".concat(i," دن حیض اور بقیہ ").concat(r," دن استحاضہ ہیں"),statusEnglish:"Bleeding exceeded 10 days — Initial ".concat(i," days (habit) are Haidh; remaining ").concat(r," days are Istihadha"),statusRomanUrdu:"Khoon 10 din se mutajawiz ho gaya — Ibtidai ".concat(i," din haidh aur baqiya ").concat(r," din istihadha hain"),haidhDays:i,istihadhaDays:r,qadhaSalahRequired:!0,qadhaDaysCount:t,ghuslObligationUrdu:"ابتدائی ".concat(i," دن (عادت) کے مکمل ہوتے ہی غسل فرض ہو چکا تھا، اگر غسل نہیں کیا تھا تو ابھی فورا غسل کریں۔"),ghuslObligationEnglish:"Ghusl was due at the end of Day ".concat(i," (your normal habit). If not performed, take Ghusl immediately."),ghuslObligationRomanUrdu:"Ibtidai ".concat(i," din (aadat) ke mukammal hote hi ghusl farz ho chuka tha, agar ghusl nahi kiya tha to abhi fauran ghusl karein."),prayerRulingsUrdu:"چونکہ عادت سے زائد دن (".concat(i+1," سے ").concat(a," تک) استحاضہ تھے، اس لیے ان ").concat(t," دنوں میں جو نمازیں نہیں پڑھی گئیں ان کی قضا پڑھنا فرض ہے۔"),prayerRulingsEnglish:"Because days beyond your habit (Days ".concat(i+1," to ").concat(a,") were Istihadha, any prayers missed during these ").concat(t," days must be performed as Qadha."),prayerRulingsRomanUrdu:"Chunke aadat se zaid din (".concat(i+1," se ").concat(a," tak) istihadha the, is liye in ").concat(t," dinon mein jo namazein nahi parhi gayin unki qadha parhna farz hai."),fastingRulingsUrdu:"عادت کے ".concat(i," دن کے بعد والے دنوں میں روزہ رکھنا درست تھا، اگر چھوڑا تھا تو قضا رکھیں۔"),fastingRulingsEnglish:"Fasting was valid after Day ".concat(i,". If fasts were deferred during Istihadha days, perform them as Qadha."),fastingRulingsRomanUrdu:"Aadat ke ".concat(i," din ke baad wale dinon mein roza rakhna durust tha, agar chhora tha to qadha rakhein."),spiritualPrescriptionUrdu:["آئندہ کے لیے اپنی عادت کے دنوں (مثلاً ۶ یا ۷ دن) کو سختی سے یاد رکھیں۔","۱۰ دن سے زیادہ خون آنے پر عادت کے دن پورے ہوتے ہی غسل کر کے نمازیں جاری رکھیں۔","استحاضہ کے دوران ہر فرض نماز کے وقت نیا وضو کرنا معذور کے لیے ضروری ہے۔"],spiritualPrescriptionEnglish:["For future reference, strictly memorize and track your habitual days (e.g., 6 or 7 days).","If bleeding exceeds 10 days, take Ghusl as soon as habit days finish and continue praying.","During Istihadha, performing a fresh Wudu at each prayer time is mandatory for an excused sister."],spiritualPrescriptionRomanUrdu:["Ainda ke liye apni aadat ke dinon (maslan 6 ya 7 din) ko sakhti se yaad rakhein.","10 din se zyada khoon aane par aadat ke din poore hote hi ghusl kar ke namazein jari rakhein.","Istihadha ke dauran har farz namaz ke waqt naya wuzu karna ma'zoor ke liye zaroori hai."],referenceText:"بہارِ شریعت، حصہ ۲ / درِ مختار و رد المحتار"}}}}]);